51: /**
52:  * Builds the property panel for an Extend relationship.<p>
53:  *
54:  * This is a type of Relationship, but, since Relationship has no semantic
55:  *   meaning of its own, we derive directly from PropPanelModelElement (as
56:  *   other children of Relationship do).<p>
57:  *
58:  * TODO: this property panel needs refactoring to remove dependency on
59:  *       old gui components.
60:  *
61:  * @author mail@jeremybennett.com
62:  */
63: public class PropPanelExtend extends PropPanelModelElement {
64: 
65: 
66:     /**
67:      * Constructor. Builds up the various fields required.
68:      * TODO: improve the conditionfield so it can be checked and the
69:      * OCL editor can be used.
70:      */
71: 
72:     public PropPanelExtend() {
73:         super("Extend", ConfigLoader.getTabPropsOrientation());
74: 
75:         addField(Translator.localize("label.name"),
76: 		 getNameTextField());
77:         addField(Translator.localize("label.stereotype"),
78:                 getStereotypeBox());
79:         addField(Translator.localize("label.namespace"),
80: 		 getNamespaceScroll());
81: 
82:         addSeperator();
83: 
84: 
85:         // Link to the two ends. This is done as a drop down. First for the
86:         // base use case.
87:         addField(Translator.localize("label.usecase-base"),
88: 		 new UMLComboBox2(new UMLExtendBaseComboBoxModel(),
89: 				  ActionSetExtendBase.getInstance()));
90: 
91:         addField(Translator.localize("label.extension"),
92: 		 new UMLComboBox2(new UMLExtendExtensionComboBoxModel(),
93: 				  ActionSetExtendExtension.getInstance()));
94: 
95:         JList extensionPointList =
96: 	    new UMLMutableLinkedList(new UMLExtendExtensionPointListModel(),
97: 		ActionAddExtendExtensionPoint.getInstance(),
98: 		ActionNewExtendExtensionPoint.SINGLETON);
99:         addField(Translator.localize("label.extension-points"),
100: 		new JScrollPane(extensionPointList));
101: 
102:         addSeperator();
103: 
104:         UMLExpressionModel2 conditionModel =
105:             new UMLConditionExpressionModel(this, "condition");
106: 
107:         JTextArea conditionArea =
108:             new UMLExpressionBodyField(conditionModel, true);
109:         conditionArea.setRows(5);
110:         JScrollPane conditionScroll =
111:             new JScrollPane(conditionArea);
112: 
113:         addField("Condition:", conditionScroll);
114: 
115:         // Add the toolbar buttons:
116:         addButton(new PropPanelButton2(new ActionNavigateNamespace()));
117:         addButton(new PropPanelButton2(new ActionNewExtensionPoint(),
118:                 lookupIcon("ExtensionPoint")));
119:         addButton(new PropPanelButton2(new ActionNewStereotype(),
120:                 lookupIcon("Stereotype")));
121:         addButton(new PropPanelButton2(new ActionRemoveFromModel(),
122:                 lookupIcon("Delete")));
123:     }
124: 
125: 
126:     /**
127:      * Get the condition associated with the extend relationship.<p>
128:      *
129:      * The condition is actually of type {@link
130:      * ru.novosoft.uml.foundation.data_types.MBooleanExpression},
131:      * which defines both a language and a body. We are only
132:      * interested in the body, which is just a string.<p>
133:      *
134:      * @return The body of the {@link
135:      * ru.novosoft.uml.foundation.data_types.MBooleanExpression} which
136:      * is the condition associated with this extend relationship, or
137:      * <code>null</code> if there is none.
138:      */
139:     public String getCondition() {
140:         String condBody = null;
141:         Object target   = getTarget();
142: 
143:         if (ModelFacade.isAExtend(target)) {
144:             Object condition = ModelFacade.getCondition(target);
145: 
146:             if (condition != null) {
147:                 condBody = (String) ModelFacade.getBody(condition);
148:             }
149:         }
150: 
151:         return condBody;
152:     }
153: 
154: 
155:     /**
156:      * Set the condition associated with the extend relationship.<p>
157:      *
158:      * The condition is actually of type {@link
159:      * ru.novosoft.uml.foundation.data_types.MBooleanExpression},
160:      * which defines both a language and a body. We are only
161:      * interested in setting the body, which is just a string.<p>
162:      *
163:      * @param condBody  The body of the condition to associate with this
164:      *                  extend relationship.
165:      */
166:     public void setCondition(String condBody) {
167: 
168:         // Give up if we are not an extend relationship
169: 
170:         Object target = getTarget();
171: 
172:         if (!(org.argouml.model.ModelFacade.isAExtend(target))) {
173:             return;
174:         }
175: 
176:         // Set the condition body.
177: 
178:         ModelFacade.setCondition(target,
179: 				 Model.getDataTypesFactory()
180: 				     .createBooleanExpression(null, condBody));
181:     }
182: 
183: 
184:     /**
185:      * Invoked by the "ActionPerformedNewExtensionPoint" toolbar button to create a new
186:      *   extension point for this extend relationship in the same namespace as
187:      *   the current extend relationship.<p>
188:      *
189:      * This code uses getFactory and adds the extension point to
190:      *   the current extend relationship.<p>
191:      */
192:     private class ActionPerformedNewExtensionPoint
193:         extends AbstractActionNewModelElement {
194: 
195:         /**
196:          * The constructor.
197:          */
198:         public ActionPerformedNewExtensionPoint() {
199:             super("button.new-extension-point");
200:             putValue(Action.NAME,
201:                     Translator.localize("button.new-extension-point"));
202:         }
203: 
204:         /**
205:          * @see java.awt.event.ActionListener#actionPerformed(java.awt.event.ActionEvent)
206:          */
207:         public void actionPerformed(ActionEvent e) {
208:             Object target = TargetManager.getInstance().getModelTarget();
209:             if (org.argouml.model.ModelFacade.isAExtend(target)) {
210:                 Object ns = ModelFacade.getNamespace(target);
211:                 if (ns != null) {
212:                     if (ModelFacade.getBase(target) != null) {
213:                         Object extensionPoint =
214:                             Model.getUseCasesFactory()
215:                             	.buildExtensionPoint(
216:                             	        ModelFacade.getBase(target));
217:                         ModelFacade.addExtensionPoint(target, extensionPoint);
218:                         TargetManager.getInstance().setTarget(extensionPoint);
219:                         super.actionPerformed(e);
220:                     }
221:                 }
222:             }
223:         }
224:     }
225: 
226: } /* end class PropPanelExtend */
