88:   // accessors
89: 
90:   public void setOutgoingButtonEnabled(boolean b) {
91:         setOutgoingRightButtonEnabled(b);
92:         setIncomingAboveButtonEnabled(b);
93:   }
94: 
95:   public void setIncomingButtonEnabled(boolean b) {
96:         setIncomingLeftButtonEnabled(b);
97:         setOutgoingBelowButtonEnabled(b);
98:   }
99: 
100:   public void setIncomingLeftButtonEnabled(boolean b) {
101:     _showIncomingLeft = b;
102:   }
103: 
104:   public void setOutgoingRightButtonEnabled(boolean b) {
105:     _showOutgoingRight = b;
106:   }
107: 
108:    public void setIncomingAboveButtonEnabled(boolean b) {
