157:    * of the bounding box.  */
158:   public void paintButtons(Graphics g) {
159:     int cx = _content.getX();
160:     int cy = _content.getY();
161:     int cw = _content.getWidth();
162:     int ch = _content.getHeight();
163:     if (_showOutgoingRight) 
164:         paintButtonLeft(trans, g, cx + cw, cy + ch/2, 12);
165:     if (_showIncomingLeft) 
166:         paintButtonRight(trans, g, cx, cy + ch/2, 13);
167:     if (_showOutgoingBelow) 
168:         paintButtonAbove(transDown, g, cx + cw/2, cy , 14);
169:     if (_showIncomingAbove) 
170:         paintButtonBelow(transDown, g, cx+cw/2, cy + ch, 15);
171:   }
