232:   public void buttonClicked(int buttonCode) {
233:     super.buttonClicked(buttonCode);
234:     MActionState newNode =  UmlFactory.getFactory().getActivityGraphs().createActionState();
235: 
236:     FigStateVertex actionStateFig = (FigStateVertex) _content;
237:     MStateVertex existingActionState = (MStateVertex) actionStateFig.getOwner();
238: 
239:     Editor ce = Globals.curEditor();
240:     GraphModel graphModel = ce.getGraphModel();
241:     if (!(graphModel instanceof MutableGraphModel)) return;
242:     MutableGraphModel mutableGraphModel = (MutableGraphModel) graphModel;
243: 
244:     if (!mutableGraphModel.canAddNode(newNode)) return;
245:     GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
246:     LayerPerspective layerPerspective = (LayerPerspective)
247:       ce.getLayerManager().getActiveLayer();
248:     Fig newFC = renderer.getFigNodeFor(graphModel, layerPerspective, newNode);
249: 
250:     Rectangle outputRect = new Rectangle(Math.max(0, actionStateFig.getX() - 200),
251: 					 Math.max(0, actionStateFig.getY() - 200),
252: 					 actionStateFig.getWidth() + 400,
253: 					 actionStateFig.getHeight() + 400);
254:     if (buttonCode >=10 && buttonCode <= 13) {
255:             int x = 0;
256:             int y = 0; 
257:             if (buttonCode == 10) {
258:                 // superclass
259:                 x = actionStateFig.getX();
260:                 y = Math.max(0, actionStateFig.getY() - 200);
261:             }
262:             else if (buttonCode == 11) {
263:                 x = actionStateFig.getX();
264:                 y = actionStateFig.getY() + actionStateFig.getHeight() + 100;
265:             }
266:             else if (buttonCode == 12) {
267:                 x = actionStateFig.getX() + actionStateFig.getWidth() + 100;
268:                 y = actionStateFig.getY();
269:             }
270:             else if (buttonCode == 13) {
271:                 x = Math.max(0, actionStateFig.getX() - 200);
272:                 y = actionStateFig.getY();
273:                 
274:             }        
275:             // place the fig if it is not a selfassociation       
276:             if (!placeFig(newFC, layerPerspective, x, y, outputRect)) return;
277:         }
278:   
279:     ce.add(newFC);
280:     mutableGraphModel.addNode(newNode);
281: 
282:     FigPoly edgeShape = new FigPoly();
283:     Point fcCenter = actionStateFig.center();
284:     edgeShape.addPoint(fcCenter.x, fcCenter.y);
285:     Point newFCCenter = newFC.center();
286:     edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
287:     Object newEdge = null;
288:     if (buttonCode == 12) newEdge = addOutgoingTrans(mutableGraphModel, existingActionState, newNode);
289:     else if (buttonCode == 13) newEdge = addIncomingTrans(mutableGraphModel, existingActionState, newNode);
290:     else if (buttonCode == 14) newEdge = addIncomingTrans(mutableGraphModel, existingActionState, newNode);
291:     else if (buttonCode == 15) newEdge = addOutgoingTrans(mutableGraphModel, existingActionState, newNode);
292: 
293:     FigEdge fe = (FigEdge) layerPerspective.presentationFor(newEdge);
294:     edgeShape.setLineColor(Color.black);
295:     edgeShape.setFilled(false);
296:     edgeShape._isComplete = true;
297:     fe.setFig(edgeShape);
298:     ce.getSelectionManager().select(actionStateFig);
299:   }
