301:   public Object addOutgoingTrans(MutableGraphModel mgm, MStateVertex cls,
302: 			    MStateVertex newCls) {
303:     return mgm.connect(cls, newCls, MTransition.class);
304:   }
305: 
306:   public Object addIncomingTrans(MutableGraphModel mgm, MStateVertex newNode,
307: 			    MStateVertex newCls) {
308:     return mgm.connect(newCls, newNode, MTransition.class);
309:   }
