183:     public void dragHandle(int mX, int mY, int anX, int anY, Handle hand) {
184:         if (hand.index < 10) {
185:             _paintButtons = false;
186:             super.dragHandle(mX, mY, anX, anY, hand);
187:             return;
188:         }
189:         int cx = _content.getX(), cy = _content.getY();
190:         int cw = _content.getWidth(), ch = _content.getHeight();
191:         int newX = cx, newY = cy, newW = cw, newH = ch;
192:         Dimension minSize = _content.getMinimumSize();
193:         int minWidth = minSize.width, minHeight = minSize.height;
194:         Class edgeClass = null;
195:         Class nodeClass = ru.novosoft.uml.foundation.core.MClassImpl.class;
196:         int bx = mX, by = mY;
197:         boolean reverse = false;
198:         switch (hand.index) {
199:         case 10: //add superclass
200:             edgeClass = ru.novosoft.uml.foundation.core.MGeneralization.class;
201:             by = cy;
202:             bx = cx + cw/2;
203:             break;
204:         case 11: //add subclass
205:             edgeClass = ru.novosoft.uml.foundation.core.MGeneralization.class;
206:             reverse = true;
207:             by = cy + ch;
208:             bx = cx + cw/2;
209:             break;
210:         case 12: //add assoc
211:             edgeClass = ru.novosoft.uml.foundation.core.MAssociation.class;
212:             by = cy + ch/2;
213:             bx = cx + cw;
214:             break;
215:         case 13: // add assoc
216:             edgeClass = ru.novosoft.uml.foundation.core.MAssociation.class;
217:             reverse = true;
218:             by = cy + ch/2;
219:             bx = cx;
220:             break;
221:         case 14: // selfassociation
222:             // do not want to drag this
223:             break;
224:         default:
225:             cat.warn("invalid handle number");
226:             break;
227:         }
228:         if (edgeClass != null && nodeClass != null) {
229:             Editor ce = Globals.curEditor();
230:             ModeCreateEdgeAndNode m = new
231:                 ModeCreateEdgeAndNode(ce, edgeClass, nodeClass, _useComposite);
232:             m.setup((FigNode)_content, _content.getOwner(), bx, by, reverse);
233:             ce.mode(m);
234:         }
235: 
236:     }
237: 
238: 
239:     public void buttonClicked(int buttonCode) {
240:         super.buttonClicked(buttonCode);
241:         MClass newNode = UmlFactory.getFactory().getCore().createClass();
242:         FigClass fc = (FigClass) _content;
243:         MClass cls = (MClass) fc.getOwner();
244: 
245:         Editor ce = Globals.curEditor();
246:         GraphModel gm = ce.getGraphModel();
247:         if (!(gm instanceof MutableGraphModel)) return;
248:         MutableGraphModel mgm = (MutableGraphModel) gm;
249: 
250:         if (!mgm.canAddNode(newNode)) return;
251:         GraphNodeRenderer renderer = ce.getGraphNodeRenderer();
252:         LayerPerspective lay = (LayerPerspective)
253:             ce.getLayerManager().getActiveLayer();
254:         Fig newFC = renderer.getFigNodeFor(gm, lay, newNode);
255: 
256:         Rectangle outputRect = new Rectangle(Math.max(0, fc.getX() - 200),
257:                                              Math.max(0, fc.getY() - 200),
258:                                              fc.getWidth() + 400,                              
259:                                              fc.getHeight() + 400);
260:                                              
261:         
262:         // handle the case that it is not a self association
263:         if (buttonCode >=10 && buttonCode <= 13) {
264:             int x = 0;
265:             int y = 0; 
266:             if (buttonCode == 10) {
267:                 // superclass
268:                 x = fc.getX();
269:                 y = Math.max(0, fc.getY() - 200);
270:             }
271:             else if (buttonCode == 11) {
272:                 x = fc.getX();
273:                 y = fc.getY() + fc.getHeight() + 100;
274:             }
275:             else if (buttonCode == 12) {
276:                 x = fc.getX() + fc.getWidth() + 100;
277:                 y = fc.getY();
278:             }
279:             else if (buttonCode == 13) {
280:                 x = Math.max(0, fc.getX() - 200);
281:                 y = fc.getY();
282:                 
283:             }        
284:             // place the fig if it is not a selfassociation       
285:             if (!placeFig(newFC, lay, x, y, outputRect)) return;
286:         }
287:         
288:         // add the new node only if required, e.g. not when we add a 
289:         // self association
290:         if (buttonCode != 14) {
291:             ce.add(newFC);
292:             mgm.addNode(newNode);
293:         }
294:         FigPoly edgeShape = new FigPoly();
295:         if (buttonCode!=14) {
296:             Point fcCenter = fc.center();
297:             edgeShape.addPoint(fcCenter.x, fcCenter.y);
298:             Point newFCCenter = newFC.center();
299:             edgeShape.addPoint(newFCCenter.x, newFCCenter.y);
300:         }
301:         else {
302:             Point fcCenter = fc.center();
303:             Point centerRight = 
304:                 new Point((int)(fcCenter.x + fc.getSize().getWidth()/2), 
305:                           fcCenter.y);
306: 
307:             int yoffset = (int)((fc.getSize().getHeight()/2));
308:             edgeShape.addPoint(fcCenter.x, fcCenter.y);
309:             edgeShape.addPoint(centerRight.x, centerRight.y);
310:             edgeShape.addPoint(centerRight.x + 30,
311:                                centerRight.y);
312:             edgeShape.addPoint(centerRight.x + 30,
313:                                centerRight.y + yoffset);
314:             edgeShape.addPoint(centerRight.x,
315:                                centerRight.y + yoffset);
316:         }
317:         Object newEdge = null;
318:         if (buttonCode == 10) newEdge = createEdgeLeft(mgm, cls, newNode);
319:         else if (buttonCode == 11) newEdge = createEdgeRight(mgm, cls, newNode);
320:         else if (buttonCode == 12) newEdge = createEdgeRightAssoc(mgm, cls, newNode);
321:         else if (buttonCode == 13) newEdge = createEdgeLeftAssoc(mgm, cls, newNode);
322:         else if (buttonCode == 14) newEdge = createEdgeRightAssoc(mgm, cls, cls);
323: 
324:         FigEdge fe = (FigEdge) lay.presentationFor(newEdge);
325:         edgeShape.setLineColor(Color.black);
326:         edgeShape.setFilled(false);
327:         edgeShape._isComplete = true;
328:         fe.setFig(edgeShape);
329:         ce.getSelectionManager().select(fc);
330:     }
331: 
332:     public Object createEdgeLeft(MutableGraphModel mgm, MClass cls,
333:                                  MClass newCls) {
334:         return mgm.connect(cls, newCls, MGeneralization.class);
335:     }
336: 
337:     public Object createEdgeRight(MutableGraphModel mgm, MClass cls,
338:                                   MClass newCls) {
339:         return mgm.connect(newCls, cls, MGeneralization.class);
340:     }
341: 
342:     public Object createEdgeRightAssoc(MutableGraphModel mgm, MClass cls,
343:                                        MClass newCls) {
344:         return mgm.connect(cls, newCls, MAssociation.class);
345:     }
346: 
347:     public Object createEdgeLeftAssoc(MutableGraphModel mgm, MClass cls,
348:                                       MClass newCls) {
349:         return mgm.connect(newCls, cls, MAssociation.class);
350:     }
