398:     /**
399:      * The user clicked on the clarifier.
400:      *
401:      * @param x the x of the point clicked
402:      * @param y the y of the point clicked
403:      * @return the todo item clicked
404:      */
405:     public ToDoItem hitClarifier(int x, int y) {
406:         int iconPos = 25, xOff = -4, yOff = -4;
407:         Point p = new Point();
408:         ToDoList list = Designer.theDesigner().getToDoList();
409:         Vector items = list.elementsForOffender(getOwner());
410:         int size = items.size();
411:         for (int i = 0; i < size; i++) {
412:             ToDoItem item = (ToDoItem) items.elementAt(i);
413:             Icon icon = item.getClarifier();
414:             stuffPointAlongPerimeter(iconPos, p);
415:             int width = icon.getIconWidth();
416:             int height = icon.getIconHeight();
417:             if (y >= p.y + yOff
418:                 && y <= p.y + height + yOff
419:                 && x >= p.x + xOff
420:                 && x <= p.x + width + xOff)
421:                 return item;
422:             iconPos += width;
423:         }
424:         for (int i = 0; i < size; i++) {
425:             ToDoItem item = (ToDoItem) items.elementAt(i);
426:             Icon icon = item.getClarifier();
427:             if (icon instanceof Clarifier) {
428:                 ((Clarifier) icon).setFig(this);
429:                 ((Clarifier) icon).setToDoItem(item);
430:                 if (((Clarifier) icon).hit(x, y))
431:                     return item;
432:             }
433:         }
434:         items = list.elementsForOffender(this);
435:         size = items.size();
436:         for (int i = 0; i < size; i++) {
437:             ToDoItem item = (ToDoItem) items.elementAt(i);
438:             Icon icon = item.getClarifier();
439:             stuffPointAlongPerimeter(iconPos, p);
440:             int width = icon.getIconWidth();
441:             int height = icon.getIconHeight();
442:             if (y >= p.y + yOff
443:                 && y <= p.y + height + yOff
444:                 && x >= p.x + xOff
445:                 && x <= p.x + width + xOff)
446:                 return item;
447:             iconPos += width;
448:         }
449:         for (int i = 0; i < size; i++) {
450:             ToDoItem item = (ToDoItem) items.elementAt(i);
451:             Icon icon = item.getClarifier();
452:             if (icon instanceof Clarifier) {
453:                 ((Clarifier) icon).setFig(this);
454:                 ((Clarifier) icon).setToDoItem(item);
455:                 if (((Clarifier) icon).hit(x, y))
456:                     return item;
457:             }
458:         }
459:         return null;
460:     }
