523:     /**
524:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
525:      */
526:     public void propertyChange(PropertyChangeEvent pve) {
527:         Object src = pve.getSource();
528:         String pName = pve.getPropertyName();
529:         if (pve instanceof DeleteInstanceEvent && src == getOwner()) {
530:             removeFromDiagram();
531:             return;
532:         }
533:         // We handle and consume editing events
534:         if (pName.equals("editing")
535:                 && Boolean.FALSE.equals(pve.getNewValue())) {
536:             LOG.debug("finished editing");
537:             // parse the text that was edited
538:             textEdited((FigText) src);
539:             calcBounds();
540:             endTrans();
541:         } else if (pName.equals("editing")
542:                 && Boolean.TRUE.equals(pve.getNewValue())) {
543:             textEditStarted((FigText) src);
544:         } else {
545:             // Add/remove name change listeners for applied stereotypes
546:             if (src == getOwner()
547:                     && "stereotype".equals(pName)) {
548:                 if (pve instanceof RemoveAssociationEvent) {
549:                     removeElementListener(pve.getOldValue());
550:                 } else if (pve instanceof AddAssociationEvent) {
551:                     addElementListener(pve.getNewValue(), "name");
552:                 }
553:             }
554:             // Pass everything except editing events to superclass
555:             super.propertyChange(pve);
556:         }
557: 
558:         if (Model.getFacade().isAModelElement(src) 
559:                 && getOwner() != null
560:                 && !Model.getUmlFactory().isRemoved(getOwner())) {
561:             /* If the source of the event is an UML object,
562:              * then the UML model has been changed.*/
563:             modelChanged(pve);
564:         }
565:         damage();  // TODO: (MVW) Is this required?
566:         // After all these events? I doubt it...
567:     }
