974:             removeElementListener(o);
975:         }
976:         ArgoEventPump.removeListener(this);
977: 
978:         Iterator it = getPathItemFigs().iterator();
979:         while (it.hasNext()) {
980:             Fig fig = (Fig) it.next();
981:             fig.removeFromDiagram();
982:         }
983: 
984:         /* TODO: MVW: Why the next action?
985:          * Deleting a fig from 1 diagram should not influence others!
986:          * */
987:         // GEF does not take into account the multiple diagrams we have
988:         // therefore we loop through our diagrams and delete each and every
989:         // occurence on our own
990:         it = ProjectManager.getManager().getCurrentProject().getDiagrams()
991:                 .iterator();
992:         while (it.hasNext()) {
993:             ArgoDiagram diagram = (ArgoDiagram) it.next();
994:             diagram.damage();
995:         }
996: 
997:         /* TODO: MVW: Should we not call damage()
998:          * for diagrams AFTER the next step? */
999:         super.removeFromDiagram();
1000:     }
