1014:     /**
1015:      * <p>Updates the classifiers the edge is attached to.  <p>Calls a
1016:      * helper method (layoutThisToSelf) to avoid this edge
1017:      * disappearing if the new source and dest are the same node.
1018:      *
1019:      * @return boolean whether or not the update was sucessful
1020:      */
1021:     protected boolean determineFigNodes() {
1022:         Object owner = getOwner();
1023:         if (owner == null || getLayer() == null) {
1024:             LOG.error("The FigEdge has no owner or its layer is null");
1025:             return false;
1026:         }
1027: 
1028:         Object newSource = getSource();
1029:         Object newDest = getDestination();
1030: 
1031:         Fig currentSourceFig = getSourceFigNode();
1032:         Fig currentDestFig = getDestFigNode();
1033:         Object currentSource = null;
1034:         Object currentDestination = null;
1035:         if (currentSourceFig != null && currentDestFig != null) {
1036:             currentSource = currentSourceFig.getOwner();
1037:             currentDestination = currentDestFig.getOwner();
1038:         }
1039:         if (newSource != currentSource || newDest != currentDestination) {
1040:             Fig newSourceFig = getNoEdgePresentationFor(newSource);
1041:             Fig newDestFig = getNoEdgePresentationFor(newDest);
1042:             if (newSourceFig != currentSourceFig) {
1043:                 setSourceFigNode((FigNode) newSourceFig);
1044:                 setSourcePortFig(newSourceFig);
1045: 
1046:             }
1047:             if (newDestFig != currentDestFig) {
1048:                 setDestFigNode((FigNode) newDestFig);
1049:                 setDestPortFig(newDestFig);
1050:             }
1051:             ((FigNode) newSourceFig).updateEdges();
1052:             ((FigNode) newDestFig).updateEdges();
1053:             calcBounds();
1054: 
1055:             // adapted from SelectionWButtons from line 280
1056:             // calls a helper method to avoid this edge disappearing
1057:             // if the new source and dest are the same node.
1058:             if (newSourceFig == newDestFig) {
1059: 
1060:                 layoutThisToSelf();
1061:             }
1062: 
1063:         }
1064: 
1065:         return true;
1066:     }
