329:     /**
330:      * distance formula: (x-h)^2 + (y-k)^2 = distance^2
331:      *
332:      * @param p1 point
333:      * @param p2 point
334:      * @return the square of the distance
335:      */
336:     protected int getSquaredDistance(Point p1, Point p2) {
337:         int xSquared = p2.x - p1.x;
338:         xSquared *= xSquared;
339:         int ySquared = p2.y - p1.y;
340:         ySquared *= ySquared;
341:         return xSquared + ySquared;
342:     }
