1068:     /**
1069:      * A version of GEF's presentationFor() method which 
1070:      * @param element ModelElement to return presentation for
1071:      * @return the Fig representing the presentation
1072:      */
1073:     private Fig getNoEdgePresentationFor(Object element) {
1074:         if (element == null) {
1075:             throw new IllegalArgumentException("Can't search for a null owner");
1076:         }
1077:         List contents = getLayer().getContentsNoEdges();
1078:         int figCount = contents.size();
1079:         for (int figIndex = 0; figIndex < figCount; ++figIndex) {
1080:             Fig fig = (Fig) contents.get(figIndex);
1081:             if (fig.getOwner() == element) {
1082:                 return fig;
1083:             }
1084:         }
1085:         throw new IllegalStateException("Can't find a FigNode representing "
1086:                 + Model.getFacade().getName(element));
1087:     }
