1090:     /**
1091:      * helper method for determineFigNodes() in order to automatically
1092:      * layout an edge that is now from and to the same node type.
1093:      * <p>adapted from SelectionWButtons from line 280
1094:      */
1095:     private void layoutThisToSelf() {
1096: 
1097:         FigPoly edgeShape = new FigPoly();
1098:         //newFC = _content;
1099:         Point fcCenter =
1100:             new Point(getSourceFigNode().getX() / 2,
1101:                     getSourceFigNode().getY() / 2);
1102:         Point centerRight =
1103:             new Point(
1104: 		      (int) (fcCenter.x
1105: 			     + getSourceFigNode().getSize().getWidth() / 2),
1106: 		      fcCenter.y);
1107: 
1108:         int yoffset = (int) ((getSourceFigNode().getSize().getHeight() / 2));
1109:         edgeShape.addPoint(fcCenter.x, fcCenter.y);
1110:         edgeShape.addPoint(centerRight.x, centerRight.y);
1111:         edgeShape.addPoint(centerRight.x + 30, centerRight.y);
1112:         edgeShape.addPoint(centerRight.x + 30, centerRight.y + yoffset);
1113:         edgeShape.addPoint(centerRight.x, centerRight.y + yoffset);
1114: 
1115:         // place the edge on the layer and update the diagram
1116:         this.setBetweenNearestPoints(true);
1117:         edgeShape.setLineColor(Color.black);
1118:         edgeShape.setFilled(false);
1119:         edgeShape.setComplete(true);
1120:         this.setFig(edgeShape);
1121:     }
