62:     private static final int X = 10;
63:     private static final int Y = 10;
64:     private static final int W = 90;
65:     private static final int H = 25;
66:     
67:     private static final int SX = 3;
68:     private static final int SY = 3;
69:     private static final int SW = 9;
70:     private static final int SH = 5;
