85:     /**
86:      * Main Constructor (called from file loading)
87:      */
88:     public FigSubactivityState() {
89:         FigRRect bigPort = new FigRRect(X, Y, W, H, 
90:                 Color.cyan, Color.cyan);
91:         bigPort.setCornerRadius(bigPort.getHalfHeight());
92:         cover = new FigRRect(X, Y, W, H, Color.black, Color.white);
93:         cover.setCornerRadius(getHalfHeight());
94: 
95:         bigPort.setLineWidth(0);
96:         
97:         //icon = makeSubStatesIcon(X + W, Y); // the substate icon in the corner
98:         
99:         getNameFig().setLineWidth(0);
100:         getNameFig().setBounds(10 + PADDING, 10, 90 - PADDING * 2, 25);
101:         getNameFig().setFilled(false);
102:         getNameFig().setMultiLine(true);
103: 
104:         // add Figs to the FigNode in back-to-front order
105:         addFig(bigPort);
106:         addFig(cover);
107:         addFig(getNameFig());
108:         //addFig(icon);
109:         
110:         makeSubStatesIcon(X + W, Y);
111: 
112:         setBigPort(bigPort);
113:         Rectangle r = getBounds();
114:         setBounds(r.x, r.y, r.width, r.height);
115:     }
