117:     /**
118:      * @param x the x-coordinate of the right corner 
119:      * @param y the y coordinate of the bottom corner
120:      */
121:     private void makeSubStatesIcon(int x, int y) {
122:         s1 = new FigRRect(x - 22, y + 3, 8, 6, 
123:                 Color.black, Color.white);
124:         s2 = new FigRRect(x - 11, y + 9, 8, 6, 
125:                 Color.black, Color.white);
126:         s1.setFilled(true);
127:         s2.setFilled(true);
128:         s1.setLineWidth(1);
129:         s2.setLineWidth(1);
130:         s1.setCornerRadius(SH);
131:         s2.setCornerRadius(SH);
132:         s3 = new FigLine(x - 18, y + 6, x - 7, y + 12, Color.black);
133:         
134:         addFig(s3); // add them back to front
135:         addFig(s1);
136:         addFig(s2);
137:     }
