274:                                             mee.getRemovedValue(), "script");
275:                 }
276:             updateNameText();
277:             damage();
278:         } else
279:             if (ModelFacade.getEntry(getOwner()) == mee.getSource()) {
280:                 updateNameText();
281:                 damage();
282:             } 
283:         
284:     }
