185:     /**
186:      * Makes sure that the edges stick to the outline of the fig.
187:      * @see org.tigris.gef.presentation.Fig#getGravityPoints()
188:      */
189:     public Vector getGravityPoints() {
190:         Vector ret = new Vector();
191:         int cx = getFigAt(HEAD_POSN).center().x;
192:         int cy = getFigAt(HEAD_POSN).center().y;
193:         int radiusx = Math.round(getFigAt(HEAD_POSN).getWidth() / 2) + 1;
194:         int radiusy = Math.round(getFigAt(HEAD_POSN).getHeight() / 2) + 1;
195:         final int maxPoints = 20;
196:         Point point = null;
197:         for (int i = 0; i < maxPoints; i++) {
198: 	    double angle = 2 * Math.PI / maxPoints * i;
199:             point = new Point((int) (cx + Math.cos(angle) * radiusx),
200: 			      (int) (cy + Math.sin(angle) * radiusy));
201:             ret.add(point);
202:         }
203:         ret.add(new Point(getFigAt(BODY_POSN).getX(),
204:                           getFigAt(BODY_POSN).getY()));
205:         ret.add(new Point(((FigLine) getFigAt(BODY_POSN)).getX1(),
206:                           ((FigLine) getFigAt(BODY_POSN)).getY1()));
207:         ret.add(new Point(getFigAt(LEFT_LEG_POSN).getX(),
208:                           getFigAt(LEFT_LEG_POSN).getY()));
209:         ret.add(new Point(((FigLine) getFigAt(LEFT_LEG_POSN)).getX1(),
210:                           ((FigLine) getFigAt(LEFT_LEG_POSN)).getY1()));
211:         ret.add(new Point(getFigAt(RIGHT_LEG_POSN).getX(),
212:                           getFigAt(RIGHT_LEG_POSN).getY()));
213:         ret.add(new Point(((FigLine) getFigAt(RIGHT_LEG_POSN)).getX1(),
214:                           ((FigLine) getFigAt(RIGHT_LEG_POSN)).getY1()));
215:         ret.add(new Point(getFigAt(ARMS_POSN).getX(),
216:                           getFigAt(ARMS_POSN).getY()));
217:         ret.add(new Point(((FigLine) getFigAt(ARMS_POSN)).getX1(),
218:                           ((FigLine) getFigAt(ARMS_POSN)).getY1()));
219:         return ret;
220:     }
