378:     /**
379:      * @param isVisible true if the attribute compartment is visible
380:      */
381:     public void setAttributesVisible(boolean isVisible) {
382:         Rectangle rect = getBounds();
383:         int h;
384:     	if (isCheckSize()) {
385:     	    h = ((ROWHEIGHT  
386:                 * Math.max(1, getAttributesFig().getFigs(null).size() - 1) + 2)
387:                 * rect.height
388:                 / getMinimumSize().height);
389:         } else {
390:             h = 0;
391:         }
392:         if (getAttributesFig().isVisible()) {
393:             if (!isVisible) {  // hide compartment
394:                 damage();
395:                 Iterator it = getAttributesFig().getFigs(null).iterator();
396:                 while (it.hasNext()) {
397:                     ((Fig) (it.next())).setVisible(false);
398:                 }
399:                 getAttributesFig().setVisible(false);
400:                 Dimension aSize = this.getMinimumSize();
401:                 setBounds(rect.x, rect.y,
402: 			  (int) aSize.getWidth(), (int) aSize.getHeight());
403:             }
404:         } else {
405:             if (isVisible) { // show compartement
406:                 Iterator it = getAttributesFig().getFigs(null).iterator();
407:                 while (it.hasNext()) {
408:                     ((Fig) (it.next())).setVisible(true);
409:                 }
410:                 getAttributesFig().setVisible(true);
411:                 Dimension aSize = this.getMinimumSize();
412:                 setBounds(rect.x, rect.y,
413: 			  (int) aSize.getWidth(), (int) aSize.getHeight());
414:                 damage();
415:             }
416:         }
417:     }
