458:     /**
459:      * <p>Gets the minimum size permitted for a class on the diagram.</p>
460:      *
461:      * <p>Parts of this are hardcoded, notably the fact that the name
462:      *   compartment has a minimum height of 21 pixels.</p>
463:      *
464:      * @return  the size of the minimum bounding box.
465:      */
466:     public Dimension getMinimumSize() {
467: 
468:         // Use "aSize" to build up the minimum size. Start with the size of the
469:         // name compartment and build up.
470: 
471:         Dimension aSize = getNameFig().getMinimumSize();
472:         int h = aSize.height;
473:         int w = aSize.width;
474: 
475:         // Ensure that the minimum height of the name compartment is at least
476:         // 21 pixels (hardcoded).
477: 
478:         if (aSize.height < 21) {
479:             aSize.height = 21;
480:         }
481: 
482:         // If we have a stereotype displayed, then allow some space for that
483:         // (width and height)
484: 
485:         if (getStereotypeFig().isVisible()) {
486:             aSize.width =
487: 		Math.max(aSize.width,
488: 			 getStereotypeFig().getMinimumSize().width);
489:             aSize.height += STEREOHEIGHT;
490:         }
491: 
492:         // Allow space for each of the attributes we have
493: 
494:         if (getAttributesFig().isVisible()) {
495: 
496:             // Loop through all the attributes, to find the widest (remember
497:             // the first fig is the box for the whole lot, so ignore it).
498: 
499:             Iterator it = getAttributesFig().getFigs(null).iterator();
500:             it.next(); // Ignore first element
501: 
502:             while (it.hasNext()) {
503:                 int elemWidth =
504: 		    ((FigText) it.next()).getMinimumSize().width + 2;
505:                 aSize.width = Math.max(aSize.width, elemWidth);
506:             }
507: 
508:             // Height allows one row for each attribute (remember to ignore the
509:             // first element.
510: 
511:             aSize.height +=
512: 		ROWHEIGHT * Math.max(1, 
513: 		        getAttributesFig().getFigs(null).size() - 1) + 1;
514:         }
515: 
516:         // Allow space for each of the operations we have
517: 
518:         if (isOperationsVisible()) {
519: 
520:             // Loop through all the operations, to find the widest (remember
521:             // the first fig is the box for the whole lot, so ignore it).
522: 
523:             Iterator it = getOperationsFig().getFigs(null).iterator();
524:             it.next(); // ignore
525: 
526:             while (it.hasNext()) {
527:                 int elemWidth =
528: 		    ((FigText) it.next()).getMinimumSize().width + 2;
529:                 aSize.width = Math.max(aSize.width, elemWidth);
530:             }
531: 
532:             aSize.height +=
533: 		ROWHEIGHT * Math.max(1, 
534: 		        getOperationsFig().getFigs(null).size() - 1) + 1;
535:         }
536: 
537:         // we want to maintain a minimum width for the class
538:         aSize.width = Math.max(60, aSize.width);
539: 
540:         // And now aSize has the answer
541: 
542:         return aSize;
543:     }
