590:             CompartmentFigText ft = unhighlight();
591:             if (ft != null) {
592:                 int i = new Vector(getAttributesFig().getFigs(null))
593:                                             .indexOf(ft);
594:                 FigGroup fg = getAttributesFig();
595:                 if (i == -1) {
596:                     i = new Vector(getOperationsFig().getFigs(null))
597:                                             .indexOf(ft);
598:                     fg = getOperationsFig();
599:                 }
600:                 if (i != -1) {
601:                     if (key == KeyEvent.VK_UP) {
602:                         ft = (CompartmentFigText)
603: 			    getPreviousVisibleFeature(fg, ft, i);
604:                     } else {
605:                         ft = (CompartmentFigText)
606: 			    getNextVisibleFeature(fg, ft, i);
607:                     }
608:                     if (ft != null) {
609:                         ft.setHighlighted(true);
610:                         highlightedFigText = ft;
611:                         return;
612:                     }
613:                 }
614:             }
615:         } else if (key == KeyEvent.VK_ENTER && highlightedFigText != null) {
616:             highlightedFigText.startTextEditor(ke);
617:             ke.consume();
618:             return;
619:         }
620:         super.keyPressed(ke);
621:     }
