671:     /**
672:      * @param fgVec the FigGroup
673:      * @param ft    the Figtext
674:      * @param i     get the fig before fig i
675:      * @return the FigText
676:      */
677:     protected FigText getPreviousVisibleFeature(FigGroup fgVec,
678: 						FigText ft, int i) {
679:         if (fgVec == null || i < 1) {
680:             return null;
681:         }
682:         FigText ft2 = null;
683:         // TODO: come GEF V 0.12 use getFigs returning an array
684:         Vector v = new Vector(fgVec.getFigs(null));
685:         if (i >= v.size() || !((FigText) v.elementAt(i)).isVisible()) {
686:             return null;
687:         }
688:         do {
689:             i--;
690:             while (i < 1) {
691:                 fgVec = (fgVec == getAttributesFig()) 
692:                     ? getOperationsFig() 
693:                     : getAttributesFig();
694:                 v = new Vector(fgVec.getFigs(null));
