854:     /**
855:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
856:      */
857:     protected void updateStereotypeText() {
858: 
859:         Object me = /*(MModelElement)*/ getOwner();
860: 
861:         if (me == null) {
862:             return;
863:         }
864: 
865:         Rectangle rect = getBounds();
866:         Object stereo = null;
867:         if (ModelFacade.getStereotypes(me).size() > 0) {
868:             stereo = ModelFacade.getStereotypes(me).iterator().next();
869:         }
870: 
871:         if ((stereo == null)
872:                 || (ModelFacade.getName(stereo) == null)
873:                 || (ModelFacade.getName(stereo).length() == 0))	{
874: 
875:             if (getStereotypeFig().isVisible()) {
876:                 getFigAt(BLINDER_POSN).setVisible(false);
877:                 getStereotypeFig().setVisible(false);
878:                 rect.y += STEREOHEIGHT;
879:                 rect.height -= STEREOHEIGHT;
880:                 setBounds(rect.x, rect.y, rect.width, rect.height);
881:                 calcBounds();
882:             }
883:         } else {
884:             setStereotype(Notation.generateStereotype(this, stereo));
885: 
886:             if (!getStereotypeFig().isVisible()) {
887:                 getFigAt(BLINDER_POSN).setVisible(true);
888:                 getStereotypeFig().setVisible(true);
889: 
890:                 // Only adjust the stereotype height if we are not newly
891:                 // created. This gets round the problem of loading classes with
892:                 // stereotypes defined, which have the height already including
893:                 // the stereotype.
894: 
895:                 if (!newlyCreated) {
896:                     rect.y -= STEREOHEIGHT;
897:                     rect.height += STEREOHEIGHT;
898:                     setBounds(rect.x, rect.y, rect.width, rect.height);
899:                     calcBounds();
900:                 }
901:             }
902:         }
903: 
904:         // Whatever happened we are no longer newly created, so clear the
905:         // flag. Then set the bounds for the rectangle we have defined.
906:         newlyCreated = false;
907:     }
