909:     /**
910:      * <p>Sets the bounds, but the size will be at least the one returned by
911:      *   {@link #getMinimumSize()}, unless checking of size is disabled.</p>
912:      *
913:      * <p>If the required height is bigger, then the additional height is
914:      *   equally distributed among all figs (i.e. compartments), such that the
915:      *   cumulated height of all visible figs equals the demanded height<p>.
916:      *
917:      * <p>Some of this has "magic numbers" hardcoded in. In particular there is
918:      *   a knowledge that the minimum height of a name compartment is 21
919:      *   pixels.</p>
920:      *
921:      * @param x  Desired X coordinate of upper left corner
922:      *
923:      * @param y  Desired Y coordinate of upper left corner
924:      *
925:      * @param w  Desired width of the FigClass
926:      *
927:      * @param h  Desired height of the FigClass
928:      */
929:     public void setBounds(int x, int y, int w, int h) {
930: 
931:         // Save our old boundaries (needed later), and get minimum size
932:         // info. "aSize will be used to maintain a running calculation of our
933:         // size at various points.
934: 
935:         // "extra_each" is the extra height per displayed fig if requested
936:         // height is greater than minimal. "height_correction" is the height
937:         // correction due to rounded division result, will be added to the name
938:         // compartment
939: 
940:         Rectangle oldBounds = getBounds();
941:         Dimension aSize = 
942:             isCheckSize() ? getMinimumSize() : new Dimension(w, h);
943: 
944:         int newW = Math.max(w, aSize.width);
945:         int newH = h;
946: 
947:         int extraEach = 0;
948:         int heightCorrection = 0;
949: 
950:         // First compute all nessessary height data. Easy if we want less than
951:         // the minimum
952: 
953:         if (newH <= aSize.height) {
954: 
955:             // Just use the mimimum
956: 
957:             newH = aSize.height;
958: 
959:         } else {
960: 
961:             // Split the extra amongst the number of displayed compartments
962: 
963:             int displayedFigs = 1; //this is for getNameFig()
964: 
965:             if (getAttributesFig().isVisible()) {
966:                 displayedFigs++;
967:             }
968: 
969:             if (isOperationsVisible()) {
970:                 displayedFigs++;
971:             }
972: 
973:             // Calculate how much each, plus a correction to put in the name
974:             // comparment if the result is rounded
975: 
976:             extraEach = (newH - aSize.height) / displayedFigs;
977:             heightCorrection =
978: 		(newH - aSize.height) - (extraEach * displayedFigs);
979:         }
980: 
981:         // Now resize all sub-figs, including not displayed figs. Start by the
982:         // name. We override the getMinimumSize if it is less than our view (21
983:         // pixels hardcoded!). Add in the shared extra, plus in this case the
984:         // correction.
985: 
986:         int height = getNameFig().getMinimumSize().height;
987: 
988:         if (height < 21) {
989:             height = 21;
990:         }
991: 
992:         height += extraEach + heightCorrection;
993: 
994:         // Now sort out the stereotype display. If the stereotype is displayed,
995:         // move the upper boundary of the name compartment up and set new
996:         // bounds for the name and the stereotype compatments and the
997:         // stereoLineBlinder that blanks out the line between the two
998: 
999:         int currentY = y;
1000: 
1001:         if (getStereotypeFig().isVisible()) {
1002:             currentY += STEREOHEIGHT;
1003:         }
1004: 
1005:         getNameFig().setBounds(x, currentY, newW, height);
1006:         getStereotypeFig().setBounds(x, y, newW, STEREOHEIGHT + 1);
1007:         getFigAt(BLINDER_POSN).setBounds(x + 1, y + STEREOHEIGHT, newW - 2, 2);
1008: 
1009:         // Advance currentY to where the start of the attribute box is,
1010:         // remembering that it overlaps the next box by 1 pixel. Calculate the
1011:         // size of the attribute box, and update the Y pointer past it if it is
1012:         // displayed.
1013: 
1014:         currentY += height - 1; // -1 for 1 pixel overlap
1015: 
1016:         int na = (isAttributesVisible())
1017:     	    ? Math.max(1, getAttributesFig().getFigs(null).size() - 1)
1018:     	    : 0;
1019:         int no = (isOperationsVisible())
1020:     	    ? Math.max(1, getOperationsFig().getFigs(null).size() - 1)
1021:     	    : 0;
1022:         if (isCheckSize()) {
1023:             height = ROWHEIGHT * na + 2 + extraEach;
1024:         } else if (newH > currentY - y && na + no > 0) {
1025:             height = (newH + y - currentY) * na / (na + no) + 1;
1026:         } else {
1027:             height = 1;
1028:         }
1029:         aSize = updateFigGroupSize(getAttributesFig(), x, currentY, 
1030:                 newW, height);
1031: 
1032:         if (getAttributesFig().isVisible()) {
1033:             currentY += aSize.height - 1; // -1 for 1 pixel overlap
1034:         }
1035: 
1036:         // Finally update the bounds of the operations box
1037: 
1038:         aSize =
1039: 	    updateFigGroupSize(getOperationsFig(), x, currentY, 
1040:                 newW, newH + y - currentY);
1041: 
1042:         // set bounds of big box
1043: 
1044:         getBigPort().setBounds(x, y, newW, newH);
1045: 
1046:         // Now force calculation of the bounds of the figure, update the edges
1047:         // and trigger anyone who's listening to see if the "bounds" property
1048:         // has changed.
1049: 
1050:         calcBounds();
1051:         updateEdges();
1052:         firePropChange("bounds", oldBounds, getBounds());
1053:     }
