114:         body = new FigPoly(Color.black, Color.white);
115:         body.addPoint(x, y);
116:         body.addPoint(x + width - 1 - gapY, y);
117:         body.addPoint(x + width - 1, y + gapY);
118:         body.addPoint(x + width - 1, y + height - 1);
119:         body.addPoint(x, y + height - 1);
120:         body.addPoint(x, y);
121:         body.setFilled(true);
122:         body.setLineWidth(1);
123: 
124:         urCorner = new FigPoly(Color.black, Color.white);
125:         urCorner.addPoint(x + width - 1 - gapY, y);
126:         urCorner.addPoint(x + width - 1, y + gapY);
127:         urCorner.addPoint(x + width - 1 - gapY, y + gapY);
128:         urCorner.addPoint(x + width - 1 - gapY, y);
129:         urCorner.setFilled(true);
130:         urCorner.setLineWidth(1);
131: 
132:         setBigPort(new FigRect(x, y, width, height, null, null));
133:         getBigPort().setFilled(false);
134:         getBigPort().setLineWidth(0);
135: 
136:         text = new FigText(2, 2, width - 2 - gapY, height - 4, true);
137:         text.setFont(getLabelFont());
138:         text.setTextColor(Color.black);
139:         text.setMultiLine(true);
140:         text.setAllowsTab(false);
141:         // _text.setText(placeString());
142:         text.setJustification(FigText.JUSTIFY_LEFT);
143:         text.setFilled(false);
144:         text.setLineWidth(0);
145:         //_text.setLineColor(Color.white);
146: 
147:         // add Figs to the FigNode in back-to-front order
148:         addFig(getBigPort());
149:         addFig(body);
150:         addFig(urCorner);
151:         addFig(text);
152: 
153:         setBlinkPorts(false); //make port invisble unless mouse enters
154:         Rectangle r = getBounds();
155:         setBounds(r.x, r.y, r.width, r.height);
