172:     /**
173:      * Create a note for a given model element.
174:      * @deprecated as of 0.17.1 nobody should use this constructor since 
175:      * it not only constructs the fig but also the model behind it. 
176:      * That should not be done by a fig which is only a view to the model
177:      * @param element The annotated model element.
178:      */
179:     public FigComment(Object element) {
180:         this(); // Construct the figure.
181: 
182:         if (!ModelFacade.isAModelElement(element)) {
183:             throw new IllegalArgumentException();
184:         }
185: 
186: 	// Create a new Comment node.
187:         Object comment =
188: 	    UmlFactory.getFactory().getCore().createComment();
189:         setOwner(comment); // Set it as the owner of the figure.
190: 	// Tell the annotated element, that it has a comment now.
191:         ModelFacade.addComment(element, comment);
192: 
193:         // Notes in statechart diagrams need a special treatment, cause
194:         // the nodes in them don't necessary have a namespace, where
195:         // we could add the note. So I added this hack... :-(
196:         // Andreas Rueckert <a_rueckert@gmx.net>
197:         if (ModelFacade.isAStateVertex(element)) {
198: 
199: 	    // If the current target is a statechart diagram, we have to
200: 	    // check, if we are editing the diagram.
201:             ProjectBrowser pb = ProjectBrowser.getInstance(); 
202:             if (TargetManager.getInstance().getTarget() 
203:                     instanceof UMLStateDiagram) { 
204:                 StateDiagramGraphModel gm =
205: 		    (StateDiagramGraphModel)
206: 		    (((UMLStateDiagram) TargetManager.getInstance()
207: 		            .getTarget()).getGraphModel());
208: 		// We are editing, so we set the Namespace directly.
209:                 ModelFacade.setNamespace(comment, gm.getNamespace());
210:             }
211:         } else {
212: 	    // Add the comment to the same namespace as the annotated element.
213:             ModelFacade.setNamespace(comment, 
214:                     ModelFacade.getNamespace(element));
215:         }
216: 
217:         storeNote(getH()); // Set the default text for this figure type.
218:     }
