262:             if (org.argouml.model.ModelFacade.isAModelElement(getOwner())) {
263:                 Object own = /*(MModelElement)*/ getOwner();
264:                 readyToEdit = true;
265:             } else {
266:                 LOG.debug("not ready to edit note");
267:                 return;
268:             }
