310:     /**
311:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
312:      */
313:     public void propertyChange(PropertyChangeEvent pve) {
314:         Object src = pve.getSource();
315:         String pName = pve.getPropertyName();
316:         if (pName.equals("editing")
317: 	    && Boolean.FALSE.equals(pve.getNewValue()))
318: 	{
319:             try {
320:                 //parse the text that was edited
321:                 textEdited((FigText) src);
322:                 // resize the FigNode to accomodate the new text
323:                 Rectangle bbox = getBounds();
324:                 Dimension minSize = getMinimumSize();
325:                 bbox.width = Math.max(bbox.width, minSize.width);
326:                 bbox.height = Math.max(bbox.height, minSize.height);
327:                 setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
328:                 endTrans();
329:             } catch (PropertyVetoException ex) {
330:                 LOG.error("could not parse and use the text entered "
331: 			  + "in figcomment", ex);
332:             }
333:         } else
334:             super.propertyChange(pve);
