201:             ProjectBrowser pb = ProjectBrowser.getInstance(); 
202:             if (TargetManager.getInstance().getTarget() 
203:                     instanceof UMLStateDiagram) { 
204:                 StateDiagramGraphModel gm =
205: 		    (StateDiagramGraphModel)
206: 		    (((UMLStateDiagram) TargetManager.getInstance()
207: 		            .getTarget()).getGraphModel());
208: 		// We are editing, so we set the Namespace directly.
209:                 ModelFacade.setNamespace(comment, gm.getNamespace());
