154:      * The space between the 2 text figs is: PADDING.
155:      * @see org.tigris.gef.presentation.Fig#getMinimumSize()
156:      */
157:     public Dimension getMinimumSize() {
158:         Dimension tempDim = classifier.getMinimumSize();
159:         int w = tempDim.width + PADDING * 2;
160:         int h = tempDim.height + PADDING;
161:         tempDim = state.getMinimumSize();
162:         w = Math.max(w, tempDim.width + PADDING * 2);
163:         h = h + PADDING + tempDim.height + PADDING;
164: 
165:         return new Dimension(Math.max(w, WIDTH / 2), Math.max(h, HEIGHT / 2));
