178:     public void setBounds(int x, int y, int w, int h) {
179:         //if (getNameFig() == null) return;
180:         Rectangle oldBounds = getBounds();
181:         
182:         Dimension classDim = classifier.getMinimumSize();
183:         Dimension stateDim = state.getMinimumSize();
184:         /* the height of the blank space above and below the text figs: */
185:         int blank = (h - PADDING - classDim.height - stateDim.height) / 2;
186:         classifier.setBounds(x + PADDING, 
187:                 y + blank, 
188:                 w - PADDING * 2, 
189:                 classDim.height);
190:         state.setBounds(x + PADDING,
191:                 y + blank + classDim.height + PADDING,
192:                 w - PADDING * 2, 
193:                 stateDim.height);
194:         
195:         getBigPort().setBounds(x, y, w, h);
196:         cover.setBounds(x, y, w, h);
197: 
198:         calcBounds(); 
199:         updateEdges();
200:         firePropChange("bounds", oldBounds, getBounds());
201:     }
