324:     public void keyPressed(KeyEvent ke) {
325:         if (!isReadyToEdit()) {
326:             if (ModelFacade.isAModelElement(getOwner())) {
327:                 updateClassifierText();
328:                 updateStateText();
329:                 setReadyToEdit(true);
330:             } else {
331:                 //LOG.debug("not ready to edit name");
332:                 return;
333:             }
334:         }
335:         if (ke.isConsumed() || getOwner() == null) {
336:             return;
337:         }
338:         classifier.keyPressed(ke);
339:     }
