341:     /**
342:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEdited(org.tigris.gef.presentation.FigText)
343:      */
344:     protected void textEdited(FigText ft) throws PropertyVetoException {
345:         try {
346:             if (ft == classifier && this.getOwner() != null) { 
347:                 ParserDisplay.SINGLETON.parseObjectFlowState1(ft.getText(), 
348:                     this.getOwner());
349:             } else if (ft == state && this.getOwner() != null) {  
350:                 ParserDisplay.SINGLETON.parseObjectFlowState2(ft.getText(), 
351:                         this.getOwner());
352:             }
353:             ProjectBrowser.getInstance().getStatusBar().showStatus("");
354:         } catch (ParseException pe) {
355:             ProjectBrowser.getInstance().getStatusBar().showStatus(
356:                     "Input rejected: " + pe.getMessage());
357:             updateClassifierText();
358:             updateStateText();
359:         }
360:     } 
