69: /** Class to display graphics for a UML Interface in a diagram. 
70:  * 
71:  */
72: public class FigInterface extends FigNodeModelElement 
73:         implements OperationsCompartmentContainer {
74:     
75:     private static final Logger LOG = Logger.getLogger(FigInterface.class);
76: 
77:     ////////////////////////////////////////////////////////////////
78:     // constants
79: 
80:     //These are the positions of child figs inside this fig
81:     //They mst be added in the constructor in this order.
82:     private static final int BLINDER_POSN = 3;
83:     private static final int OPERATIONS_POSN = 4;
84:     
85:     ////////////////////////////////////////////////////////////////
86:     // instance variables
87: 
88:     /**
89:      * The vector of graphics for operations (if any). First one is the
90:      * rectangle for the entire operations box.<p>
91:      */
92:     private FigOperationsCompartment operVec;
93: 
94:     /**
95:      * A rectangle to blank out the line that would otherwise appear at the
96:      * bottom of the stereotype text box.<p>
97:      */
98:     private FigRect stereoLineBlinder;
99: 
100:     /**
101:      * Manages residency of an interface within a component on a deployment
102:      * diagram. Not clear why it is public, or even why it is an instance
103:      * variable (rather than local to the method).<p>
104:      */
105:     public Object resident =
106:         UmlFactory.getFactory().getCore().createElementResidence();
107: 
108:     /**
109:      * Text highlighted by mouse actions on the diagram.<p>
110:      */
111:     private CompartmentFigText highlightedFigText = null;
112: 
113:     ////////////////////////////////////////////////////////////////
114:     // constructors
115: 
116:     /**
117:      * Main constructor for a {@link FigInterface}.
118:      *
119:      * Parent {@link FigNodeModelElement} will have created the main
120:      * box {@link #getBigPort()} and its name {@link #getNameFig()}
121:      * and stereotype (@link #getStereotypeFig()}. This constructor
122:      * creates a box for the operations.<p>
123:      *
124:      * The properties of all these graphic elements are adjusted
125:      * appropriately. The main boxes are all filled and have outlines.<p>
126:      *
127:      * For reasons I don't understand the stereotype is created in a box
128:      * with lines. So we have to created a blanking rectangle to overlay the
129:      * bottom line, and avoid three compartments showing.<p>
130:      *
131:      * <em>Warning</em>. Much of the graphics positioning is hard coded. The
132:      * overall figure is placed at location (10,10). The name compartment (in
133:      * the parent {@link FigNodeModelElement} is 21 pixels high. The
134:      * stereotype compartment is created 15 pixels high in the parent, but we
135:      * change it to 19 pixels, 1 more than ({@link #STEREOHEIGHT} here. The
136:      * operations box is created at 19 pixels, 2 more than
137:      * {@link #ROWHEIGHT}.<p>
138:      *
139:      * CAUTION: This constructor (with no arguments) is the only one
140:      * that does enableSizeChecking(false), all others must set it true.
141:      * This is because this constructor is the only one called when loading
142:      * a project. In this case, the parsed size must be maintained.<p>
143:      */
144:     public FigInterface() {
145: 
146:         // Set name box. Note the upper line will be blanked out if there is
147:         // eventually a stereotype above.
148:         getNameFig().setLineWidth(1);
149:         getNameFig().setFilled(true);
150: 
151:         operVec = 
152:             new FigOperationsCompartment(10, 31 + ROWHEIGHT, 60, ROWHEIGHT + 2);
153: 
154:         // Set properties of the stereotype box. Make it 1 pixel higher than
155:         // before, so it overlaps the name box, and the blanking takes out both
156:         // lines. Initially not set to be displayed, but this will be changed
157:         // when we try to render it, if we find we have a stereotype.
158:         setStereotype(NotationHelper.getLeftGuillemot()
159: 		      + "Interface" + NotationHelper.getRightGuillemot());
160:         getStereotypeFigText().setExpandOnly(true);
161:         getStereotypeFig().setFilled(true);
162:         getStereotypeFig().setLineWidth(1);
163:         getStereotypeFigText().setEditable(false);
164:         getStereotypeFig().setHeight(STEREOHEIGHT + 1);
165:         // +1 to have 1 pixel overlap with getNameFig()
166:         getStereotypeFig().setVisible(true);
167: 
168:         // A thin rectangle to overlap the boundary line between stereotype
169:         // and name. This is just 2 pixels high, and we rely on the line
170:         // thickness, so the rectangle does not need to be filled. Whether to
171:         // display is linked to whether to display the stereotype.
172:         stereoLineBlinder =
173: 	    new FigRect(11, 10 + STEREOHEIGHT, 58, 2,
174: 			Color.white, Color.white);
175:         stereoLineBlinder.setLineWidth(1);
176:         stereoLineBlinder.setVisible(true);
177: 
178:         // Put all the bits together, suppressing bounds calculations until
179:         // we're all done for efficiency.
180:         enableSizeChecking(false);
181:         setSuppressCalcBounds(true);
182:         addFig(getBigPort());
183:         addFig(getStereotypeFig());
184:         addFig(getNameFig());
185:         addFig(stereoLineBlinder);
186:         addFig(operVec);
187:         setSuppressCalcBounds(false);
188: 
189:         // Set the bounds of the figure to the total of the above (hardcoded)
190:         enableSizeChecking(true);
191:         setBounds(10, 10, 60, 21 + ROWHEIGHT);
192:     }
193: 
194:     /**
195:      * Constructor for use if this figure is created for an
196:      * existing interface node in the metamodel.<p>
197:      *
198:      * Set the figure's name according to this node. This is used when the
199:      * user click's on 'add to diagram' in the navpane.  Don't know if this
200:      * should rather be done in one of the super classes, since similar code
201:      * is used in FigClass.java etc.  Andreas Rueckert
202:      * &lt;a_rueckert@gmx.net&gt;<p>
203:      *
204:      * @param gm   Not actually used in the current implementation
205:      *
206:      * @param node The UML object being placed.
207:      */
208:     public FigInterface(GraphModel gm, Object node) {
