353:     /**
354:      * Gets the minimum size permitted for an interface on the diagram.<p>
355:      *
356:      * Parts of this are hardcoded, notably the fact that the name
357:      * compartment has a minimum height of 21 pixels.<p>
358:      *
359:      * @return  the size of the minimum bounding box.
360:      */
361:     public Dimension getMinimumSize() {
362: 
363:         // Use "aSize" to build up the minimum size. Start with the size of the
364:         // name compartment and build up.
365: 
366:         Dimension aSize = getNameFig().getMinimumSize();
367:         if (aSize.height < 21) {
368:             aSize.height = 21;
369:         }
370: 
371:         // If we have a stereotype displayed, then allow some space for that
372:         // (width and height)
373: 
374:         if (getStereotypeFig().isVisible()) {
375:             aSize.width =
376: 		Math.max(aSize.width,
377: 			 getStereotypeFig().getMinimumSize().width);
378:             aSize.height += STEREOHEIGHT;
379:         }
380: 
381:         // Allow space for each of the operations we have
382: 
383:         if (operVec.isVisible()) {
384: 
385:             // Loop through all the operations, to find the widest (remember
386:             // the first fig is the box for the whole lot, so ignore it).
387: 
388:             Iterator it = operVec.getFigs(null).iterator();
389:             it.next(); // ignore
390: 
391:             while (it.hasNext()) {
392:                 int elemWidth =
393: 		    ((FigText) it.next()).getMinimumSize().width + 2;
394:                 aSize.width = Math.max(aSize.width, elemWidth);
395:             }
396:             aSize.height +=
397: 		ROWHEIGHT * Math.max(1, operVec.getFigs(null).size() - 1) + 1;
398:         }
399: 
400:         // we want to maintain a minimum width for Interfaces
401:         aSize.width = Math.max(60, aSize.width);
402: 
403:         // And now aSize has the answer
404: 
405:         return aSize;
406:     }
