723:     /**
724:      * Sets the bounds, but the size will be at least the one returned by
725:      * {@link #getMinimumSize()}, unless checking of size is disabled.<p>
726:      *
727:      * If the required height is bigger, then the additional height is
728:      * equally distributed among all figs (i.e. compartments), such that the
729:      * cumulated height of all visible figs equals the demanded height<p>.
730:      *
731:      * Some of this has "magic numbers" hardcoded in. In particular there is
732:      * a knowledge that the minimum height of a name compartment is 21
733:      * pixels.<p>
734:      *
735:      * @param x  Desired X coordinate of upper left corner
736:      *
737:      * @param y  Desired Y coordinate of upper left corner
738:      *
739:      * @param w  Desired width of the FigInterface
740:      *
741:      * @param h  Desired height of the FigInterface
742:      */
743:     public void setBounds(int x, int y, int w, int h) {
744: 
745:         // Save our old boundaries (needed later), and get minimum size
746:         // info. "aSize will be used to maintain a running calculation of our
747:         // size at various points.
748: 
749:         // "extraEach" is the extra height per displayed fig if requested
750:         // height is greater than minimal. "heightCorrection" is the height
751:         // correction due to rounded division result, will be added to the name
752:         // compartment
753: 
754:         Rectangle oldBounds = getBounds();
755:         Dimension aSize =
756: 	    isCheckSize() ? getMinimumSize() : new Dimension(w, h);
757: 
758:         int newW = Math.max(w, aSize.width);
759:         int newH = h;
760: 
761:         int extraEach = 0;
762:         int heightCorrection = 0;
763: 
764:         // First compute all nessessary height data. Easy if we want less than
765:         // the minimum
766: 
767:         if (newH <= aSize.height) {
768: 
769:             // Just use the mimimum
770: 
771:             newH = aSize.height;
772: 
773:         } else {
774: 
775:             // Split the extra amongst the number of displayed compartments
776: 
777:             int displayedFigs = 1; //this is for getNameFig()
778: 
779:             if (operVec.isVisible()) {
780:                 displayedFigs++;
781:             }
782: 
783:             // Calculate how much each, plus a correction to put in the name
784:             // comparment if the result is rounded
785: 
786:             extraEach = (newH - aSize.height) / displayedFigs;
787:             heightCorrection =
788: 		(newH - aSize.height) - (extraEach * displayedFigs);
789:         }
790: 
791:         // Now resize all sub-figs, including not displayed figs. Start by the
792:         // name. We override the getMinimumSize if it is less than our view (21
793:         // pixels hardcoded!). Add in the shared extra, plus in this case the
794:         // correction.
795: 
796:         int height = getNameFig().getMinimumSize().height;
797: 
798:         if (height < 21) {
799:             height = 21;
800:         }
801: 
802:         height += extraEach + heightCorrection;
803: 
804:         // Now sort out the stereotype display. If the stereotype is displayed,
805:         // move the upper boundary of the name compartment up and set new
806:         // bounds for the name and the stereotype compatments and the
807:         // stereoLineBlinder that blanks out the line between the two
808: 
809:         int currentY = y;
810: 
811:         if (getStereotypeFig().isVisible()) {
812:             currentY += STEREOHEIGHT;
813:         }
814: 
815:         getNameFig().setBounds(x, currentY, newW, height);
816:         getStereotypeFig().setBounds(x, y, newW, STEREOHEIGHT + 1);
817:         stereoLineBlinder.setBounds(x + 1, y + STEREOHEIGHT, newW - 2, 2);
818: 
819:         // Advance currentY to where the start of the attribute box is,
820:         // remembering that it overlaps the next box by 1 pixel. Calculate the
821:         // size of the attribute box, and update the Y pointer past it if it is
822:         // displayed.
823: 
824:         currentY += height - 1; // -1 for 1 pixel overlap
825: 
826:         // Finally update the bounds of the operations box
827: 
828:         aSize =
829: 	    updateFigGroupSize(operVec, x, currentY,
830: 			       newW, newH + y - currentY);
831: 
832:         // set bounds of big box
833: 
834:         getBigPort().setBounds(x, y, newW, newH);
835: 
836:         // Now force calculation of the bounds of the figure, update the edges
837:         // and trigger anyone who's listening to see if the "bounds" property
838:         // has changed.
839: 
840:         calcBounds();
841:         updateEdges();
842:         firePropChange("bounds", oldBounds, getBounds());
843:     }
844: 
845:     /**
846:      * Updates the operations box. Called from modelchanged if there is
847:      * a modelevent effecting the attributes and from renderingChanged in all
848:      * cases.
849:      */
850:     protected void updateOperations() {
851:         Object cls = /*(MClassifier)*/ getOwner();
852:         if (cls == null) {
853:             return;
854:         }
855: 
856:         Fig operPort = 
857:             ((FigOperationsCompartment) getFigAt(OPERATIONS_POSN)).getBigPort();
858:         
859:         int xpos = operPort.getX();
860:         int ypos = operPort.getY();
861:         int ocounter = 1;
862:         Collection behs = ModelFacade.getOperations(cls);
863:         if (behs != null) {
