297:     /**
298:      * Determines the direction of the message arrow. Deetermination of the 
299:      * type of arrow happens in modelchanged
300:      */
301:     protected void updateArrow() {
302:   	Object mes = getOwner(); // MMessage
303: 	if (mes == null || getLayer() == null) return;
304: 	Object sender = ModelFacade.getSender(mes); // MClassifierRole
305: 	Object receiver = ModelFacade.getReceiver(mes); // MClassifierRole
306: 	Fig senderPort = getLayer().presentationFor(sender);
307: 	Fig receiverPort = getLayer().presentationFor(receiver);
308: 	if (senderPort == null || receiverPort == null) return;
309: 	int sx = senderPort.getX();
310: 	int sy = senderPort.getY();
311: 	int rx = receiverPort.getX();
312: 	int ry = receiverPort.getY();
313: 	if (sx < rx && Math.abs(sy - ry) <= Math.abs(sx - rx)) { // east
314: 	    setArrow(2);
315: 	} else 
316: 	    if (sx > rx && Math.abs(sy - ry) <= Math.abs(sx - rx)) { // west
317: 		setArrow(3);
318: 	    } else 
319: 		if (sy < ry) { // south
320: 		    setArrow(1);
321: 		} else
322: 		    setArrow(4);
323:     }
