100:         getNameFig().setBounds(x, y, width - indentX, textH + 2);
101:         getNameFig().setJustification(FigText.JUSTIFY_LEFT);
102: 
103:         getBigPort().setFilled(false);
104:         getBigPort().setLineWidth(0);
105: 
106:         // Set properties of the stereotype box. Make it 1 pixel higher than
107:         // before, so it overlaps the name box, and the blanking takes out both
108:         // lines. Initially not set to be displayed, but this will be changed
109:         // when we try to render it, if we find we have a stereotype.
110: 
111:         getStereotypeFigText().setExpandOnly(true);
112:         getStereotypeFig().setFilled(true);
113:         getStereotypeFig().setLineWidth(1);
114:         getStereotypeFigText().setEditable(false);
115:         getStereotypeFig().setHeight(STEREOHEIGHT + 1);
116:         getStereotypeFig().setVisible(false);
117: 
118:         // A thin rectangle to overlap the boundary line between stereotype
119:         // and name. This is just 2 pixels high, and we rely on the line
120:         // thickness, so the rectangle does not need to be filled. Whether to
121:         // display is linked to whether to display the stereotype.
122: 
123:         stereoLineBlinder =
124:             new FigRect(11, 10 + STEREOHEIGHT, 58, 2, Color.white, Color.white);
125:         stereoLineBlinder.setLineWidth(1);
126:         stereoLineBlinder.setVisible(false);
127: 
128:         // Mark this as newly created. This is to get round the problem with
129:         // creating figs for loaded classes that had stereotypes. They are
130:         // saved with their dimensions INCLUDING the stereotype, but since we
131:         // pretend the stereotype is not visible, we add height the first time
132:         // we render such a class. This is a complete fudge, and really we
133:         // ought to address how class objects with stereotypes are saved. But
134:         // that will be hard work.
135: 
136:         // add Figs to the FigNode in back-to-front order
137:         addFig(getBigPort());
138:         addFig(getStereotypeFig());
139:         addFig(getNameFig());
140:         addFig(stereoLineBlinder);
141:         addFig(body);
142: 
143:         setBlinkPorts(false); //make port invisble unless mouse enters
144:         Rectangle r = getBounds();
145:         setBounds(r.x, r.y, r.width, r.height);
146:         updateEdges();
