288:             stereo = ModelFacade.getStereotypes(me).iterator().next();
289:         }
290: 
291:         /* check if stereotype is defined */
292:         if ((stereo == null)
293:                 || (ModelFacade.getName(stereo) == null)
294:                 || (ModelFacade.getName(stereo).length() == 0)) {
295:             if (getStereotypeFig().isVisible()) {
296:                 stereoLineBlinder.setVisible(false);
297:                 getStereotypeFig().setVisible(false);
298:                 //                rect.y      += STEREOHEIGHT;
