301:         } else {
302:             /* we got stereotype */
303:             setStereotype(Notation.generateStereotype(this, stereo));
304: 
305:             if (!showStereotype) {
306:                 stereoLineBlinder.setVisible(false);
307:                 getStereotypeFig().setVisible(false);
308:             } else if (!getStereotypeFig().isVisible()) {
309:                 if (showStereotype) {
310:                     stereoLineBlinder.setVisible(true);
311:                     getStereotypeFig().setVisible(true);
312: 
313:                     // Only adjust the stereotype height if we are not
314:                     // newly created. This gets round the problem of
315:                     // loading classes with stereotypes defined, which
316:                     // have the height already including the
