369:         if (getStereotypeFig().isVisible()) {
370:             aSize.width =
371: 		Math.max(aSize.width,
372: 			 getStereotypeFig().getMinimumSize().width);
373:             aSize.height += STEREOHEIGHT;
374:         }
375:         // we want at least some of the package body to be displayed
376:         aSize.height = Math.max(aSize.height, 60);
377:         // And now aSize has the answer
378:         return aSize;
379:     }
380: 
381:     /**
382:      * <p>Sets the bounds, but the size will be at least the one returned by
383:      *   {@link #getMinimumSize()}.</p>
384:      *
385:      * <p>If the required height is bigger, then the additional height is
386:      *   equally distributed among all figs (i.e. compartments), such that the
387:      *   cumulated height of all visible figs equals the demanded height<p>.
388:      *
389:      * <p>Some of this has "magic numbers" hardcoded in. In particular there is
390:      *   a knowledge that the minimum height of a name compartment is 21
391:      *   pixels.</p>
392:      *
393:      * @param xa  Desired X coordinate of upper left corner
394:      *
395:      * @param ya  Desired Y coordinate of upper left corner
396:      *
397:      * @param w  Desired width of the FigClass
398:      *
399:      * @param h  Desired height of the FigClass
400:      */
401:     public void setBounds(int xa, int ya, int w, int h) {
402:         // Save our old boundaries (needed later), and get minimum size
403:         // info. "aSize will be used to maintain a running calculation of our
404:         // size at various points.
405: 
406:         Rectangle oldBounds = getBounds();
407:         Dimension aSize = getMinimumSize();
408: 
409:         int newW = Math.max(w, aSize.width);
410:         int newH = h;
411: 
412:         // First compute all nessessary height data. Easy if we want less than
413:         // the minimum
414: 
415:         if (newH <= aSize.height) {
416:             // Just use the mimimum
417:             newH = aSize.height;
418:         }
419: 
420:         // Now resize all sub-figs, including not displayed figs. Start by the
421:         // name. We override the getMinimumSize if it is less than our view (21
422:         // pixels hardcoded!). Add in the shared extra, plus in this case the
423:         // correction.
424: 
425:         int minHeight = getNameFig().getMinimumSize().height;
426: 
427:         if (minHeight < 21) {
428:             minHeight = 21;
429:         }
430: 
431:         // Now sort out the stereotype display. If the stereotype is displayed,
432:         // move the upper boundary of the name compartment up and set new
433:         // bounds for the name and the stereotype compatments and the
434:         // stereoLineBlinder that blanks out the line between the two
435: 
436:         int currentY = ya;
437: 
438:         if (getStereotypeFig().isVisible()) {
439:             currentY += STEREOHEIGHT;
440:         }
441: 
442:         getNameFig().setBounds(xa, currentY, newW - indentX, minHeight);
443:         getStereotypeFig().setBounds(xa, ya, newW - indentX, STEREOHEIGHT + 1);
444:         stereoLineBlinder.setBounds(
445: 				     xa + 1,
446: 				     ya + STEREOHEIGHT,
447: 				     newW - 2 - indentX,
448: 				     2);
449: 
450:         // Advance currentY to where the start of the body box is,
451:         // remembering that it overlaps the next box by 1 pixel. Calculate the
452:         // size of the attribute box, and update the Y pointer past it if it is
453:         // displayed.
454: 
455:         currentY += minHeight - 1; // -1 for 1 pixel overlap
456:         body.setBounds(xa, currentY, newW, newH + ya - currentY);
457: 
458:         // set bounds of big box
459: 
460:         getBigPort().setBounds(xa, ya, newW, newH);
461: 
462:         // Now force calculation of the bounds of the figure, update the edges
463:         // and trigger anyone who's listening to see if the "bounds" property
464:         // has changed.
465: 
466:         calcBounds();
467:         updateEdges();
468:         firePropChange("bounds", oldBounds, getBounds());
469:     }
