541: 	public void mouseClicked(MouseEvent me) {
542: 
543: 	    String lsDefaultName = "main";
544: 
545: 	    if (me.getClickCount() >= 2) {
546: 		Object lPkg = /*(MPackage)*/ FigPackage.this.getOwner();
547: 		if (lPkg != null) {
548: 		    Object lNS = lPkg;
