555: 		    UMLDiagram lFirst = null;
556: 		    while (diagEnum.hasMoreElements()) {
557: 			UMLDiagram lDiagram =
558: 			    (UMLDiagram) diagEnum.nextElement();
559: 			Object lDiagramNS =
560: 			    /*(MNamespace)*/lDiagram.getNamespace();
