565: 				lFirst = lDiagram;
566: 			    }
567: 
568: 			    if (lDiagram.getName() != null
569: 				&& lDiagram.getName().startsWith(
570: 				        lsDefaultName)) {
571: 				me.consume();
572: 				super.mouseClicked(me);
573: 				TargetManager.getInstance().setTarget(lDiagram);
574: 				return;
575: 			    }
576: 			}
577: 		    } /*while*/
578: 
579: 		    /* if we get here then we didnt get the
580: 		     * default diagram*/
581: 		    if (lFirst != null) {
582: 			me.consume();
583: 			super.mouseClicked(me);
584: 
585: 			TargetManager.getInstance().setTarget(lFirst);
586: 			return;
587: 		    } else {
588: 			/* try to create a new class diagram */
589: 			me.consume();
590: 			super.mouseClicked(me);
591: 			try {
592: 			    String nameSpace;
593: 			    if (lNS != null
594: 				    && ModelFacade.getName(lNS) != null)
595: 				nameSpace = ModelFacade.getName(lNS);
596: 			    else
597: 				nameSpace = "(anon)";
598: 
599: 			    String dialogText =
600: 				"Add new class diagram to "
601: 				+ nameSpace
602: 				+ "?";
603: 			    int option =
604: 				JOptionPane.showConfirmDialog(
605: 					null,
606: 					dialogText,
607: 					"Add new class diagram?",
608: 					JOptionPane.YES_NO_OPTION);
609: 			    if (option == JOptionPane.YES_OPTION) {
610: 				ArgoDiagram lNew =
611: 				    new UMLClassDiagram(lNS);
612: 				String diagramName =
613: 				    lsDefaultName + "_" + lNew.getName();
614: 
615: 				lP.addMember(lNew);
616: 
617: 				TargetManager.getInstance().setTarget(lNew);
618: 				/* change prefix */
619: 				lNew.setName(diagramName);
620: 			    }
621: 			} catch (Exception ex) {
622: 			    LOG.error(ex);
623: 			}
624: 
625: 			return;
626: 		    } /*if new*/
627: 
628: 		} /*if package */
629: 	    } /* if doubleclicks */
630: 	    super.mouseClicked(me);
631: 	}
632:     }
