157: 	    return;
158: 	}
159: 
160: 	Rectangle oldBounds = getBounds();
161: 	getBigPort().setBounds(x , y, w , h);
162: 	cover.setBounds(x , y, w, h);
163: 
164: 	Dimension stereoDim = getStereotypeFig().getMinimumSize();
165: 	Dimension nameDim = getNameFig().getMinimumSize();
166: 	getNameFig().setBounds(x + 1, y + stereoDim.height + 1,
167: 			       w - 1, nameDim.height);
168: 	getStereotypeFig().setBounds(x + 1, y + 1, w - 2, stereoDim.height);
169: 	_x = x; _y = y; _w = w; _h = h;
170: 	firePropChange("bounds", oldBounds, getBounds());
171: 	updateEdges();
