189:     public void setEnclosingFig(Fig encloser) {
190: 	super.setEnclosingFig(encloser);
191: 
192: 	Vector figures = getEnclosedFigs();
193: 
194: 	if (getLayer() != null) {
195:             // elementOrdering(figures);
196:             Collection contents = getLayer().getContents(null);
197:             Collection bringToFrontList = new ArrayList();
198:             Iterator it = contents.iterator();
199:             while (it.hasNext()) {
200:                 Object o = it.next();
201:                 if (o instanceof FigEdgeModelElement) {
202:                     bringToFrontList.add(o);
203:                     
204:                 }
205:             }
206:             Iterator bringToFrontIter = bringToFrontList.iterator();
207:             while (bringToFrontIter.hasNext()) {
208:                 FigEdgeModelElement figEdge = 
209:                     (FigEdgeModelElement) bringToFrontIter.next();
210:                 figEdge.getLayer().bringToFront(figEdge);
211:             }
212:         }
213:     }
