217:      */
218:     protected void updateStereotypeText() {
219: 	Object me = /*(MModelElement)*/ getOwner();
220: 	if (me == null) return;
221: 	Object stereo = null;
222: 	if (ModelFacade.getStereotypes(me).size() > 0) {
223:             stereo = ModelFacade.getStereotypes(me).iterator().next();
224:         }
225: 	if (stereo == null
226: 	    || ModelFacade.getName(stereo) == null
227: 	    || ModelFacade.getName(stereo).length() == 0) {
228: 
229: 	    setStereotype("");
230: 
231: 	} else {
232: 
233: 	    setStereotype(Notation.generateStereotype(this, stereo));
234: 
235: 	}
236:     }
