71:   // contructors
72:   public PropPanelNodeInstance() {
73:     super("NodeInstance Properties");
74:     GridBagLayout gb = (GridBagLayout) getLayout();    
75:     GridBagConstraints c = new GridBagConstraints();
76:     c.fill = GridBagConstraints.BOTH;
77:     c.ipadx = 0; c.ipady = 0;
78: 
79:     // add all widgets and labels 
