82:     c.gridwidth = 1; 
83:     c.gridy = 1; 
84:     c.weightx = 0.0; 
85:     gb.setConstraints(_baseLabel, c); 
86:     add(_baseLabel); 
87:  
88:     c.weightx = 1.0; 
89:     c.gridx = 1; 
90:     c.gridy = 1; 
91:     _baseField.setMinimumSize(new Dimension(120, 20)); 
92:     gb.setConstraints(_baseField, c); 
93:     add(_baseField); 
94:     _baseField.getDocument().addDocumentListener(this); 
95:     _baseField.setFont(_stereoField.getFont()); 
96: 
97:   }
