99:   ////////////////////////////////////////////////////////////////
100:   // accessors
101: 
102: 
103:   /** Set the values to be shown in all widgets based on model */ 
104:   protected void setTargetInternal(Object t) { 
105:     super.setTargetInternal(t); 
106:     MNodeInstance noi = (MNodeInstance) t; 
107:     if (noi.getClassifiers() != null) { 
108:       String base = ""; 
109:       Collection classifiers = noi.getClassifiers(); 
110:       Iterator it = classifiers.iterator(); 
111:       while (it.hasNext()) { 
112:         Object o = it.next(); 
113:         if (o != null && (o instanceof MClassifier)) { 
114:           MClassifier cls = (MClassifier) o; 
115:           if (cls != null) { 
116:             base = cls.getName(); 
117:           } 
118:         } 
119:       } 
120:       _baseField.setText(base);         
121:     }  
122:     else { 
123:       _baseField.setText(null); 
124:     } 
125:     
126:     // set the values to be shown in all widgets based on model 
127:       validate(); 
128:   } 
129: 
130:   public void setTargetBase() {  
131:     if (_target == null) return;  
132:     if (_inChange) return; 
133:   
134:     MNodeInstance noi = (MNodeInstance) _target; 
135:     MNode classifier = new MNodeImpl();  
136:     String base = _baseField.getText(); 
137:     Collection col = noi.getClassifiers(); 
138:     if ((col != null) && (col.size()>0)) {  
139:       Iterator itcol = col.iterator();  
140:       while (itcol.hasNext()) {  
141:         MClassifier cls = (MClassifier) itcol.next();  
142:         noi.removeClassifier(cls);  
143:       }  
144:     }  
145:  
146:     Vector diagrams = ProjectBrowser.TheInstance.getProject().getDiagrams(); 
147:     GraphModel model = null; 
148:     Vector v = new Vector(); 
149:     int size = diagrams.size(); 
150:     for (int i=0; i<size; i++) { 
151:       Object o = diagrams.elementAt(i); 
152:       if (!(o instanceof Diagram)) continue; 
153:       if (o instanceof MModel) continue; 
154:       Diagram d = (Diagram) o; 
155:       model = d.getGraphModel();  
156:  
157:       if (!(model instanceof DeploymentDiagramGraphModel)) continue; 
158:         
159:       Vector nodes = model.getNodes(); 
160:       int s = nodes.size(); 
161:       for (int j=0; j<s; j++) { 
162:         MModelElement node = (MModelElement) nodes.elementAt(j); 
163:         if (node != null && (node instanceof MNodeImpl)) { 
164:           MNode mnode = (MNode) node; 
165:           if (mnode.getNamespace() != noi.getNamespace()) continue;
166:           String node_name = mnode.getName(); 
167:           if (node_name != null && (node_name.equals(base))) { 
168:             v.addElement(mnode); 
169:             noi.setClassifiers(v); 
170:             return;  
171:           }       
172:         } 
173:       } 
174:     } 
175:  
176:     classifier.setName(base); 
177:     v.addElement(classifier); 
178:     noi.setClassifiers(v); 
179:  
180:     //System.out.println("needs-more-work: baseClass = " + base);  
181:     // needs-more-work: this could involve changes to the graph model  
182:   }  
183: 
184:   ////////////////////////////////////////////////////////////////
185:   // event handling
186: 
187:   public void insertUpdate(DocumentEvent e) {
188:     super.focusLost(e);
189:     if (e.getDocument() == _baseField.getDocument()) { 
190:       setTargetBase(); 
191:     } 
192:   }
193: 
194:   public void removeUpdate(DocumentEvent e) { focusLost(e); }
195: 
196:   public void changedUpdate(DocumentEvent e) {
197:     System.out.println(getClass().getName() + " changed");
198:     // Apparently, this method is never called.
199:   }
200: 
201: 
202:   public void itemStateChanged(ItemEvent e) {
203:     Object src = e.getSource(); 
204:     // check for each widget, and update the model with new value 
205:     if (src == _baseField) { 
206:       setTargetBase();
207:     } 
208:   }
