216:   public String  getColumnName(int c) {
217:     if (c == 0) return "Description";
218:     return "XXX";
219:   }
220: 
221:   public Class getColumnClass(int c) {
222:     return String.class;
223:   }
224: 
225:   public boolean isCellEditable(int row, int col) {
226:     return col == 0;
227:   }
228: 
229:   public int getRowCount() {
230:     if (_target == null) return 0;
231:     Vector extPts = new Vector(_target.getExtensionPoints());
232:     if (extPts == null) return 0;
233:     return extPts.size() + 1;
234:   }
235: 
236:   public Object getValueAt(int row, int col) {
237:     Vector extPts = new Vector(_target.getExtensionPoints());
238:     if (extPts == null) return "no extension points";
239:     if (row == extPts.size()) return ""; // blank line allows adding
240:     String ext = (String) extPts.elementAt(row);
241:     if (col == 0) return ext;
242:     else return "UC-" + row*2+col; // for debugging
243:   }
244: 
245:   public void setValueAt(Object aValue, int rowIndex, int columnIndex)  {
246:     //System.out.println("setting table value " + rowIndex + ", " + columnIndex);
247:     if (columnIndex != 0) return;
248:     if (!(aValue instanceof String)) return;
249:     String val = (String) aValue;
250:     Vector extPts = new Vector(_target.getExtensionPoints());
251:     if (rowIndex >= extPts.size()) {
252:       extPts.addElement(val);
253:       fireTableStructureChanged();
254:       _panel.resizeColumns();
255:     }
256:     else if (val.equals("")) {
257:       extPts.removeElementAt(rowIndex);
258:       fireTableStructureChanged();
259:       _panel.resizeColumns();
260:     }
261:     else extPts.setElementAt(val, rowIndex);
262:   }
