164:   protected void setTargetInternal(Object t) {
165:     super.setTargetInternal(t);
166:     MAttribute attr = (MAttribute) t;
167: 
168:     Vector offeredTypes = getOfferedTypes();
169:     if (offeredTypes != null)
170:       _typeField.setModel(new DefaultComboBoxModel(Converter.convert(offeredTypes)));
171: 
172:     MVisibilityKind vk = attr.getVisibility();
173: 	if (vk != null)
174: 		_visField.setSelectedItem(vk.getName());
175: 
176:     MScopeKind sk = attr.getOwnerScope();
177:     MChangeableKind ck = attr.getChangeability();
178: 
179:     if (MScopeKind.CLASSIFIER.equals(sk) && MChangeableKind.FROZEN.equals(ck))
180:       _keywordsField.setSelectedItem("static final");
181:     else if (MScopeKind.CLASSIFIER.equals(sk))
182:       _keywordsField.setSelectedItem("static");
183:     else if (MChangeableKind.FROZEN.equals(ck))
184:       _keywordsField.setSelectedItem("final");
185:     else
186:       _keywordsField.setSelectedItem("None");
187: 
188:     MClassifier type = attr.getType();
189:     if (type.getName() != null)
190: 	_typeField.setSelectedItem(type.getName());
191: 
192:     MExpression expr = attr.getInitialValue();
193:     if (expr == null) _initText.setText("");
194:     else _initText.setText(expr.getBody());
195: 
196:   }
