200:   public void setTargetVisibility() {
201:     if (_target == null) return;
202:     if (_inChange) return;
203:     MVisibilityKind vk = MVisibilityKind.forName((String)_visField.getSelectedItem());
204:     MAttribute attr = (MAttribute) _target;
205: 	attr.setVisibility(vk);
206:   }
207: 
208:   public void setTargetKeywords() {
209:     if (_target == null) return;
210:     if (_inChange) return;
211:     String keys = (String) _keywordsField.getSelectedItem();
212:     if (keys == null) {
213:       //System.out.println("keywords are null");
214:       return;
215:     }
216:     MAttribute attr = (MAttribute) _target;
217: 	if (keys.equals("None")) {
218: 		attr.setOwnerScope(MScopeKind.INSTANCE);
219: 		attr.setChangeability(null);
220: 	}
221: 	else if (keys.equals("transient")) {
222: 		System.out.println("needs-more-work: setting to transient...");
223: 		attr.setOwnerScope(MScopeKind.INSTANCE);
224: 		attr.setChangeability(null);
225: 	}
226: 	else if (keys.equals("static")) {
227: 		attr.setOwnerScope(MScopeKind.CLASSIFIER);
228: 		attr.setChangeability(null);
229: 	}
230: 	else if (keys.equals("final")) {
231: 		attr.setOwnerScope(MScopeKind.INSTANCE);
232: 		attr.setChangeability(MChangeableKind.FROZEN);
233: 	}
234: 	else if (keys.equals("static final")) {
235: 		attr.setOwnerScope(MScopeKind.CLASSIFIER);
236: 		attr.setChangeability(MChangeableKind.FROZEN);
237: 	}
238:   }
