240:   public void setTargetType() {
241:     if (!(_target instanceof MAttribute)) return;
242:     if (_inChange) return;
243:     MAttribute attr = (MAttribute) _target;
244:     Object sel = _typeField.getSelectedItem();
245:     if (sel == null) return;
246:     // System.out.println("set target type: " + sel);
247:     Project p = ProjectBrowser.TheInstance.getProject();
248:     MClassifier type = p.findType((String)sel);
249: 
250:     if (type == null) {
251: 	System.out.println("should not be here!");
252: 	type = new MClassifierImpl();
253: 	type.setName(sel.toString());
254:     }
255:     attr.setType(type);
256:   }
