181: class ActivityTableModelInternalTrans extends AbstractTableModel
182: implements VetoableChangeListener, DelayedVChangeListener, MElementListener {
183: 
184:   ////////////////
185:   // instance varables
186:   MActionState _target;
187:   PropPanelActionState _panel;
188: 
189:   ////////////////
190:   // constructor
191:   public ActivityTableModelInternalTrans(PropPanelActionState p) { _panel = p; }
192: 
193:   ////////////////
194:   // accessors
195:   public void setTarget(MActionState s) {
196:     if (_target instanceof MElementImpl)
197:       ((MModelElementImpl)_target).removeMElementListener(this);
198:     _target = s;
199:     if (_target instanceof MElementImpl)
200:       ((MModelElementImpl)_target).addMElementListener(this);
201:     fireTableStructureChanged();
202:     _panel.resizeColumns();
203:   }
204: 
205:   ////////////////
206:   // TableModel implemetation
207:   public int getColumnCount() { return 1; }
208: 
209:   public String  getColumnName(int c) {
210:     if (c == 0) return "Description";
211:     return "XXX";
212:   }
213: 
214:   public Class getColumnClass(int c) {
215:     return String.class;
216:   }
217: 
218:   public boolean isCellEditable(int row, int col) {
219:     return col == 0;
220:   }
221: 
222:   public int getRowCount() {
223:     if (_target == null) return 0;
224:     Vector trans = new Vector(_target.getInternalTransitions());
225:     if (trans == null) return 1;
226:     return trans.size() + 1;
227:   }
228: 
229:   public Object getValueAt(int row, int col) {
230:     Vector trans = new Vector(_target.getInternalTransitions());
231:     if (trans == null) return "";
232:     if (row >= trans.size()) return ""; // blank line allows adding
233:     MTransition t = (MTransition) trans.elementAt(row);
234:     String tStr = GeneratorDisplay.Generate(t);
235:     if (col == 0) return tStr;
236:     else return "UC-" + row*2+col; // for debugging
237:   }
238: 
239:   public void setValueAt(Object aValue, int rowIndex, int columnIndex)  {
240:    //System.out.println("setting table value " + rowIndex + ", " + columnIndex);
241:     if (columnIndex != 0) return;
242:     if (!(aValue instanceof String)) return;
243:     String val = (String) aValue;
244:     val = val.trim();
245:     Vector trans = new Vector(((MActionState)_target).getInternalTransitions());
246:     if (trans == null) trans = new Vector();
247:     MTransition newTrans = ParserDisplay.SINGLETON.parseTransition(val);
248:     if (newTrans != null) {
249: 	MActionState st = (MActionState) _target;
250: 	newTrans.setSource(st);
251: 	newTrans.setTarget(st);
252: 	newTrans.setStateMachine(st.getStateMachine());
253: 	//newTrans.setState(st);
254:     }
255:     else {
256:       System.out.println("newTrans is null!");
257:       fireTableStructureChanged();
258:       _panel.resizeColumns();
259:       return;
260:     }
261: 
262:     if (rowIndex == trans.size()) trans.addElement(newTrans);
263:     else if (val.equals("")) trans.removeElementAt(rowIndex);
264:     else trans.setElementAt(newTrans, rowIndex);
265: 
266:     ((MActionState)_target).setInternalTransitions(trans);
267: 
268:     fireTableStructureChanged();
269:     _panel.resizeColumns();
270:   }
