229: 	}
230: 	else if (keys.equals("static final")) {
231: 		oper.setOwnerScope(MScopeKind.INSTANCE);
232: 		oper.setConcurrency(MCallConcurrencyKind.CONCURRENT);
233: 	}
234: 	else if (keys.equals("synchronized")) {
235: 		oper.setOwnerScope(MScopeKind.INSTANCE);
236: 		oper.setConcurrency(MCallConcurrencyKind.GUARDED);
237: 	}
238: 	else if (keys.equals("static synchronized")) {
239: 		oper.setOwnerScope(MScopeKind.CLASSIFIER);
240: 		oper.setConcurrency(MCallConcurrencyKind.GUARDED);
241: 	}
242: 	else if (keys.equals("final synchronized")) {
243: 		oper.setOwnerScope(MScopeKind.INSTANCE);
244: 		oper.setConcurrency(MCallConcurrencyKind.GUARDED);
245: 	}
246: 	else if (keys.equals("static final synchronized")) {
247: 		oper.setOwnerScope(MScopeKind.CLASSIFIER);
248: 		oper.setConcurrency(MCallConcurrencyKind.GUARDED);
249: 	}
