51: /** Class to display graphics for a UML collaboration in a diagram. */
52: 
53: public class FigMessage extends FigNodeModelElement {
54: 
55:   ////////////////////////////////////////////////////////////////
56:   // constants
57:   public int PADDING = 5;
58:   public static Vector ARROW_DIRECTIONS = new Vector();
59: 
60:   ////////////////////////////////////////////////////////////////
61:   // instance variables
62: 
63:   protected FigPoly _figPoly;
64:   protected int _arrowDirection = 0;
65:   //protected Polygon _polygon;
66: 
67:   ////////////////////////////////////////////////////////////////
68:   // constructors
69: 
70:   public FigMessage() {
71:     _name.setLineWidth(0);
72:     _name.setMultiLine(true);
73:     _name.setFilled(false);
74:     Dimension nameMin = _name.getMinimumSize();
75:     _name.setBounds(10, 10, 90, nameMin.height);
76: 
77:     _figPoly = new FigPoly(Color.black, Color.black);
78:     int[] xpoints = {75,75,77,75,73,75};
79:     int[] ypoints = {33,24,24,15,24,24};
80:     Polygon polygon = new Polygon(xpoints, ypoints, 6);
81:     _figPoly.setPolygon(polygon);
82:     _figPoly.setBounds(100,10,5,18);
83: 
84:     ARROW_DIRECTIONS.addElement("North");
85:     ARROW_DIRECTIONS.addElement("South");
86:     ARROW_DIRECTIONS.addElement("East");
87:     ARROW_DIRECTIONS.addElement("West");
88: 
89:     // add Figs to the FigNode in back-to-front order
90:     addFig(_name);
91:     addFig(_figPoly);
92: 
93:     Rectangle r = getBounds();
94:     setBounds(r.x, r.y, r.width, r.height);
95:   }
96: 
97:   public FigMessage(GraphModel gm, Layer lay, Object node) {
98:     this();
99:     setLayer(lay);
100:     setOwner(node);
101:   }
102: 
103:   public String placeString() { return "new Message"; }
104: 
105:   public Object clone() {
106:     FigMessage figClone = (FigMessage) super.clone();
107:     Vector v = figClone.getFigs();
108:     figClone._name = (FigText) v.elementAt(0);
109:     figClone._figPoly = (FigPoly) v.elementAt(1);
110:     //figClone._polygon = (Polygon) _polygon.clone();
111:     return figClone;
112:   }
113: 
114: 
115: 
116:   ////////////////////////////////////////////////////////////////
117:   // Fig accessors
118: 
119:   public void setLineColor(Color col) {
120:     _figPoly.setLineColor(col);
121:     _name.setLineColor(col);
122:   }
123:   public Color getLineColor() { return _figPoly.getLineColor(); }
124: 
125:   public void setFillColor(Color col) {
126:     _figPoly.setFillColor(col);
127:     _name.setFillColor(col);
128:   }
129:   public Color getFillColor() { return _figPoly.getFillColor(); }
130: 
131:   public void setFilled(boolean f) {  }
132:   public boolean getFilled() { return true; }
133: 
134:   public void setLineWidth(int w) { _figPoly.setLineWidth(w); }
135:   public int getLineWidth() { return _figPoly.getLineWidth(); }
136: 
137:   public void setArrow(int direction) {
138:     Rectangle bbox = getBounds();
139:     
140:     _arrowDirection = direction;
141:     switch (direction) {
142:       // south
143:       case 1: {
144:         int[] xpoints = {75,75,77,75,73,75};
145:         int[] ypoints = {15,24,24,33,24,24};
146:         Polygon polygon = new Polygon(xpoints, ypoints, 6);
147:         _figPoly.setPolygon(polygon);
148:         break;
149:       }
150:       // east
151:       case 2: {
152:         int[] xpoints = {66,75,75,84,75,75};
153:         int[] ypoints = {24,24,26,24,22,24};
154:         Polygon polygon = new Polygon(xpoints, ypoints, 6);
155:         _figPoly.setPolygon(polygon);
156:         break;
157:       }
158:       // west
159:       case 3: {
160:         int[] xpoints = {84,75,75,66,75,75};
161:         int[] ypoints = {24,24,26,24,22,24};
162:         Polygon polygon = new Polygon(xpoints, ypoints, 6);
163:         _figPoly.setPolygon(polygon);
164:         break;
165:       }
166:       // north
167:       default: {
168:         int[] xpoints = {75,75,77,75,73,75};
169:         int[] ypoints = {33,24,24,15,24,24};
170:         Polygon polygon = new Polygon(xpoints, ypoints, 6);
171:         _figPoly.setPolygon(polygon);
172:       }
173:     }
174:     setBounds(bbox);
175:   }
176:   public int getArrow() { return _arrowDirection; }
177: 
178:   public Dimension getMinimumSize() {
179:     Dimension nameMin = _name.getMinimumSize();
180:     Dimension figPolyMin = _figPoly.getSize();
181: 
182:     int h = Math.max(figPolyMin.height, nameMin.height);
183:     int w = figPolyMin.width + nameMin.width;
184:     return new Dimension(w, h);
185:   }
186: 
187:   /* Override setBounds to keep shapes looking right */
188:   public void setBounds(int x, int y, int w, int h) {
189:     if (_name == null) return;
190: 
191:     Rectangle oldBounds = getBounds();
192: 
193:     Dimension nameMin = _name.getMinimumSize();
194: 
195:     int ht = 0;
196: 
197:     if (nameMin.height > _figPoly.getHeight()) 
198:       ht = (nameMin.height - _figPoly.getHeight()) / 2;
199: 
200:     _name.setBounds(x, y, w-_figPoly.getWidth(), nameMin.height);
201:     _figPoly.setBounds(x + _name.getWidth(), y + ht,
202: 		       _figPoly.getWidth(), _figPoly.getHeight());
203: 
204:     firePropChange("bounds", oldBounds, getBounds());
205:     calcBounds(); //_x = x; _y = y; _w = w; _h = h;
206:     updateEdges();
207:   }
208: 
209:   protected void textEdited(FigText ft) throws PropertyVetoException {
210:     MMessage mes = (MMessage) getOwner();
211:     if (mes != null && ft == _name) {
212:        String s = ft.getText();
213:        try {
214: 	  ParserDisplay.SINGLETON.parseMessage(mes, s);
215: 	  ProjectBrowser.TheInstance.getStatusBar().showStatus("");
216:        } catch (ParseException pe) {
217: 	  ProjectBrowser.TheInstance.getStatusBar().showStatus("Error: " + pe + " at " + pe.getErrorOffset());
218:        }
219:     }
220:     else
221: 	super.textEdited(ft);
222:   }
223: 
224:   protected void modelChanged() {
225:     super.updateNameText();
226:     MMessage mes = (MMessage) getOwner();
227:     if (mes == null) return;
228:     _name.setText(Notation.generate(this, mes));
229: 	updateArrow();	
230: 	
231:   }
232:   
233: /**
234:  * Determines the direction of the message arrow. Deetermination of the 
235:  * type of arrow happens in modelchanged
236:  */
237:   protected void updateArrow() {
238:   	MMessage mes = (MMessage) getOwner();
239:     if (mes == null) return;
240:     MClassifierRole sender = mes.getSender();
241:     MClassifierRole receiver = mes.getReceiver();
242:     Fig senderPort = getLayer().presentationFor(sender);
243:     Fig receiverPort = getLayer().presentationFor(receiver);
244:     if (senderPort == null || receiverPort == null) return;
245:     int sx = senderPort.getX();
246:     int sy = senderPort.getY();
247:     int rx = receiverPort.getX();
248:     int ry = receiverPort.getY();
249:     if (sx < rx && Math.abs(sy-ry) <= Math.abs(sx-rx)) { // east
250:     	setArrow(2);
251:     } else 
252:     if (sx > rx && Math.abs(sy-ry) <= Math.abs(sx-rx)) { // west
253:     	setArrow(3);
254:     } else 
255:     if (sy < ry) { // south
256:     	setArrow(1);
257:     } else
258:     	setArrow(4);
259:   }
260: 
261:   /** add the FigMessage to the Path Items of its FigAssociationRole */
262:   public void addPathItemToFigAssociationRole(Layer lay) {
263: 
264:     MAssociationRole ar = ((MMessage) getOwner()).getCommunicationConnection();
265:     if (ar != null && lay != null) {
266:       FigAssociationRole figAssocRole = (FigAssociationRole) lay.presentationFor(ar);
267:       if (figAssocRole != null) {
268:       	figAssocRole.addMessage(this);
269:         figAssocRole.updatePathItemLocations();
270:         lay.bringToFront(this);
271:       }
272:     }
273:   }
274: 
275:  
276: 	
277: 
278: 	
279: 
280: 	/**
281: 	 * @see org.tigris.gef.presentation.Fig#paint(Graphics)
282: 	 */
283: 	public void paint(Graphics g) {
284: 		updateArrow();
285: 		super.paint(g);
286: 	}
287: 
288:     
289: 
290: } /* end class FigMessage */
