262:   public void addPathItemToFigAssociationRole(Layer lay) {
263: 
264:     MAssociationRole ar = ((MMessage) getOwner()).getCommunicationConnection();
265:     if (ar != null && lay != null) {
266:       FigAssociationRole figAssocRole = (FigAssociationRole) lay.presentationFor(ar);
267:       if (figAssocRole != null) {
268:       	figAssocRole.addMessage(this);
269:         figAssocRole.updatePathItemLocations();
270:         lay.bringToFront(this);
271:       }
272:     }
273:   }
