117:      * <p>Constructor for a new classifier role.</p>
118:      *
119:      * <p>An invisible {@link FigRect} as the point of contact for connections
120:      *   ({@link #_bigPort}), with matching rectangle providing the graphic
121:      *   rendering {@link #_cover}). Stereotype and name are rendered centrally
122:      *   in the rectangle.</p>
123:      */
124: 
125:     public FigClassifierRole() {
126: 
127:         // The big port and cover. Color of the big port is irrelevant
128: 
129:         _bigPort = new FigRect(10, 10, 90, 50, Color.cyan, Color.cyan);
130:         _cover   = new FigRect(10, 10, 90, 50, Color.black, Color.white);
131: 
132:         // The stereotype. Width is the same as the cover, height is whatever
133:         // its minimum permitted is. The text should be centred.
134: 
135:         Dimension stereoMin = _stereo.getMinimumSize();
136: 
137:         _stereo.setLineWidth(0);
138:         _stereo.setFilled(false);
139:         _stereo.setJustifciaionByName("Center");
140:         _stereo.setDisplayed(false);
141: 
142:         _stereo.setBounds(10, 10, 90, stereoMin.height);
143: 
144:         // The name. Width is the same as the cover, height is whatever its
145:         // minimum permitted is. The text of the name will be centred by
146:         // default. In the same place as the stereotype, since at this stage
147:         // the stereotype is not displayed. Being a classifier role it is
148:         // underlined
149: 
150:         Dimension nameMin = _name.getMinimumSize();
151: 
152:         _name.setLineWidth(0);
153:         _name.setMultiLine(true);
154:         _name.setFilled(false);
155:         _name.setUnderline(true);
156: 
157:         _name.setBounds(10, 10, 90, nameMin.height);
158: 
159:         // add Figs to the FigNode in back-to-front order
160: 
161:         addFig(_bigPort);
162:         addFig(_cover);
163:         addFig(_stereo);
164:         addFig(_name);
165: 
166:         // Set our bounds to those we are given.
167: 
168:         Rectangle r = getBounds();
169:         setBounds(r.x, r.y, r.width, r.height);
170:     }
