214:     public Object clone() {
215:         FigClassifierRole figClone = (FigClassifierRole) super.clone();
216:         Vector            v        = figClone.getFigs();
217: 
218:         figClone._bigPort = (FigRect) v.elementAt(0);
219:         figClone._cover   = (FigRect) v.elementAt(1);
220:         figClone._stereo  = (FigText) v.elementAt(2);
