227:     /**
228:      * <p>Update the stereotype text.</p>
229:      *
230:      * <p>If the stereotype text is non-existant, we must make sure it is
231:      *   marked not displayed, and update the display accordingly.</p>
232:      *
233:      * <p>Similarly if there is text, we must make sure it is marked
234:      *   displayed.</p>
235:      */
236: 
237:     protected void updateStereotypeText() {
238: 
239:         // Can't do anything if we haven't got an owner to have a stereotype!
240: 
241:         MModelElement me = (MModelElement) getOwner();
242: 
243:         if (me == null) {
244:             return;
245:         }
246: 
247:         // Record the old bounds and get the stereotype
248: 
249:         Rectangle   bounds = getBounds();
250:         MStereotype stereo = me.getStereotype();
251: 
252:         // Where we now have no stereotype, mark as not displayed. Were we do
253:         // have a stereotype, set the text and mark as displayed. If we remove
254:         // or add/change a stereotype we adjust the vertical bounds
255:         // appropriately. Otherwise we need not work out the bounds here. That
256:         // will be done in setBounds().
257: 
258:         if ((stereo == null) ||
259:             (stereo.getName() == null) ||
260:             (stereo.getName().length() == 0)) {
261: 
262:             if (_stereo.isDisplayed()) {
263:                 bounds.height -= _stereo.getBounds().height;
264:                 _stereo.setDisplayed(false);
265:             }
266:         }
267:         else {
268: 
269:             int oldHeight = _stereo.getBounds().height;
270: 
271:             // If we weren't currently displayed the effective height was
272:             // zero. Mark the stereotype as displayed
273: 
274:             if (!(_stereo.isDisplayed())) {
275:                 oldHeight = 0;
276:                 _stereo.setDisplayed(true);
277:             }
278: 
279:             // Set the text and recalculate its bounds
280: 
281:             _stereo.setText(Notation.generateStereotype(this, stereo));
282:             _stereo.calcBounds();
283: 
284:             bounds.height += _stereo.getBounds().height - oldHeight;
285:         }
286: 
287:         // Set the bounds to our old bounds (reduced if we have taken the
288:         // stereotype away). If the bounds aren't big enough when we've added a
289:         // stereotype, they'll get increased as needed.
290: 
291:         setBounds(bounds.x, bounds.y, bounds.width, bounds.height);
292:     }
