330:     /**
331:      * <p>Work out the minimum size that this Fig can be.</p>
332:      *
333:      * <p>This should be the size of the stereotype + name + padding. However
334:      *   we allow for the possible case that the cover or big port could be
335:      *   bigger still.</p>
336:      *
337:      * @return  The minimum size of this fig.
338:      */
339: 
340:     public Dimension getMinimumSize() {
341:       
342:         Dimension bigPortMin = _bigPort.getMinimumSize();
343:         Dimension coverMin   = _cover.getMinimumSize();
344:         Dimension stereoMin  = _stereo.getMinimumSize();
345:         Dimension nameMin    = _name.getMinimumSize();
346: 
347:         Dimension newMin    = new Dimension(nameMin.width, nameMin.height);
348: 
349:         // Work out whether we need to count in the stereotype
350: 
351:         if (_stereo.isDisplayed()) {
352:             newMin.width   = Math.max(newMin.width, stereoMin.width);
353:             newMin.height += stereoMin.height;
354:         }
355: 
356:         // Maximum should allow for bigPort and cover.
357: 
358:         newMin.height = Math.max(bigPortMin.height,
359:                                  Math.max(coverMin.height,
360:                                           newMin.height + _PADDING * 2));
361: 
362:         newMin.width  = Math.max(bigPortMin.width,
363:                                  Math.max(coverMin.width,
364:                                           newMin.width + _PADDING * 2));
365: 
366:         return newMin;
367:     }
