370:     /**
371:      * <p>Override setBounds to keep shapes looking right.</p>
372:      *
373:      * <p>Set the bounds of all components of the Fig. The stereotype (if any)
374:      *   and name are centred in the fig.</p>
375:      *
376:      * <p>We allow for the requested bounds being too small, and impose our
377:      *   minimum size if necessary.</p>
378:      *
379:      * @param x  X coordinate of upper left corner
380:      *
381:      * @param y  Y coordinate of upper left corner
382:      *
383:      * @param w  width of bounding box
384:      *
385:      * @param h  height of bounding box
386:      *
387:      * @author 10 Apr 2002. Jeremy Bennett (mail@jeremybennett.com). Patch to
388:      *         allow for stereotype as well.
389:      */
390: 
391:     public void setBounds(int x, int y, int w, int h) {
392: 
393:         // In the rather unlikely case that we have no name, we give up.
394: 
395:         if (_name == null) {
396:             return;
397:         }
398: 
399:         // Remember where we are at present, so we can tell GEF later. Then
400:         // check we are as big as the minimum size
401: 
402:         Rectangle oldBounds = getBounds();
403:         Dimension minSize   = getMinimumSize();
404: 
405:         int newW = (minSize.width  > w) ? minSize.width  : w;
406:         int newH = (minSize.height > h) ? minSize.height : h;
407: 
408:         Dimension stereoMin = _stereo.getMinimumSize();
409:         Dimension nameMin   = _name.getMinimumSize();
410: 
411:         // Work out the padding each side, depending on whether the stereotype
412:         // is displayed and set bounds accordingly
413: 
414:         if (_stereo.isDisplayed()) {
415:             int extra_each = (h - nameMin.height - stereoMin.height) / 2;
416: 
417:             _stereo.setBounds(x, y + extra_each, w, stereoMin.height);
418:             _name.setBounds(x, y + stereoMin.height + extra_each, w,
419:                             nameMin.height); 
420:         }
421:         else {
422:             int extra_each = (h - nameMin.height) / 2;
423: 
424:             _name.setBounds(x, y + extra_each, w, nameMin.height);
425:         }
426: 
427:         // Set the bounds of the bigPort and cover
428: 
429:         _bigPort.setBounds(x, y, newW, newH);
430:         _cover.setBounds(x, y, newW, newH);
431: 
432:         // Record the changes in the instance variables of our parent, tell GEF
433:         // and trigger the edges to reconsider themselves.
434: 
435:         _x = x;
436:         _y = y;
437:         _w = newW;
438:         _h = newH;
439:         
440:         firePropChange("bounds", oldBounds, getBounds());
441:         updateEdges();
442:     }
