457:     protected void textEdited(FigText ft) throws PropertyVetoException {
458: 
459:         MClassifierRole cls = (MClassifierRole) getOwner();
460: 
461:         if (ft == _name) {
462:             String s = ft.getText();
463: 	    try {
464: 		ParserDisplay.SINGLETON.parseClassifierRole(cls, s);
465: 		ProjectBrowser.TheInstance.getStatusBar().showStatus("");
466: 	    } catch (ParseException pe) {
467: 		ProjectBrowser.TheInstance.getStatusBar().showStatus("Error: " + pe + " at " + pe.getErrorOffset());
468: 	    }
469:         }
470:     }
