472: 
473:     /**
474:      * <p>Adjust the fig in the light of some change to the model.</p>
475:      *
476:      * <p><em>Note</em>. The current implementation does not properly use
477:      *   Notation.generate to generate the full name for a classifier role.</p>
478:      */
479: 
480:     protected void modelChanged() {
481: 
482:         // Let the superclass sort out any of its changes
483: 
484:         super.updateNameText();
485: 
486:         // Give up if we don't have an owner
487: 
488:         MClassifierRole cr = (MClassifierRole) getOwner();
489: 
490:         if (cr == null) {
491:             return;
492:         }
493: 
494:         // Note our current bounds
495: 
496:         Rectangle oldBounds = getBounds();
497: 
498:         // We only use the notation generator for the name itself. We ought to
499:         // do the whole thing.
500: 
501:         String nameStr    = Notation.generate(this, cr.getName()).trim();
502:         String baseString = "";
503: 
504:         // Loop through all base classes, building a comma separated list
505: 
506:         if (cr.getBases() != null && cr.getBases().size()>0) {
507:             Vector bases = new Vector(cr.getBases());
508:             baseString += ((MClassifier)bases.elementAt(0)).getName();
509: 
510:             for(int i=1; i<bases.size(); i++)
511:                 baseString += ", "  +
512:                               ((MClassifier)bases.elementAt(i)).getName();
513:         }
514: 
515:         // Build the final string and set it as the name text.
516: 
517:         if (_readyToEdit) {
518:             if( nameStr.length() == 0 && baseString.length() == 0)
519:                 _name.setText("");
520:             else
521:                 _name.setText("/" + nameStr.trim() + " : " + baseString);
522:         }
523: 
524:         // Now recalculate all the bounds, using our old bounds.
525: 
526: 	setBounds(oldBounds.x, oldBounds.y, oldBounds.width, oldBounds.height);
527:     }
528: 
