262:             if (_stereo.isDisplayed()) {
263:                 bounds.height -= _stereo.getBounds().height;
264:                 _stereo.setDisplayed(false);
265:             }
266:         }
267:         else {
268: 
269:             int oldHeight = _stereo.getBounds().height;
270: 
271:             // If we weren't currently displayed the effective height was
272:             // zero. Mark the stereotype as displayed
273: 
274:             if (!(_stereo.isDisplayed())) {
275:                 oldHeight = 0;
276:                 _stereo.setDisplayed(true);
277:             }
