279:             // Set the text and recalculate its bounds
280: 
281:             _stereo.setText(Notation.generateStereotype(this, stereo));
282:             _stereo.calcBounds();
283: 
284:             bounds.height += _stereo.getBounds().height - oldHeight;
285:         }
