174: 	setOwner(node);                             // Set it as the owner of the figure.
175: 	element.addComment(node);                   // Tell the annotated element, that it has a comment now.
176: 
177: 	// Notes in state diagrams need a special treatment, cause
178: 	// the nodes in them don't necessary have a namespace, where
179: 	// we could add the note. So I added this hack... :-(
180: 	// Andreas Rueckert <a_rueckert@gmx.net>
181: 	if(element instanceof MStateVertex) { 
182: 
183: 	    ProjectBrowser pb = ProjectBrowser.TheInstance;    // If the current target is a state diagram, we have to
184: 	    if (pb.getTarget() instanceof UMLStateDiagram) {   // check, if we are editing the diagram.
185: 		StateDiagramGraphModel gm = (StateDiagramGraphModel)(((UMLStateDiagram)pb.getTarget()).getGraphModel());
186: 		node.setNamespace(gm.getNamespace());  // We are editing, so we set the Namespace directly.
187: 	    }
188: 	} else {
189: 	    node.setNamespace(element.getNamespace());  // Add the comment to the same namespace as the annotated element.
190: 	}
191: 
192: 	storeNote( placeString());                  // Set the default text for this figure type.
193:     }
