231:     public void mouseClicked(MouseEvent me) {
232: 	if (!_readyToEdit) {
233: 	    if (getOwner() instanceof MModelElement) {
234: 		MModelElement own = (MModelElement)getOwner();
235: 		storeNote("");
236: 		_readyToEdit = true;
