238: 		cat.debug("not ready to edit note");
239: 		return;
240: 	    }
241: 	}
242: 	if (me.isConsumed()) return;
243: 	if (me.getClickCount() >= 2 &&
244: 	    !(me.isPopupTrigger() || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
245: 	    if (getOwner() == null) return;
246: 	    Fig f = hitFig(new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4));
247: 	    if (f instanceof MouseListener) ((MouseListener)f).mouseClicked(me);
248: 	}       
249: 	me.consume();
250:     }
