263: 	Object src = pce.getSource();
264: 	startTrans();
265: 	// update any text, colors, fonts, etc.
266: 	updateNameText();
267: 	// update the relative sizes and positions of internel Figs
268: 	updateBounds();
269: 	endTrans();
