272:     public void propertyChange(PropertyChangeEvent pve) {
273: 	Object src = pve.getSource();
274: 	String pName = pve.getPropertyName();
275: 	if (pName.equals("editing") && Boolean.FALSE.equals(pve.getNewValue())) {
276: 	    try {
277: 		startTrans();
278: 		//parse the text that was edited
279: 		textEdited((FigText)src);
280: 		// resize the FigNode to accomodate the new text
281: 		Rectangle bbox = getBounds();
282: 		Dimension minSize = getMinimumSize();
283: 		bbox.width = Math.max(bbox.width, minSize.width);
284: 		bbox.height = Math.max(bbox.height, minSize.height);
285: 		setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
286: 		endTrans();
287: 	    }
288: 	    catch (PropertyVetoException ex) {
289:                 cat.error("could not parse and use the text entered in figcomment", ex);
290: 	    }
291: 	}
292: 	else super.propertyChange(pve);
293:     }  
