388:      * Get the minimum size for the note figure.
389:      *
390:      * @return The minimum size for the note figure.
391:      */
392:     public Dimension getMinimumSize() {
393: 
394: 	// Get the size of the text field.
395: 	Dimension textMinimumSize = _text.getMinimumSize();
396: 
397: 	// And add the gaps around the textfield to get the minimum
398: 	// size of the note.
399: 	return new Dimension(textMinimumSize.width + 4 + gapY, textMinimumSize.height + 4);
400:     }
401: 
402:     public void setBounds(int x, int y, int w, int h) {
403: 	if (_text == null) return;
404: 
405: 	Rectangle oldBounds = getBounds();
406: 
407: 	// Resize the text figure
408: 	_text.setBounds(x + 2, y  + 2 , w - 4 - gapY , h - 4);
409: 
410: 	// Resize the big port around the figure
411: 	_bigPort.setBounds(x, y, w, h);
412: 
413: 	// Since this is a complex polygon, there's no easy way to resize it.
414: 	Polygon newPoly = new Polygon();
415: 	newPoly.addPoint(x, y);
416: 	newPoly.addPoint(x + w - 1 - gapY, y);
417: 	newPoly.addPoint(x + w - 1, y + gapY);
418: 	newPoly.addPoint(x + w - 1, y + h - 1);
419: 	newPoly.addPoint(x, y + h - 1);
420: 	newPoly.addPoint(x, y);
421: 	_body.setPolygon(newPoly);
422: 
423: 	// Just move the corner to it's new position.
424: 	_urCorner.setBounds(x + w - 1 - gapY, y, gapY, gapY);
425: 
426: 	calcBounds(); //_x = x; _y = y; _w = w; _h = h;
427: 	firePropChange("bounds", oldBounds, getBounds());
428:     }
429: 
430:     protected void updateBounds() {
431: 	Rectangle bbox = getBounds();
432: 	Dimension minSize = getMinimumSize();
433: 	bbox.width = Math.max(bbox.width, minSize.width);
434: 	bbox.height = Math.max(bbox.height, minSize.height);
435: 	setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
436:     }    
