223:   public void parseDynObjects(String dynobjs) {
224: 
225:     _dynObjects = dynobjs;
226: 
227:     StringTokenizer st1 = new StringTokenizer(dynobjs, ",[]");
228:     while (st1.hasMoreTokens()) {
229:       String element = st1.nextToken().trim();
230:       _dynVector.addElement(element);
231:     }
232:     int count = 0;
233:     StringTokenizer st = new StringTokenizer(dynobjs, ",|[]");
234: 
235:     while (st.hasMoreTokens()) {
236:       String next = st.nextToken().trim();
237:     
238:       if (next.equals("a")) {
239:         // next token is an activation fig ["a"| _FromPos| _toPos| _fromBegin| end]
240:         FigActivation fa = new FigActivation(10, 10, 21, 10, 0, 0);
241:         addFig(fa);
242:         _activations.addElement(fa);
243:         bindPort(getOwner(), fa);
244: 
245:         String fromStr = st.nextToken();
246:         String toStr = st.nextToken();
247:         String begStr = st.nextToken();
248:         String endStr = st.nextToken();
249: 
250:         Integer fromInt = new Integer(fromStr);
251:         int from = fromInt.intValue();
252:         fa.setFromPosition(from);
253: 
254:         Integer toInt = new Integer(toStr);
255:         int to = toInt.intValue();
256:         fa.setToPosition(to);
257: 
258:         if (begStr.equals("true")) { fa.setFromTheBeg(true); }
259:         else fa.setFromTheBeg(false);
260:         if (endStr.equals("true")) { fa.setEnd(true); }
261:         else fa.setEnd(false);
262: 
263:         fa.setDynVectorPos(count);
264:         count++;
265:       }
266:       if (next.equals("b")) {
267: 
268:         // next token is a dynPort figure ["b"| _pos]
269:         FigDynPort fsp = new FigDynPort(10, 10, 21, 1, 0);
270:         addFig(fsp);
271:         _ports.addElement(fsp);
272:         bindPort(getOwner(), fsp);
273: 
274:         String posStr = st.nextToken();
275:         Integer posInt = new Integer(posStr);
276:         int pos = posInt.intValue();
277:         fsp.setPosition(pos);
278: 
279:         fsp.setDynVectorPos(count);
280:         count++;
281:       }
282: 
283:     }
284: 
285:   }
