729:   /** This method decides, if two FigActivations can be
730:    *    replaced with the first of this two FigActivations with
731:    *    the added lenght of both FigActivations */
732:   public void concatActivation(FigSeqLink figLink, Vector contents) {
733:     int portNumber = figLink.getPortNumber(contents);
734:     boolean canConcat = false;
735:     FigActivation figConcat = canConcat(portNumber);
736:     if (figConcat != null) canConcat = true;
737: 
738:     if (canConcat) {
739:       figConcat.setEnd(false);
740:       int max = 10000;
741:       FigActivation nextAct = null;
742:       for (int i=0; i<_activations.size(); i++) {
743:         FigActivation fa = (FigActivation) _activations.elementAt(i);
744:         if (fa.getFromPosition() > portNumber && fa.getFromPosition() < max)  {
745:           nextAct = fa;
746:           max = fa.getFromPosition();
747:         }
748:       }
749:       if (nextAct != null) {
750:         figConcat.setToPosition(nextAct.getToPosition());
751:         _activations.removeElement(nextAct);
752:         int dynPos = nextAct.getDynVectorPos();
753:         _dynVector.removeElementAt(dynPos);
754:         Vector dynFigs = getFigs();
755:         for (int i=0; i<dynFigs.size(); i++) {
756:           Fig df = (Fig) dynFigs.elementAt(i);
757:           if (df instanceof FigActivation) {
758:             FigActivation dfa = (FigActivation) df;
759:             if (dfa.getDynVectorPos() > dynPos) dfa.setDynVectorPos(dfa.getDynVectorPos()-1);
760:           }
761:           else if (df instanceof FigDynPort) {
762:             FigDynPort dfsp = (FigDynPort) df;
763:             if (dfsp.getDynVectorPos() > dynPos) dfsp.setDynVectorPos(dfsp.getDynVectorPos()-1);
764:           }
765:         }
766:         _dynObjects = _dynVector.toString();
767:         removeFig(nextAct);
768:         nextAct.delete();
769:       }
770:       else {
771:         // do nothing
772:       }
773:     }
774:   }
