828:   /** Returns two Integers, one is the port-number of the FigSeqLink
829:    *    which is next to the given portNumber. The second Integer is
830:    *    the highest port-number */
831:   public Vector nearestLink(Vector edges, int portNumber, Vector contents) {
832:     Vector _nearest = new Vector();
833:     Enumeration e = edges.elements();
834:     int max = 100000;
835:     int nearest = 0;
836:     int high = 0;
837:     while (e.hasMoreElements()) {
838:       FigSeqLink  fsl = (FigSeqLink) e.nextElement();
839:       int pos = fsl.getPortNumber(contents);
840:       if (pos < max && pos > portNumber) {
841:         max = pos;
842:         nearest = max;
843:       }
844:       if (pos > high) high = pos;
845:     }
846:     _nearest.addElement(new Integer(nearest));
847:     _nearest.addElement(new Integer(high));
848:     return _nearest;
849:   }
