339:   /* Override setBounds to keep shapes looking right */
340:   public void setBounds(int x, int y, int w, int h, int edges) {
341: 
342:     if (_name == null) return;
343: 
344: 
345:     Rectangle oldBounds = getBounds();
346: 
347:     Dimension nameMin = _name.getMinimumSize();
348: 
349:     int mainX = 0; int mainY = 0; int mainW = 0; int mainH = 0;
350:     int lifeX = 0; int lifeY = 0; int lifeW = 0; int lifeH = 0;
351:     int portX = 0; int portY = 0; int portW = 0; int portH = 0;
352: 
353: 
354: 
355: 
356:     if (_created && _terminated) {
357:       mainX = x;        mainY = y+40*(_createHeight+1)+10;
358:       mainW = nameMin.width+20;     mainH = nameMin.height+10;
359:       lifeX = x+nameMin.width/2+6;    lifeY = y+nameMin.height+40*(_createHeight+1)+20;
360:       lifeW = 10;       lifeH = 25+40*(_terminateHeight- _createHeight-1);
361:       portX = x;        portY = y+nameMin.height+45;
362:       portW = 10;       portH = 1;
363: 
364:     }
365: 
366:     if (_created && (!(_terminated))) {
367:       	mainX = x; 				mainY = y+40*(_createHeight+1)+10;
368:       	mainW = nameMin.width+20; 		mainH = nameMin.height+10;
369:       	lifeX = x+nameMin.width/2+6;		lifeY = y+nameMin.height+40*(_createHeight+1)+20;
370:       	lifeW = 10;				lifeH = 30+40*(edges- _createHeight-1);
371:       	portX = x;				portY = y+nameMin.height+45;
372:       	portW = 10;				portH = 1;
373: 
374: 
375: 
376:     }
377: 
378:     if ((!(_created)) && _terminated) {
379:       	mainX = x; 				mainY = y;
380:       	mainW = nameMin.width+20; 		mainH = nameMin.height+10;
381:       	lifeX = x+nameMin.width/2+6;		lifeY = y+nameMin.height+10;
382:       	lifeW = 10;				lifeH = 40*_terminateHeight+35;
383:       	portX = lifeX-3;			portY = y+nameMin.height+45;
384:       	portW = 21;				portH = 1;
385: 
386: 
387:     }
388:     if ((!(_created)) && (!(_terminated))) {
389:       	mainX = x; 				mainY = y;
390:       	mainW = nameMin.width+20; 		mainH = nameMin.height+10;
391:       	lifeX = x+nameMin.width/2+6;		lifeY = y+nameMin.height+10;
392:       	lifeW = 10;				lifeH = 40*edges+40;
393:       	portX = lifeX-3;		 	portY = y+nameMin.height+45;
394:       	portW = 21;				portH = 1;
395: 
396: 
397:     }
398:     int activX = lifeX-6;	int activY = 0;
399:     int activW = 21;		int activH = 0;
400: 
401:     // the dynamci ports are invisible
402:     portH=0;
403:    
404:      _bigPort.setBounds(mainX, mainY, mainW, mainH);
405:      _cover.setBounds(mainX, mainY, mainW, mainH);
406:     _name.setBounds(mainX, mainY, mainW, mainH);
407:     _lifeline.setBounds(lifeX, lifeY, lifeW, lifeH);
408: 
409:     Enumeration e = _ports.elements();
410: 
411:     while (e.hasMoreElements()) {
412: 
413: 
414:       FigDynPort r = (FigDynPort) e.nextElement();
415:       int number = r.getPosition();
416: 
417:       if (_created) {
418:         if (number == _createHeight) {
419: 	     r.setBounds(mainX, mainY+ mainH/2 -3 , mainW, portH); //-1
420:         } else  {
421:           r.setBounds(portX+((nameMin.width)/2), portY+40*number, 21, portH);
422:         }
423:       }
424:       if (!(_created)) {
425:         r.setBounds(portX-3, portY+40*number, 21, portH);
426:       }
427: 
428: 
429:     }
430: 
431:     // the y-position of the termination symbol
432:     int termY1 = lifeY + lifeH;
433: 
434:     int actSize = _activations.size();
435:     for (int i=0; i<actSize; i++) {
436: 
437:       FigActivation figAct = (FigActivation) _activations.elementAt(i);
438:       int from = figAct.getFromPosition();
439:       int to = figAct.getToPosition();
440:       if (i == 0) {
441:         if (figAct.isFromTheBeg()) {
442:           if (_created) {
443:             activY = lifeY;
444:             activH = 40*(to-_createHeight)-15;
445:           } else {
446:             activY = lifeY;
447:             activH = 40*(to)+35;
448:           }
449:         } else {
450:           if (_created) {
451:             activY = lifeY;
452:             activH = 40*(to-_createHeight)-15;
453:           } else {
454:             activY = portY+40*from;
455:             activH = 40*(to-from);
456:           }
457:           if ((to-from) == 0 && (!(figAct.isEnd()))) {
458:             activH = 10;
459:           }
460:         }
461:         figAct.setBounds(activX, activY, activW, activH);
462:       } else {
463:         activY = portY+40*from;
464:         activH = 40*(to-from);
465:         if ((to-from) == 0 && (!(figAct.isEnd()))) {
466:           activH = 10;
467:         }
468:         figAct.setBounds(activX, activY, activW, activH);
469: 
470: 
471:       }
472:       // update the termination y position
473:       if ( (activY+activH) > termY1) termY1 = activY+activH;
474:     }
475:     // set termination symbol under the last activation symbol
476:     int termX1=lifeX;
477:     termY1=termY1-1;
478:     int termX2=lifeX+lifeW-1;
479:     int termY2=termY1;
480: 
481:     if  ( _terminated ) {
482:       // make terminate symbol visible as a cross 
483:       termX1=lifeX-lifeW;
484:       //termY1=lifeY+lifeH-1;
485:       termX2=lifeX+2*lifeW;
486:       termY2=termY1+lifeW*2;
487:     }
488:     terminateSymbolSetBounds( termX1, termY1, termX2, termY2);
489: 
490:     _x = x; _y = y; _w = w; _h = h;
491: 
492:     firePropChange("bounds", oldBounds, getBounds());
493:     calcBounds(); //_x = x; _y = y; _w = w; _h = h;
494:     updateEdges();
495: 
496:    }
