686:    *    a return-action, the corresponding FigActivation will
687:    *    be cut in two FigActivations */
688:   public void breakActivation(FigSeqLink figLink, Vector contents) {
689:     int size = contents.size();
690:     int portNumber = figLink.getPortNumber(contents);
691:     int edges = edgesCount(contents);
692: 
693:     for (int i=0; i<_activations.size(); i++) {
694:       FigActivation figAct = (FigActivation) _activations.elementAt(i);
695:       if (figAct.getFromPosition() <= portNumber && figAct.getToPosition() > portNumber) {
696:         Vector figEdges = getFigEdges();
697:         Vector _nearest = nearestLink(figEdges, portNumber, contents);
698:         int nearest = ((Integer)_nearest.elementAt(0)).intValue();
699:         int high = ((Integer)_nearest.elementAt(1)).intValue();
700: 
701:         if (nearest > portNumber) {
702:           //FigActivation newAct = new FigActivation(0, 0, 21, 40, nearest, high);
703:           FigActivation newAct = new FigActivation(0, 0, 21, 40, nearest, figAct.getToPosition());
704:           _activations.addElement(newAct);
705:           String dynStr = "a|"+newAct.getFromPosition()+"|"+newAct.getToPosition()+"|"+newAct.isFromTheBeg()+"|"+newAct.isEnd();
706:           _dynVector.addElement(dynStr);
707:           _dynObjects = _dynVector.toString();
708:           newAct.setDynVectorPos(_dynVector.indexOf(dynStr));
709:           addFig(newAct);
710:           bindPort(getOwner(), newAct);
711:         }
712:         figAct.setToPosition(portNumber);
713:         figAct.setEnd(true);
714:       }
715:       else if (figAct.getFromPosition() <= portNumber && figAct.getToPosition() == portNumber) {
716:         figAct.setEnd(true);
717:       }
718: //      else if (figAct.getFromPosition() == portNumber) {
719: //        figLink.setDefaultAction();
720: //      }
721:       int dynPos = figAct.getDynVectorPos();
722:       _dynVector.removeElementAt(dynPos);
723:       String newDynStr = "a|"+figAct.getFromPosition()+"|"+figAct.getToPosition()+"|"+figAct.isFromTheBeg()+"|"+figAct.isEnd();
724:       _dynVector.insertElementAt(newDynStr, dynPos);
725:       _dynObjects = _dynVector.toString();
726:     }
