793:    *    --> returns true */
794:   public boolean canDo(boolean side, FigSeqLink fsl, int portNumber) {
795:     FigSeqObject fso = (FigSeqObject) fsl.getDestFigNode();
796:     if (side) fso = (FigSeqObject) fsl.getSourceFigNode();
797:     boolean _canDo = true;
798:     for (int j=0; j<fso._activations.size(); j++) {
799:       FigActivation fa = (FigActivation) fso._activations.elementAt(j);
800:       if (fa.getFromPosition() == portNumber) _canDo = false;
801:     }
802: 
803:     if (!(side)) {
804:       FigSeqObject dest = (FigSeqObject) fsl.getSourceFigNode();
805:       for (int i=0; i<dest._activations.size(); i++) {
806:         FigActivation fa = (FigActivation) dest._activations.elementAt(i);
