816:   public FigActivation canConcat(int portNumber) {
817:     FigActivation _figConcat = null;
818:     for (int j=0; j<_activations.size(); j++) {
819:       FigActivation fa = (FigActivation) _activations.elementAt(j);
820:       if (fa.getToPosition() == portNumber && fa.isEnd()) {
