47: /** Class to display graphics for a UML MState in a diagram. */
48: 
49: public class FigState extends FigStateVertex {
50:     protected static Category cat = Category.getInstance(FigState.class);
51: 
52:   ////////////////////////////////////////////////////////////////
53:   // constants
54: 
55:   public final int MARGIN = 2;
56:   public final int X = 0;
57:   public final int Y = 0;
58:   public final int W = 70;
59:   public final int H = 40;
60: 
61:   ////////////////////////////////////////////////////////////////
62:   // instance variables
63: 
64:   /** UML does not really use ports, so just define one big one so
65:    *  that users can drag edges to or from any point in the icon. */
66: 
67:   FigRect _bigPort;
68:   FigRect _cover;
69:   FigText _internal;
70:   FigLine _divider;
71: 
72: 
73:   ////////////////////////////////////////////////////////////////
74:   // constructors
75: 
76:   public FigState() {
77:     _bigPort = new FigRRect(X+1, Y+1, W-2, H-2, Color.cyan, Color.cyan);
78:     _cover = new FigRRect(X, Y, W, H, Color.black, Color.white);
79: 
80:     _bigPort.setLineWidth(0);
81:     _name.setLineWidth(0);
82:     _name.setBounds(X+2, Y+2, W-4, _name.getBounds().height);
83:     _name.setFilled(false);
84: 
85:     _divider = new FigLine(X,  Y+2 + _name.getBounds().height + 1,
86: 			   W-1,  Y+2 + _name.getBounds().height + 1,
87: 			   Color.black);
88: 
89:     _internal = new FigText(X+2, Y+2 + _name.getBounds().height + 4,
90: 			    W-4, H - (Y+2 + _name.getBounds().height + 4));
91:     _internal.setFont(LABEL_FONT);
92:     _internal.setTextColor(Color.black);
93:     _internal.setLineWidth(0);
94:     _internal.setFilled(false);
95:     _internal.setExpandOnly(true);
96:     _internal.setMultiLine(true);
97:     _internal.setJustification(FigText.JUSTIFY_LEFT);
98: 
99:     // add Figs to the FigNode in back-to-front order
100:     addFig(_bigPort);
101:     addFig(_cover);
102:     addFig(_name);
103:     addFig(_divider);
104:     addFig(_internal);
105: 
106:     //setBlinkPorts(false); //make port invisble unless mouse enters
107:     Rectangle r = getBounds();
108:     setBounds(r.x, r.y, r.width, r.height);
109:   }
110: 
111:   public FigState(GraphModel gm, Object node) {
112:     this();
113:     setOwner(node);
114:   }
115: 
116:   public String placeString() { return "new MState"; }
117: 
118:   public Object clone() {
119:     FigState figClone = (FigState) super.clone();
120:     Vector v = figClone.getFigs();
121:     figClone._bigPort = (FigRect) v.elementAt(0);
122:     figClone._cover = (FigRect) v.elementAt(1);
123:     figClone._name = (FigText) v.elementAt(2);
124:     figClone._divider = (FigLine) v.elementAt(3);
125:     figClone._internal = (FigText) v.elementAt(4);
126:     return figClone;
127:   }
128: 
129:   ////////////////////////////////////////////////////////////////
130:   // accessors
131: 
132:   public Selection makeSelection() {
133:     return new SelectionState(this);
134:   }
135: 
136: 
137:   public void setOwner(Object node) {
138:     super.setOwner(node);
139:     bindPort(node, _bigPort);
140:   }
141: 
142:   public Dimension getMinimumSize() {
143:     Dimension nameDim = _name.getMinimumSize();
144:     Dimension internalDim = _internal.getMinimumSize();
145: 
146:     int h = nameDim.height + 4 + internalDim.height;
147:     int w = Math.max(nameDim.width + 4, internalDim.width + 4);
148:     return new Dimension(w, h);
149:   }
150: 
151:   /* Override setBounds to keep shapes looking right */
152:   public void setBounds(int x, int y, int w, int h) {
153:     if (_name == null) return;
154:     Rectangle oldBounds = getBounds();
155:     Dimension nameDim = _name.getMinimumSize();
156: 
157:     _name.setBounds(x+2, y+2, w-4,  nameDim.height);
158:     _divider.setShape(x, y + nameDim.height + 1, x + w - 1,  y + nameDim.height + 1);
159: 
160:     _internal.setBounds(x+2, y + nameDim.height + 4,
161: 			w-4, h - nameDim.height - 6);
162: 
163:     _bigPort.setBounds(x, y, w, h);
164:     _cover.setBounds(x, y, w, h);
165: 
166:     calcBounds(); //_x = x; _y = y; _w = w; _h = h;
167:     updateEdges();
168:     firePropChange("bounds", oldBounds, getBounds());
169:   }
170: 
171:   ////////////////////////////////////////////////////////////////
172:   // Fig accessors
173: 
174:   public void setLineColor(Color col) {
175:     _cover.setLineColor(col);
176:     _divider.setLineColor(col);
177:   }
178:  public Color getLineColor() { return _cover.getLineColor(); }
179: 
180:   public void setFillColor(Color col) { _cover.setFillColor(col); }
181:   public Color getFillColor() { return _cover.getFillColor(); }
182: 
183:   public void setFilled(boolean f) { _cover.setFilled(f); }
184:   public boolean getFilled() { return _cover.getFilled(); }
185: 
186:   public void setLineWidth(int w) {
187:     _cover.setLineWidth(w);
188:     _divider.setLineWidth(w);
189:   }
190:   public int getLineWidth() { return _cover.getLineWidth(); }
191: 
192: 
193:   ////////////////////////////////////////////////////////////////
194:   // event processing
195: 
196:   /** Update the text labels */
197:   protected void updateNameText() {
198:     super.updateNameText();
199:     cat.debug("FigState modelChanged");
200:     MState s = (MState) getOwner();
201:     if (s == null) return;
202:     String newText = Notation.generateStateBody(this, s);
203:     _internal.setText(newText);
204: 
205:     calcBounds();
206:     Rectangle rect = getBounds();
207:     setBounds(rect.x, rect.y, rect.width, rect.height);
208:     firePropChange("bounds", rect, getBounds());  
209:   }
210: 
211:   public void textEdited(FigText ft) throws PropertyVetoException {
212:     super.textEdited(ft);
213:     if (ft == _internal) {
214:       MState st = (MState) getOwner();
215:       if (st == null) return;
216:       String s = ft.getText();
217:       ParserDisplay.SINGLETON.parseStateBody(st, s);
218:     }
219:   }
220: 
221: 
222: } /* end class FigState */
