217: 	    baseStr += ", "+((MClassifier)it.next()).getName(); 
218: 	} 
219:     }
220: 
221:     if (_readyToEdit) { 
222:       if( nameStr == "" && baseStr == "") 
223: 	_name.setText(""); 
224:       else 
225: 	_name.setText(nameStr.trim() + " : " + baseStr); 
226:     } 
227:     Dimension nameMin = _name.getMinimumSize(); 
228:     Rectangle r = getBounds(); 
229:     setBounds(r.x, r.y, r.width, r.height); 
230:   } 
