473:     /**
474:      * <p>Gets the minimum size permitted for a class on the diagram.</p>
475:      *
476:      * <p>Parts of this are hardcoded, notably the fact that the name
477:      *   compartment has a minimum height of 21 pixels.</p>
478:      *
479:      * @return  the size of the minimum bounding box.
480:      */
481:     public Dimension getMinimumSize() {
482: 
483:         // Use "aSize" to build up the minimum size. Start with the size of the
484:         // name compartment and build up.
485: 
486:         Dimension aSize = _name.getMinimumSize();
487:         int h = aSize.height;
488:         int w = aSize.width;
489: 
490:         // Ensure that the minimum height of the name compartment is at least
491:         // 21 pixels (hardcoded).
492: 
493:         if (aSize.height < 21) {
494:             aSize.height = 21;
495:         }
496: 
497:         // If we have a stereotype displayed, then allow some space for that
498:         // (width and height)
499: 
500:         if (_stereo.isDisplayed()) {
501:             aSize.width = Math.max(aSize.width, _stereo.getMinimumSize().width);
502:             aSize.height += STEREOHEIGHT;
503:         }
504: 
505:         // Allow space for each of the attributes we have
506: 
507:         if (_attrVec.isDisplayed()) {
508: 
509:             // Loop through all the attributes, to find the widest (remember
510:             // the first fig is the box for the whole lot, so ignore it).
511: 
512:             Enumeration enum = _attrVec.getFigs().elements();
513:             enum.nextElement(); // ignore
514: 
515:             while (enum.hasMoreElements()) {
516:                 int elemWidth =
517:                     ((FigText) enum.nextElement()).getMinimumSize().width + 2;
518:                 aSize.width = Math.max(aSize.width, elemWidth);
519:             }
520: 
521:             // Height allows one row for each attribute (remember to ignore the
522:             // first element.
523: 
524:             aSize.height += ROWHEIGHT
525:                 * Math.max(1, _attrVec.getFigs().size() - 1)
526:                 + 1;
527:         }
528: 
529:         // Allow space for each of the operations we have
530: 
531:         if (_operVec.isDisplayed()) {
532: 
533:             // Loop through all the operations, to find the widest (remember
534:             // the first fig is the box for the whole lot, so ignore it).
535: 
536:             Enumeration enum = _operVec.getFigs().elements();
537:             enum.nextElement(); // ignore
538: 
539:             while (enum.hasMoreElements()) {
540:                 int elemWidth =
541:                     ((FigText) enum.nextElement()).getMinimumSize().width + 2;
542:                 aSize.width = Math.max(aSize.width, elemWidth);
543:             }
544: 
545:             aSize.height += ROWHEIGHT
546:                 * Math.max(1, _operVec.getFigs().size() - 1)
547:                 + 1;
548:         }
549: 
550:         // we want to maintain a minimum width for the class
551:         aSize.width = Math.max(60, aSize.width);
552: 
553:         // And now aSize has the answer
554: 
555:         return aSize;
556:     }
