873:     protected void updateStereotypeText() {
874: 
875:         MModelElement me = (MModelElement) getOwner();
876: 
877:         if (me == null) {
878:             return;
879:         }
880: 
881:         Rectangle rect = getBounds();
882:         MStereotype stereo = me.getStereotype();
883: 
884:         if ((stereo == null)
885:             || (stereo.getName() == null)
886:             || (stereo.getName().length() == 0)) {
887: 
888:             if (_stereo.isDisplayed()) {
889:                 _stereoLineBlinder.setDisplayed(false);
890:                 _stereo.setDisplayed(false);
891:                 rect.y += STEREOHEIGHT;
892:                 rect.height -= STEREOHEIGHT;
893:                 setBounds(rect.x, rect.y, rect.width, rect.height);
894:             }
895:         } else {
896:             _stereo.setText(Notation.generateStereotype(this, stereo));
897: 
898:             if (!_stereo.isDisplayed()) {
899:                 _stereoLineBlinder.setDisplayed(true);
900:                 _stereo.setDisplayed(true);
901: 
902:                 // Only adjust the stereotype height if we are not newly
903:                 // created. This gets round the problem of loading classes with
904:                 // stereotypes defined, which have the height already including
905:                 // the stereotype.
906: 
907:                 if (!_newlyCreated) {
908:                     rect.y -= STEREOHEIGHT;
909:                     rect.height += STEREOHEIGHT;
910:                     setBounds(rect.x, rect.y, rect.width, rect.height);
911:                 }
912: 
913:             }
914:         }
915: 
916:         // Whatever happened we are no longer newly created, so clear the
917:         // flag. Then set the bounds for the rectangle we have defined.
918: 
919:         _newlyCreated = false;
920: 
921:     }
