923:     /**
924:      * <p>Sets the bounds, but the size will be at least the one returned by
925:      *   {@link #getMinimumSize()}, unless checking of size is disabled.</p>
926:      *
927:      * <p>If the required height is bigger, then the additional height is
928:      *   equally distributed among all figs (i.e. compartments), such that the
929:      *   cumulated height of all visible figs equals the demanded height<p>.
930:      *
931:      * <p>Some of this has "magic numbers" hardcoded in. In particular there is
932:      *   a knowledge that the minimum height of a name compartment is 21
933:      *   pixels.</p>
934:      *
935:      * @param x  Desired X coordinate of upper left corner
936:      *
937:      * @param y  Desired Y coordinate of upper left corner
938:      *
939:      * @param w  Desired width of the FigClass
940:      *
941:      * @param h  Desired height of the FigClass
942:      */
943:     public void setBounds(int x, int y, int w, int h) {
944: 
945:         // Save our old boundaries (needed later), and get minimum size
946:         // info. "aSize will be used to maintain a running calculation of our
947:         // size at various points.
948: 
949:         // "extra_each" is the extra height per displayed fig if requested
950:         // height is greater than minimal. "height_correction" is the height
951:         // correction due to rounded division result, will be added to the name
952:         // compartment
953: 
954:         Rectangle oldBounds = getBounds();
955:         Dimension aSize = checkSize ? getMinimumSize() : new Dimension(w, h);
956: 
957:         int newW = Math.max(w, aSize.width);
958:         int newH = h;
959: 
960:         int extra_each = 0;
961:         int height_correction = 0;
962: 
963:         // First compute all nessessary height data. Easy if we want less than
964:         // the minimum
965: 
966:         if (newH <= aSize.height) {
967: 
968:             // Just use the mimimum
969: 
970:             newH = aSize.height;
971: 
972:         } else {
973: 
974:             // Split the extra amongst the number of displayed compartments
975: 
976:             int displayedFigs = 1; //this is for _name
977: 
978:             if (_attrVec.isDisplayed()) {
979:                 displayedFigs++;
980:             }
981: 
982:             if (_operVec.isDisplayed()) {
983:                 displayedFigs++;
984:             }
985: 
986:             // Calculate how much each, plus a correction to put in the name
987:             // comparment if the result is rounded
988: 
989:             extra_each = (newH - aSize.height) / displayedFigs;
990:             height_correction =
991:                 (newH - aSize.height) - (extra_each * displayedFigs);
992:         }
993: 
994:         // Now resize all sub-figs, including not displayed figs. Start by the
995:         // name. We override the getMinimumSize if it is less than our view (21
996:         // pixels hardcoded!). Add in the shared extra, plus in this case the
997:         // correction.
998: 
999:         int height = _name.getMinimumSize().height;
1000: 
1001:         if (height < 21) {
1002:             height = 21;
1003:         }
1004: 
1005:         height += extra_each + height_correction;
1006: 
1007:         // Now sort out the stereotype display. If the stereotype is displayed,
1008:         // move the upper boundary of the name compartment up and set new
1009:         // bounds for the name and the stereotype compatments and the
1010:         // stereoLineBlinder that blanks out the line between the two
1011: 
1012:         int currentY = y;
1013: 
1014:         if (_stereo.isDisplayed()) {
1015:             currentY += STEREOHEIGHT;
1016:         }
1017: 
1018:         _name.setBounds(x, currentY, newW, height);
1019:         _stereo.setBounds(x, y, newW, STEREOHEIGHT + 1);
1020:         _stereoLineBlinder.setBounds(x + 1, y + STEREOHEIGHT, newW - 2, 2);
1021: 
1022:         // Advance currentY to where the start of the attribute box is,
1023:         // remembering that it overlaps the next box by 1 pixel. Calculate the
1024:         // size of the attribute box, and update the Y pointer past it if it is
1025:         // displayed.
1026: 
1027:         currentY += height - 1; // -1 for 1 pixel overlap
1028: 
1029:         int na =
1030:             (_attrVec.isDisplayed())
1031:                 ? Math.max(1, _attrVec.getFigs().size() - 1)
1032:                 : 0;
1033:         int no =
1034:             (_operVec.isDisplayed())
1035:                 ? Math.max(1, _operVec.getFigs().size() - 1)
1036:                 : 0;
1037:         if (checkSize) {
1038:             height = ROWHEIGHT * na + 2 + extra_each;
1039:         } else if (newH > currentY - y && na + no > 0) {
1040:             height = (newH + y - currentY) * na / (na + no) + 1;
1041:         } else {
1042:             height = 1;
1043:         }
1044:         aSize = getUpdatedSize(_attrVec, x, currentY, newW, height);
1045: 
1046:         if (_attrVec.isDisplayed()) {
1047:             currentY += aSize.height - 1; // -1 for 1 pixel overlap
1048:         }
1049: 
1050:         // Finally update the bounds of the operations box
1051: 
1052:         aSize =
1053:             getUpdatedSize(_operVec, x, currentY, newW, newH + y - currentY);
1054: 
1055:         // set bounds of big box
1056: 
1057:         _bigPort.setBounds(x, y, newW, newH);
1058: 
1059:         // Now force calculation of the bounds of the figure, update the edges
1060:         // and trigger anyone who's listening to see if the "bounds" property
1061:         // has changed.
1062: 
1063:         calcBounds();
1064:         updateEdges();
1065:         firePropChange("bounds", oldBounds, getBounds());
1066:     }
