120:     /**
121:      * <p>Main constructor for a {@link FigInterface}.</p>
122:      *
123:      * <p>Parent {@link FigNodeModelElement} will have created the main box
124:      *   {@link #_bigPort} and its name {@link #_name} and stereotype (@link
125:      *   #_stereo}. This constructor creates a box for the operations.</p>
126:      *
127:      * <p>The properties of all these graphic elements are adjusted
128:      *   appropriately. The main boxes are all filled and have outlines.</p>
129:      *
130:      * <p>For reasons I don't understand the stereotype is created in a box
131:      *   with lines. So we have to created a blanking rectangle to overlay the
132:      *   bottom line, and avoid three compartments showing.</p>
133:      *
134:      * <p><em>Warning</em>. Much of the graphics positioning is hard coded. The
135:      *   overall figure is placed at location (10,10). The name compartment (in
136:      *   the parent {@link FigNodeModelElement} is 21 pixels high. The
137:      *   stereotype compartment is created 15 pixels high in the parent, but we
138:      *   change it to 19 pixels, 1 more than ({@link #STEREOHEIGHT} here. The
139:      *   operations box is created at 19 pixels, 2 more than
140:      *   {@link #ROWHEIGHT}.</p>
141:      *
142:      * <p>CAUTION: This constructor (with no arguments) is the only one
143:      *   that does enableSizeChecking(false), all others must set it true.
144:      *   This is because this constructor is the only one called when loading
145:      *   a project. In this case, the parsed size must be maintained.</p>
146:      */
147: 
148:     public FigInterface() {
149: 
150:         // Set name box. Note the upper line will be blanked out if there is
151:         // eventually a stereotype above.
152:         _name.setLineWidth(1);
153:         _name.setFilled(true);
154: 
155:         // this rectangle marks the operation section; all operations are inside it:
156:         _operBigPort =
157:             new FigRect(
158:                 10,
159:                 31 + ROWHEIGHT,
160:                 60,
161:                 ROWHEIGHT + 2,
162:                 Color.black,
163:                 Color.white);
164:         _operBigPort.setFilled(true);
165:         _operBigPort.setLineWidth(1);
166: 
167:         _operVec = new FigGroup();
168:         _operVec.setFilled(true);
169:         _operVec.setLineWidth(1);
170:         _operVec.addFig(_operBigPort);
171: 
172:         // Set properties of the stereotype box. Make it 1 pixel higher than
173:         // before, so it overlaps the name box, and the blanking takes out both
174:         // lines. Initially not set to be displayed, but this will be changed
175:         // when we try to render it, if we find we have a stereotype.
176:         _stereo.setText(
177:             NotationHelper.getLeftGuillemot()
178:                 + "Interface"
179:                 + NotationHelper.getRightGuillemot());
180:         _stereo.setExpandOnly(true);
181:         _stereo.setFilled(true);
182:         _stereo.setLineWidth(1);
183:         _stereo.setEditable(false);
184:         _stereo.setHeight(STEREOHEIGHT + 1);
185:         // +1 to have 1 pixel overlap with _name
186:         _stereo.setDisplayed(true);
187: 
188:         // A thin rectangle to overlap the boundary line between stereotype
189:         // and name. This is just 2 pixels high, and we rely on the line
190:         // thickness, so the rectangle does not need to be filled. Whether to
191:         // display is linked to whether to display the stereotype.
192:         _stereoLineBlinder =
193:             new FigRect(11, 10 + STEREOHEIGHT, 58, 2, Color.white, Color.white);
194:         _stereoLineBlinder.setLineWidth(1);
195:         _stereoLineBlinder.setDisplayed(true);
196: 
197:         // Put all the bits together, suppressing bounds calculations until
198:         // we're all done for efficiency.
199:         enableSizeChecking(false);
200:         suppressCalcBounds = true;
201:         addFig(_bigPort);
202:         addFig(_stereo);
203:         addFig(_name);
204:         addFig(_stereoLineBlinder);
205:         addFig(_operVec);
206:         suppressCalcBounds = false;
207: 
208:         // Set the bounds of the figure to the total of the above (hardcoded)
209:         setBounds(10, 10, 60, 21 + ROWHEIGHT);
210:     }
