321:     public void setOperationVisible(boolean isVisible) {
322:         Rectangle rect = getBounds();
323:         int h =
324:             checkSize
325:                 ? (ROWHEIGHT * Math.max(1, _operVec.getFigs().size() - 1) + 2)
326:                     * rect.height
327:                     / getMinimumSize().height
328:                 : 0;
329:         if (_operVec.isDisplayed()) {
330:             if (!isVisible) {
331:                 damage();
332:                 Enumeration enum = _operVec.getFigs().elements();
333:                 while (enum.hasMoreElements())
334:                      ((Fig) (enum.nextElement())).setDisplayed(false);
335:                 _operVec.setDisplayed(false);
336:                 setBounds(rect.x, rect.y, rect.width, rect.height - h);
337:             }
338:         } else {
339:             if (isVisible) {
340:                 Enumeration enum = _operVec.getFigs().elements();
341:                 while (enum.hasMoreElements())
342:                      ((Fig) (enum.nextElement())).setDisplayed(true);
343:                 _operVec.setDisplayed(true);
344:                 setBounds(rect.x, rect.y, rect.width, rect.height + h);
345:                 damage();
346:             }
347:         }
348:     }
