350:     /**
351:      * <p>Gets the minimum size permitted for an interface on the diagram.</p>
352:      *
353:      * <p>Parts of this are hardcoded, notably the fact that the name
354:      *   compartment has a minimum height of 21 pixels.</p>
355:      *
356:      * @return  the size of the minimum bounding box.
357:      */
358:     public Dimension getMinimumSize() {
359: 
360:         // Use "aSize" to build up the minimum size. Start with the size of the
361:         // name compartment and build up.
362: 
363:         Dimension aSize = _name.getMinimumSize();
364:         int h = aSize.height;
365:         int w = aSize.width;
366: 
367:         // Ensure that the minimum height of the name compartment is at least
368:         // 21 pixels (hardcoded).
369: 
370:         if (aSize.height < 21)
371:             aSize.height = 21;
372: 
373:         // If we have a stereotype displayed, then allow some space for that
374:         // (width and height)
375: 
376:         if (_stereo.isDisplayed()) {
377:             aSize.width = Math.max(aSize.width, _stereo.getMinimumSize().width);
378:             aSize.height += STEREOHEIGHT;
379:         }
380: 
381:         // Allow space for each of the operations we have
382: 
383:         if (_operVec.isDisplayed()) {
384: 
385:             // Loop through all the operations, to find the widest (remember
386:             // the first fig is the box for the whole lot, so ignore it).
387: 
388:             Enumeration enum = _operVec.getFigs().elements();
389:             enum.nextElement(); // ignore
390: 
391:             while (enum.hasMoreElements()) {
392:                 int elemWidth =
393:                     ((FigText) enum.nextElement()).getMinimumSize().width + 2;
394:                 aSize.width = Math.max(aSize.width, elemWidth);
395:             }
396:             aSize.height += ROWHEIGHT
397:                 * Math.max(1, _operVec.getFigs().size() - 1)
398:                 + 1;
399:         }
400: 
401:         // we want to maintain a minimum width for Interfaces
402:         aSize.width = Math.max(60, aSize.width);
403: 
404:         // And now aSize has the answer
405: 
406:         return aSize;
407:     }
