430:     public void mouseClicked(MouseEvent me) {
431:         super.mousePressed(me);
432:         boolean targetIsSet = false;
433:         int i = 0;
434:         Editor ce = Globals.curEditor();
435:         Selection sel = ce.getSelectionManager().findSelectionFor(this);
