444:             i =
445:                 (v.size() - 1)
446:                     * (me.getY() - f.getY() - 3)
447:                     / _operVec.getHeight();
448:             if (i >= 0 && i < v.size() - 1) {
449:                 targetIsSet = true;
450:                 me.consume();
