452:                 ((CompartmentFigText) f).setHighlighted(true);
453:                 highlightedFigText = (CompartmentFigText) f;
454:                 ProjectBrowser.TheInstance.setTarget(f);
455:             }
456:         }
457:         if (targetIsSet == false) {
458:             me.consume();
459:             ProjectBrowser.TheInstance.setTarget(getOwner());
460:         }
