497:     public void setEnclosingFig(Fig encloser) {
498:         Fig oldEncloser = getEnclosingFig();
499:         super.setEnclosingFig(encloser);
500:         if (!(getOwner() instanceof MModelElement))
501:             return;
502:         MModelElement me = (MModelElement) getOwner();
503:         MNamespace m = null;
504:         ProjectBrowser pb = ProjectBrowser.TheInstance;
505: 
506:         try {
507:             // If moved into an Package
508:             if (encloser != null
509:                 && oldEncloser != encloser
510:                 && encloser.getOwner() instanceof MPackage) {
511:                 me.setNamespace((MNamespace) encloser.getOwner());
512:             }
513: 
514:             // If default Namespace is not already set
515:             if (me.getNamespace() == null
516:                 && pb.getTarget() instanceof UMLDiagram) {
517:                 m = (MNamespace) ((UMLDiagram) pb.getTarget()).getNamespace();
518:                 me.setNamespace(m);
519:             }
520:         } catch (Exception e) {
521:             cat.error(
522:                 "could not set package due to:" + e + "' at " + encloser,
523:                 e);
524:         }
525: 
526:         // The next if-clause is important for the Deployment-diagram
527:         // it detects if the enclosing fig is a component, in this case
528:         // the ImplementationLocation will be set for the owning MInterface
529:         if (encloser != null && (encloser.getOwner() instanceof MComponent)) {
530:             MComponent component = (MComponent) encloser.getOwner();
531:             MInterface in = (MInterface) getOwner();
532:             resident.setImplementationLocation(component);
533:             resident.setResident(in);
534:         } else {
535:             resident.setImplementationLocation(null);
536:             resident.setResident(null);
537:         }
538:     }
