566:     protected FigText getPreviousVisibleFeature(FigText ft, int i) {
567:         FigText ft2 = null;
568:         Vector v = _operVec.getFigs();
569:         if (i < 1
570:             || i >= v.size()
571:             || !((FigText) v.elementAt(i)).isDisplayed())
572:             return null;
573:         do {
574:             i--;
575:             if (i < 1)
576:                 i = v.size() - 1;
577:             ft2 = (FigText) v.elementAt(i);
578:             if (!ft2.isDisplayed())
579:                 ft2 = null;
580:         } while (ft2 == null);
581:         return ft2;
582:     }
