584:     protected FigText getNextVisibleFeature(FigText ft, int i) {
585:         FigText ft2 = null;
586:         Vector v = _operVec.getFigs();
587:         if (i < 1
588:             || i >= v.size()
589:             || !((FigText) v.elementAt(i)).isDisplayed())
590:             return null;
591:         do {
592:             i++;
593:             if (i >= v.size())
594:                 i = 1;
595:             ft2 = (FigText) v.elementAt(i);
596:             if (!ft2.isDisplayed())
597:                 ft2 = null;
598:         } while (ft2 == null);
599:         return ft2;
600:     }
