704:     /**
705:      * <p>Sets the bounds, but the size will be at least the one returned by
706:      *   {@link #getMinimumSize()}, unless checking of size is disabled.</p>
707:      *
708:      * <p>If the required height is bigger, then the additional height is
709:      *   equally distributed among all figs (i.e. compartments), such that the
710:      *   cumulated height of all visible figs equals the demanded height<p>.
711:      *
712:      * <p>Some of this has "magic numbers" hardcoded in. In particular there is
713:      *   a knowledge that the minimum height of a name compartment is 21
714:      *   pixels.</p>
715:      *
716:      * @param x  Desired X coordinate of upper left corner
717:      *
718:      * @param y  Desired Y coordinate of upper left corner
719:      *
720:      * @param w  Desired width of the FigInterface
721:      *
722:      * @param h  Desired height of the FigInterface
723:      */
724:     public void setBounds(int x, int y, int w, int h) {
725: 
726:         // Save our old boundaries (needed later), and get minimum size
727:         // info. "aSize will be used to maintain a running calculation of our
728:         // size at various points.
729: 
730:         // "extra_each" is the extra height per displayed fig if requested
731:         // height is greater than minimal. "height_correction" is the height
732:         // correction due to rounded division result, will be added to the name
733:         // compartment
734: 
735:         Rectangle oldBounds = getBounds();
736:         Dimension aSize = checkSize ? getMinimumSize() : new Dimension(w, h);
737: 
738:         int newW = Math.max(w, aSize.width);
739:         int newH = h;
740: 
741:         int extra_each = 0;
742:         int height_correction = 0;
743: 
744:         // First compute all nessessary height data. Easy if we want less than
745:         // the minimum
746: 
747:         if (newH <= aSize.height) {
748: 
749:             // Just use the mimimum
750: 
751:             newH = aSize.height;
752: 
753:         } else {
754: 
755:             // Split the extra amongst the number of displayed compartments
756: 
757:             int displayedFigs = 1; //this is for _name
758: 
759:             if (_operVec.isDisplayed()) {
760:                 displayedFigs++;
761:             }
762: 
763:             // Calculate how much each, plus a correction to put in the name
764:             // comparment if the result is rounded
765: 
766:             extra_each = (newH - aSize.height) / displayedFigs;
767:             height_correction =
768:                 (newH - aSize.height) - (extra_each * displayedFigs);
769:         }
770: 
771:         // Now resize all sub-figs, including not displayed figs. Start by the
772:         // name. We override the getMinimumSize if it is less than our view (21
773:         // pixels hardcoded!). Add in the shared extra, plus in this case the
774:         // correction.
775: 
776:         int height = _name.getMinimumSize().height;
777: 
778:         if (height < 21) {
779:             height = 21;
780:         }
781: 
782:         height += extra_each + height_correction;
783: 
784:         // Now sort out the stereotype display. If the stereotype is displayed,
785:         // move the upper boundary of the name compartment up and set new
786:         // bounds for the name and the stereotype compatments and the
787:         // stereoLineBlinder that blanks out the line between the two
788: 
789:         int currentY = y;
790: 
791:         if (_stereo.isDisplayed()) {
792:             currentY += STEREOHEIGHT;
793:         }
794: 
795:         _name.setBounds(x, currentY, newW, height);
796:         _stereo.setBounds(x, y, newW, STEREOHEIGHT + 1);
797:         _stereoLineBlinder.setBounds(x + 1, y + STEREOHEIGHT, newW - 2, 2);
798: 
799:         // Advance currentY to where the start of the attribute box is,
800:         // remembering that it overlaps the next box by 1 pixel. Calculate the
801:         // size of the attribute box, and update the Y pointer past it if it is
802:         // displayed.
803: 
804:         currentY += height - 1; // -1 for 1 pixel overlap
805: 
806:         // Finally update the bounds of the operations box
807: 
808:         aSize =
809:             getUpdatedSize(_operVec, x, currentY, newW, newH + y - currentY);
810: 
811:         // set bounds of big box
812: 
813:         _bigPort.setBounds(x, y, newW, newH);
814: 
815:         // Now force calculation of the bounds of the figure, update the edges
816:         // and trigger anyone who's listening to see if the "bounds" property
817:         // has changed.
818: 
819:         calcBounds();
820:         updateEdges();
821:         firePropChange("bounds", oldBounds, getBounds());
822:     }
