451:     /**
452:      * Builds a default binary association with two default association ends.
453:      * @param c1 The first classifier to connect to
454:      * @param nav1 The navigability of the Associaton end
455:      * @param agg1 The aggregation type of the second Associaton end
456:      * @param c2 The second classifier to connect to
457:      * @param nav2 The navigability of the second Associaton end
458:      * @param agg2 The aggregation type of the second Associaton end
459:      * @return MAssociation
460:      * @throws IllegalArgumentException if either Classifier is null
461:      */
462:     private MAssociation buildAssociation(MClassifier c1,
463: 					 boolean nav1,
464: 					 MAggregationKind agg1,
465: 					 MClassifier c2,
466: 					 boolean nav2,
467: 					 MAggregationKind agg2) {
468:         if (c1 == null || c2 == null) {
469:             throw new IllegalArgumentException("one of "
470: 					       + "the classifiers to be "
471: 					       + "connected is null");
472:         }
473:         MNamespace ns1 = c1.getNamespace();
474:         MNamespace ns2 = c2.getNamespace();
475:         if (ns1 == null || ns2 == null) {
476:             throw new IllegalArgumentException("one of "
477: 					       + "the classifiers does not "
478: 					       + "belong to a namespace");
479:         }
480:         MAssociation assoc = (MAssociation) createAssociation();
481:         assoc.setName("");
482:         assoc.setNamespace(
483:                 (MNamespace) nsmodel.getCoreHelper()
484:                 	.getFirstSharedNamespace(ns1, ns2));
485:         buildAssociationEnd(
486: 			    assoc,
487: 			    null,
488: 			    c1,
489: 			    null,
490: 			    null,
491: 			    nav1,
492: 			    null,
493: 			    agg1,
494: 			    null,
495: 			    null,
496: 			    null);
497:         buildAssociationEnd(
498: 			    assoc,
499: 			    null,
500: 			    c2,
501: 			    null,
502: 			    null,
503: 			    nav2,
504: 			    null,
505: 			    agg2,
506: 			    null,
507: 			    null,
508: 			    null);
509:         return assoc;
510:     }
