512:     /**
513:      * Builds a binary associationrole on basis of two classifierroles,
514:      * navigation and aggregation.
515:      *
516:      * @param fromClassifier   the first given classifier
517:      * @param aggregationKind1 the first aggregationkind
518:      * @param toClassifier     the second given classifier
519:      * @param aggregationKind2 the second aggregationkind
520:      * @param unidirectional true if unidirectional
521:      * @return the newly build binary associationrole
522:      */
523:     public Object buildAssociation(
524: 					 Object fromClassifier,
525: 					 Object aggregationKind1,
526: 					 Object toClassifier,
527: 					 Object aggregationKind2,
528: 					 Boolean unidirectional) {
529:         if (fromClassifier == null || toClassifier == null) {
530:                 throw new IllegalArgumentException("one of "
531:         				       + "the classifiers to be "
532:         				       + "connected is null");
533:         }
534:         MClassifier from = (MClassifier) fromClassifier;
535:         MClassifier to = (MClassifier) toClassifier;
536:         MAggregationKind agg1 = (MAggregationKind) aggregationKind1;
537:         MAggregationKind agg2 = (MAggregationKind) aggregationKind2;
538: 
539:         MNamespace ns1 = from.getNamespace();
540:         MNamespace ns2 = to.getNamespace();
541:         if (ns1 == null || ns2 == null) {
542:                 throw new IllegalArgumentException("one of "
543:         				       + "the classifiers does not "
544:         				       + "belong to a namespace");
545:         }
546:         MAssociation assoc = (MAssociation) createAssociation();
547:         assoc.setName("");
548:         assoc.setNamespace((MNamespace)
549:         		   nsmodel.getCoreHelper().getFirstSharedNamespace(ns1,
550:         								  ns2));
551: 
552:         boolean nav1 = true;
553:         boolean nav2 = true;
554: 
555:         if (from instanceof MInterface) {
556:             nav2 = false;
557:             agg2 = agg1;
558:             agg1 = null;
559:         } else if (to instanceof MInterface) {
560:             nav1 = false;
561:         } else {
562:             nav1 = !Boolean.TRUE.equals(unidirectional);
563:             nav2 = true;
564:         }
565: 
566:         buildAssociationEnd(
567: 			    assoc,
568: 			    null,
569: 			    from,
570: 			    null,
571: 			    null,
572: 			    nav1,
573: 			    null,
574: 			    agg1,
575: 			    null,
576: 			    null,
577: 			    null);
578:         buildAssociationEnd(
579: 			    assoc,
580: 			    null,
581: 			    to,
582: 			    null,
583: 			    null,
584: 			    nav2,
585: 			    null,
586: 			    agg2,
587: 			    null,
588: 			    null,
589: 			    null);
590: 
591:         return assoc;
592:     }
