1432:     /**
1433:      * Builds a realization between some supplier (for example an
1434:      * interface in Java) and a client who implements the realization.
1435:      *
1436:      * @param clnt is the client
1437:      * @param spplr is the supplier
1438:      * @param model the namespace to use if client and
1439:      *              supplier are of different namespace
1440:      * @return Object the created abstraction
1441:      */
1442:     public Object buildRealization(
1443:             Object clnt,
1444:             Object spplr,
1445:             Object model) {
1446:         MModelElement client = (MModelElement) clnt;
1447:         MModelElement supplier = (MModelElement) spplr;
1448: 	if (client == null
1449: 	    || supplier == null
1450: 	    || client.getNamespace() == null
1451: 	    || supplier.getNamespace() == null) {
1452: 	    throw new IllegalArgumentException("faulty arguments.");
1453: 	}
1454: 	Object realization = createAbstraction();
1455: 	MNamespace nsc = client.getNamespace();
1456: 	MNamespace nss = supplier.getNamespace();
1457: 	MNamespace ns = null;
1458: 	if (nsc.equals(nss)) {
1459: 	    ns = nsc;
1460: 	} else {
1461: 	    ns = (MNamespace) model;
1462: 	}
1463: 	nsmodel.getExtensionMechanismsFactory().buildStereotype(realization,
1464: 								"realize", ns);
1465: 	nsmodel.getCoreHelper().addClientDependency(client, realization);
1466: 	nsmodel.getCoreHelper().addSupplierDependency(supplier, realization);
1467: 	return realization;
1468:     }
