1470:     /**
1471:      * Builds a usage between some client and a supplier. If client
1472:      * and supplier do not have the same model, an
1473:      * {@link IllegalArgumentException} is thrown.
1474:      *
1475:      * @param client is the client
1476:      * @param supplier is the supplier
1477:      * @return MUsage
1478:      */
1479:     public Object buildUsage(Object client, Object supplier) {
1480: 	if (client == null || supplier == null) {
1481: 	    throw new IllegalArgumentException("In buildUsage null arguments.");
1482: 	}
1483: 	if (!(client instanceof MModelElement)) {
1484: 	    throw new IllegalArgumentException("client ModelElement");
1485: 	}
1486: 	if (!(supplier instanceof MModelElement)) {
1487: 	    throw new IllegalArgumentException("supplier ModelElement");
1488: 	}
1489: 
1490: 	if (((MModelElement) client).getModel()
1491: 	        != ((MModelElement) supplier).getModel()) {
1492: 	    throw new IllegalArgumentException("To construct a usage, the "
1493: 					       + "client and the supplier "
1494: 					       + "must be part of the same "
1495: 					       + "model.");
1496: 	}
1497: 	MUsage usage = (MUsage) nsmodel.getCoreFactory().createUsage();
1498: 	usage.addSupplier((MModelElement) supplier);
1499: 	usage.addClient((MModelElement) client);
1500: 	if (((MModelElement) supplier).getNamespace() != null) {
1501: 	    usage.setNamespace(((MModelElement) supplier).getNamespace());
1502: 	} else if (((MModelElement) client).getNamespace() != null) {
1503: 	    usage.setNamespace(((MModelElement) client).getNamespace());
1504: 	}
1505: 	return usage;
1506:     }
