1836:      * of the element. Does not do an cascading delete for elements that
1837:      * are deleted by the NSUML method remove. This method should not be called
1838:      * directly.<p>
1839:      *
1840:      * In the case of a modelelement these are the following elements:<ul>
1841:      * <li>Dependencies that have the modelelement as supplier or as a client
1842:      * and are binary. (that is, they only have one supplier and one client)
1843:      * </ul>
1844:      *
1845:      * @param elem
1846:      * @see UmlFactoryImpl#delete(Object)
1847:      */
1848:     void deleteModelElement(Object elem) {
1849:         if (!(elem instanceof MModelElement)) {
1850:             throw new IllegalArgumentException();
1851:         }
1852: 
1853: 	Collection supplierDep =
1854: 	    ((MModelElement) elem).getSupplierDependencies();
1855: 	Collection clientDep =
1856: 	    ((MModelElement) elem).getClientDependencies();
1857: 	Set deps = new HashSet();
1858: 	deps.addAll(supplierDep);
1859: 	deps.addAll(clientDep);
1860: 	Iterator it = deps.iterator();
1861: 	while (it.hasNext()) {
1862: 	    MDependency dep = (MDependency) it.next();
1863: 	    Collection clients = dep.getClients();
1864: 	    Collection suppliers = dep.getSuppliers();
1865: 	    if ((clients.size() + suppliers.size()) == 2) {
1866: 		nsmodel.getUmlFactory().delete(dep);
1867: 	    }
1868: 	}
1869: 
1870:         List ownedBehaviors = new ArrayList();
1871:         ownedBehaviors.addAll(((MModelElement) elem).getBehaviors());
1872:         it = ownedBehaviors.iterator();
1873:         while (it.hasNext()) {
1874:             nsmodel.getUmlFactory().delete(it.next());
1875:         }
1876:     }
