656:     /**
657:      * Builds a fully configurable association end. All variables for
658:      * an associationend can be given as parameter.
659:      *
660:      * @param assoc The associaton this end will be part of
661:      * @param name The name of the association end
662:      * @param type The type (classifier) the end will connect. The end
663:      * is a connection piece between an association and a classifier
664:      * @param multi The multiplicity
665:      * @param stereo The stereotype
666:      * @param navigable The navigability. True if this association end
667:      *                  can be 'passed' from the other classifier.
668:      * @param order Ordering of the association
669:      * @param aggregation the aggregationkind
670:      * @param scope the scope kind
671:      * @param changeable the changeablekind
672:      * @param visibility the visibilitykind
673:      * @return MAssociationEnd
674:      */
675:     public Object buildAssociationEnd(
676: 					       Object assoc,
677: 					       String name,
678: 					       Object type,
679: 					       Object multi,
680: 					       Object stereo,
681: 					       boolean navigable,
682: 					       Object order,
683: 					       Object aggregation,
684: 					       Object scope,
685: 					       Object changeable,
686: 					       Object visibility) {
687:         // wellformednessrules and preconditions
688:         if (assoc == null
689:                 || !(assoc instanceof MAssociation)
690:                 || type == null
691:                 || !(type instanceof MClassifier)) {
692:             throw new IllegalArgumentException("either type or association "
693: 					       + "are null");
694:         }
695:         if (multi != null
696:                 && !(multi instanceof MMultiplicity)) {
697:             throw new IllegalArgumentException("Multiplicity");
698:         }
699:         if (stereo != null
700:                 && !(stereo instanceof MStereotype)) {
701:             throw new IllegalArgumentException("Stereotype");
702:         }
703:         if (order != null
704:                 && !(order instanceof MOrderingKind)) {
705:             throw new IllegalArgumentException("OrderingKind");
706:         }
707:         if (aggregation != null
708:                 && !(aggregation instanceof MAggregationKind)) {
709:             throw new IllegalArgumentException("AggregationKind");
710:         }
711:         if (scope != null
712:                 && !(scope instanceof MScopeKind)) {
713:             throw new IllegalArgumentException("ScopeKind");
714:         }
715:         if (changeable != null
716:                 && !(changeable instanceof MChangeableKind)) {
717:             throw new IllegalArgumentException("ChangeableKind");
718:         }
719:         if (visibility != null
720:                 && !(visibility instanceof MVisibilityKind)) {
721:             throw new IllegalArgumentException("VisibilityKind");
722:         }
723: 
724:         if (type instanceof MDataType || type instanceof MInterface) {
725:             if (!navigable) {
726:                 throw new IllegalArgumentException(
727:                         "Wellformedness rule 2.5.3.3 [1] is broken. "
728:                         + "The Classifier of an AssociationEnd cannot be an "
729:                         + "Interface or a DataType if the association is "
730:                         + "navigable away from that end.");
731:             }
732:             List ends = new ArrayList();
733:             ends.addAll(((MAssociation) assoc).getConnections());
734:             Iterator it = ends.iterator();
735:             while (it.hasNext()) {
736:                 MAssociationEnd end = (MAssociationEnd) it.next();
737:                 if (end.isNavigable()) {
738:                     throw new IllegalArgumentException("type is either "
739: 						       + "datatype or "
740: 						       + "interface and is "
741: 						       + "navigable to");
742:                 }
743:             }
744:         }
745:         if (aggregation != null
746:                 && aggregation.equals(MAggregationKind.COMPOSITE)
747:                 && multi != null
748:                 && ((MMultiplicity) multi).getUpper() > 1) {
749:             throw new IllegalArgumentException("aggregation is composite "
750: 					   + "and multiplicity > 1");
751:         }
752: 
753:         MAssociationEnd end =
754:             (MAssociationEnd)
755:             	nsmodel.getCoreFactory().createAssociationEnd();
756:         end.setAssociation((MAssociation) assoc);
757:         end.setType((MClassifier) type);
758:         end.setName(name);
759:         if (multi != null) {
760:             end.setMultiplicity((MMultiplicity) multi);
761:         } else {
762:             end.setMultiplicity(MMultiplicity.M1_1);
763:         }
764:         if (stereo != null) {
765:             end.setStereotype((MStereotype) stereo);
766:         }
767:         end.setNavigable(navigable);
768:         if (order != null) {
769:             end.setOrdering((MOrderingKind) order);
770:         } else {
771:             end.setOrdering(MOrderingKind.UNORDERED);
772:         }
773:         if (aggregation != null) {
774:             end.setAggregation((MAggregationKind) aggregation);
775:         } else {
776:             end.setAggregation(MAggregationKind.NONE);
777:         }
778:         if (scope != null) {
779:             end.setTargetScope((MScopeKind) scope);
780:         } else {
781:             end.setTargetScope(MScopeKind.INSTANCE);
782:         }
783:         if (changeable != null) {
784:             end.setChangeability((MChangeableKind) changeable);
785:         } else {
786:             end.setChangeability(MChangeableKind.CHANGEABLE);
787:         }
788:         if (visibility != null) {
789:             end.setVisibility((MVisibilityKind) visibility);
790:         } else {
791:             end.setVisibility(MVisibilityKind.PUBLIC);
792:         }
793:         return end;
794:     }
