1475:      * @param client is the client
1476:      * @param supplier is the supplier
1477:      * @return MUsage
1478:      */
1479:     public Object buildUsage(Object client, Object supplier) {
1480: 	if (client == null || supplier == null) {
1481: 	    throw new IllegalArgumentException("In buildUsage null arguments.");
1482: 	}
1483: 	if (!(client instanceof MModelElement)) {
