311:                 iconPos += icon.getIconWidth() + gap;
312:             }
313:         }
314:         items = list.elementsForOffender(this);
315:         size = items.size();
316:         for (int i = 0; i < size; i++) {
317:             ToDoItem item = (ToDoItem) items.elementAt(i);
318:             Icon icon = item.getClarifier();
319:             if (icon instanceof Clarifier) {
320:                 ((Clarifier) icon).setFig(this);
321:                 ((Clarifier) icon).setToDoItem(item);
322:             }
323:             if (icon != null) {
324:                 stuffPointAlongPerimeter(iconPos, p);
