248:     public Vector getPopUpActions(MouseEvent me) {
249:         Vector popUpActions = super.getPopUpActions(me);
250:         ToDoList list = Designer.theDesigner().getToDoList();
251:         Vector items = (Vector) list.elementsForOffender(getOwner()).clone();
252:         if (items != null && items.size() > 0) {
253:             ArgoJMenu critiques = new ArgoJMenu(BUNDLE, "menu.popup.critiques");
254:             ToDoItem itemUnderMouse = hitClarifier(me.getX(), me.getY());
255:             if (itemUnderMouse != null) {
256:                 critiques.add(new ActionGoToCritique(itemUnderMouse));
257:                 critiques.addSeparator();
258:             }
259:             int size = items.size();
260:             for (int i = 0; i < size; i++) {
261:                 ToDoItem item = (ToDoItem) items.elementAt(i);
262:                 if (item == itemUnderMouse)
263:                     continue;
264:                 critiques.add(new ActionGoToCritique(item));
265:             }
266:             popUpActions.insertElementAt(new JSeparator(), 0);
267:             popUpActions.insertElementAt(critiques, 0);
268:         }
269:         // POPUP_ADD_OFFSET should be equal to the number of items added here:
270:         popUpActions.addElement(new JSeparator());
271:         popUpActions.addElement(ActionProperties.getSingleton());
272:         popUpActions.addElement(ActionDeleteFromDiagram.getSingleton());
273:         return popUpActions;
274:     }
