277:     /**
278:      * distance formula: (x-h)^2 + (y-k)^2 = distance^2
279:      * 
280:      * @param p1 point
281:      * @param p2 point
282:      * @return the square of the distance
283:      */
284:     public int getSquaredDistance(Point p1, Point p2) {
285:         int xSquared = p2.x - p1.x;
286:         xSquared *= xSquared;
287:         int ySquared = p2.y - p1.y;
288:         ySquared *= ySquared;
289:         return xSquared + ySquared;
290:     }
