295:     public void paintClarifiers(Graphics g) {
296:         int iconPos = 25, gap = 1, xOff = -4, yOff = -4;
297:         Point p = new Point();
298:         ToDoList list = Designer.theDesigner().getToDoList();
299:         Vector items = list.elementsForOffender(getOwner());
300:         int size = items.size();
301:         for (int i = 0; i < size; i++) {
302:             ToDoItem item = (ToDoItem) items.elementAt(i);
303:             Icon icon = item.getClarifier();
304:             if (icon instanceof Clarifier) {
305:                 ((Clarifier) icon).setFig(this);
306:                 ((Clarifier) icon).setToDoItem(item);
307:             }
308:             if (icon != null) {
309:                 stuffPointAlongPerimeter(iconPos, p);
310:                 icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
311:                 iconPos += icon.getIconWidth() + gap;
312:             }
313:         }
314:         items = list.elementsForOffender(this);
315:         size = items.size();
316:         for (int i = 0; i < size; i++) {
317:             ToDoItem item = (ToDoItem) items.elementAt(i);
318:             Icon icon = item.getClarifier();
319:             if (icon instanceof Clarifier) {
320:                 ((Clarifier) icon).setFig(this);
321:                 ((Clarifier) icon).setToDoItem(item);
322:             }
323:             if (icon != null) {
324:                 stuffPointAlongPerimeter(iconPos, p);
325:                 icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
326:                 iconPos += icon.getIconWidth() + gap;
327:             }
328:         }
329:     }
