331:     public ToDoItem hitClarifier(int x, int y) {
332:         int iconPos = 25, xOff = -4, yOff = -4;
333:         Point p = new Point();
334:         ToDoList list = Designer.theDesigner().getToDoList();
335:         Vector items = list.elementsForOffender(getOwner());
336:         int size = items.size();
337:         for (int i = 0; i < size; i++) {
338:             ToDoItem item = (ToDoItem) items.elementAt(i);
339:             Icon icon = item.getClarifier();
340:             stuffPointAlongPerimeter(iconPos, p);
341:             int width = icon.getIconWidth();
342:             int height = icon.getIconHeight();
343:             if (y >= p.y + yOff
344:                 && y <= p.y + height + yOff
345:                 && x >= p.x + xOff
346:                 && x <= p.x + width + xOff)
347:                 return item;
348:             iconPos += width;
349:         }
350:         for (int i = 0; i < size; i++) {
351:             ToDoItem item = (ToDoItem) items.elementAt(i);
352:             Icon icon = item.getClarifier();
353:             if (icon instanceof Clarifier) {
354:                 ((Clarifier) icon).setFig(this);
355:                 ((Clarifier) icon).setToDoItem(item);
356:                 if (((Clarifier) icon).hit(x, y))
357:                     return item;
358:             }
359:         }
360:         items = list.elementsForOffender(this);
361:         size = items.size();
362:         for (int i = 0; i < size; i++) {
363:             ToDoItem item = (ToDoItem) items.elementAt(i);
364:             Icon icon = item.getClarifier();
365:             stuffPointAlongPerimeter(iconPos, p);
366:             int width = icon.getIconWidth();
367:             int height = icon.getIconHeight();
368:             if (y >= p.y + yOff
369:                 && y <= p.y + height + yOff
370:                 && x >= p.x + xOff
371:                 && x <= p.x + width + xOff)
372:                 return item;
373:             iconPos += width;
374:         }
375:         for (int i = 0; i < size; i++) {
376:             ToDoItem item = (ToDoItem) items.elementAt(i);
377:             Icon icon = item.getClarifier();
378:             if (icon instanceof Clarifier) {
379:                 ((Clarifier) icon).setFig(this);
380:                 ((Clarifier) icon).setToDoItem(item);
381:                 if (((Clarifier) icon).hit(x, y))
382:                     return item;
383:             }
384:         }
385:         return null;
386:     }
