587:     /**
588:      * generate the notation for the stereotype and stuff it into the text Fig
589:      */
590:     protected void updateStereotypeText() {
591:         if (getOwner() == null) {
592:             return;
593:         }
594:         Object stereotype = null;
595:         if (ModelFacade.getStereotypes(getOwner()).size() > 0) {
596:             stereotype =
597: 		ModelFacade.getStereotypes(getOwner()).iterator().next();
598:         }
599:         if (stereotype == null) {
600:             stereo.setText("");
601:             return;
602:         }
603:         String stereoStr = ModelFacade.getName(stereotype);
604:         if (stereoStr.length() == 0)
605:             stereo.setText("");
606:         else {
607:             stereo.setText(Notation.generateStereotype(this, stereotype));
608:         }
609:     }
