827:     /**
828:      * <p>Updates the classifiers the edge is attached to.  <p>Calls a
829:      * helper method (layoutThisToSelf) to avoid this edge
830:      * disappearing if the new source and dest are the same node.
831:      *
832:      * @return boolean whether or not the update was sucessful
833:      */
834:     protected boolean updateClassifiers() {
835:         Object owner = getOwner();
836:         if (owner == null || getLayer() == null)
837:             return false;
838: 
839:         Object newSource = getSource();
840:         Object newDest = getDestination();
841: 
842:         Fig currentSourceFig = getSourceFigNode();
843:         Fig currentDestFig = getDestFigNode();
844:         Object currentSource = null;
845:         Object currentDestination = null;
846:         if (currentSourceFig != null && currentDestFig != null) {
847:             currentSource = currentSourceFig.getOwner();
848:             currentDestination = currentDestFig.getOwner();
849:         }
850:         if (newSource != currentSource || newDest != currentDestination) {
851:             Fig newSourceFig = null;
852:             if (newSource != null)
853:                 newSourceFig = getLayer().presentationFor(newSource);
854:             Fig newDestFig = null;
855:             if (newDest != null)
856:                 newDestFig = getLayer().presentationFor(newDest);
857:             if (newSourceFig == null || newDestFig == null) {
858:                 removeFromDiagram();
859:                 return false;
860:             }
861:             if (newSourceFig != null && newSourceFig != currentSourceFig) {
862:                 setSourceFigNode((FigNode) newSourceFig);
863:                 setSourcePortFig(newSourceFig);
864: 
865:             }
866:             if (newDestFig != null && newDestFig != currentDestFig) {
867:                 setDestFigNode((FigNode) newDestFig);
868:                 setDestPortFig(newDestFig);
869:             }
870:             if (newDestFig != null && newSourceFig != null) {
871:                 ((FigNode) newSourceFig).updateEdges();
872:             }
873:             if (newSourceFig != null && newDestFig != null) {
874:                 ((FigNode) newDestFig).updateEdges();
875:             }
876:             calcBounds();
877: 
878:             // adapted from SelectionWButtons from line 280
879:             // calls a helper method to avoid this edge disappearing
880:             // if the new source and dest are the same node.
881:             if (newSourceFig == newDestFig) {
882: 
883:                 layoutThisToSelf();
884:             }
885: 
886:         }
887: 
888:         return true;
889:     }
