801:         while (it.hasNext()) {
802:             Fig fig = (Fig) it.next();
803:             fig.delete();
804:         }
805: 
806:         // GEF does not take into account the multiple diagrams we have
807:         // therefore we loop through our diagrams and delete each and every 
808:         // occurence on our own
809:         it =
810: 	    ProjectManager.getManager().getCurrentProject()
811: 	        .getDiagrams().iterator();
812:         while (it.hasNext()) {
813:             ArgoDiagram diagram = (ArgoDiagram) it.next();
814:             diagram.damage();
815:         }
816:         super.delete();
817:     }
