282:     /**
283:      * @see org.tigris.gef.ui.PopupGenerator#getPopUpActions(java.awt.event.MouseEvent)
284:      */
285:     public Vector getPopUpActions(MouseEvent me) {
286:         Vector popUpActions = super.getPopUpActions(me);
287: 
288:         // popupAddOffset should be equal to the number of items added here:
289:         popUpActions.addElement(new JSeparator());
290:         popupAddOffset = 1;
291:         if (removeFromDiagram) {
292:             popUpActions.addElement(
293:                     ProjectBrowser.getInstance().getRemoveFromDiagramAction());
294:             popupAddOffset++;
295:         }
296:         popUpActions.addElement(new ActionDeleteModelElements());
297:         popupAddOffset++;
298: 
299:         /* Check if multiple items are selected: */
300:         boolean ms = TargetManager.getInstance().getTargets().size() > 1;
301:         if (!ms) {
302:             ToDoList list = Designer.theDesigner().getToDoList();
303:             Vector items = 
304:                 (Vector) list.elementsForOffender(getOwner()).clone();
305:             if (items != null && items.size() > 0) {
306:                 ArgoJMenu critiques = new ArgoJMenu("menu.popup.critiques");
307:                 ToDoItem itemUnderMouse = hitClarifier(me.getX(), me.getY());
308:                 if (itemUnderMouse != null) {
309:                     critiques.add(new ActionGoToCritique(itemUnderMouse));
310:                     critiques.addSeparator();
311:                 }
312:                 int size = items.size();
313:                 for (int i = 0; i < size; i++) {
314:                     ToDoItem item = (ToDoItem) items.elementAt(i);
315:                     if (item == itemUnderMouse)
316:                         continue;
317:                     critiques.add(new ActionGoToCritique(item));
318:                 }
319:                 popUpActions.insertElementAt(new JSeparator(), 0);
320:                 popUpActions.insertElementAt(critiques, 0);
321:             }
322:         }
323:         // Add stereotypes submenu
324:         Action[] stereoActions =
325:             StereotypeUtility.getApplyStereotypeActions(getOwner());
326:         if (stereoActions != null) {
327:             popUpActions.insertElementAt(new JSeparator(), 0);
328:             ArgoJMenu stereotypes = new ArgoJMenu("menu.popup.apply-stereotypes");
329:             for (int i = 0; i < stereoActions.length; ++i) {
330:                 stereotypes.addCheckItem(stereoActions[i]);
331:             }
332:             popUpActions.insertElementAt(stereotypes, 0);
333:         }
334:         return popUpActions;
335:     }
