352:     /**
353:      * @param g the <code>Graphics</code> object
354:      */
355:     public void paintClarifiers(Graphics g) {
356:         int iconPos = 25, gap = 1, xOff = -4, yOff = -4;
357:         Point p = new Point();
358:         ToDoList list = Designer.theDesigner().getToDoList();
359:         Vector items = list.elementsForOffender(getOwner());
360:         int size = items.size();
361:         for (int i = 0; i < size; i++) {
362:             ToDoItem item = (ToDoItem) items.elementAt(i);
363:             Icon icon = item.getClarifier();
364:             if (icon instanceof Clarifier) {
365:                 ((Clarifier) icon).setFig(this);
366:                 ((Clarifier) icon).setToDoItem(item);
367:             }
368:             if (icon != null) {
369:                 stuffPointAlongPerimeter(iconPos, p);
370:                 icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
371:                 iconPos += icon.getIconWidth() + gap;
372:             }
373:         }
374:         items = list.elementsForOffender(this);
375:         size = items.size();
376:         for (int i = 0; i < size; i++) {
377:             ToDoItem item = (ToDoItem) items.elementAt(i);
378:             Icon icon = item.getClarifier();
379:             if (icon instanceof Clarifier) {
380:                 ((Clarifier) icon).setFig(this);
381:                 ((Clarifier) icon).setToDoItem(item);
382:             }
383:             if (icon != null) {
384:                 stuffPointAlongPerimeter(iconPos, p);
385:                 icon.paintIcon(null, g, p.x + xOff, p.y + yOff);
386:                 iconPos += icon.getIconWidth() + gap;
387:             }
388:         }
389:     }
