391:     /**
392:      * The user clicked on the clarifier.
393:      *
394:      * @param x the x of the point clicked
395:      * @param y the y of the point clicked
396:      * @return the todo item clicked
397:      */
398:     public ToDoItem hitClarifier(int x, int y) {
399:         int iconPos = 25, xOff = -4, yOff = -4;
400:         Point p = new Point();
401:         ToDoList list = Designer.theDesigner().getToDoList();
402:         Vector items = list.elementsForOffender(getOwner());
403:         int size = items.size();
404:         for (int i = 0; i < size; i++) {
405:             ToDoItem item = (ToDoItem) items.elementAt(i);
406:             Icon icon = item.getClarifier();
407:             stuffPointAlongPerimeter(iconPos, p);
408:             int width = icon.getIconWidth();
409:             int height = icon.getIconHeight();
410:             if (y >= p.y + yOff
411:                 && y <= p.y + height + yOff
412:                 && x >= p.x + xOff
413:                 && x <= p.x + width + xOff)
414:                 return item;
415:             iconPos += width;
416:         }
417:         for (int i = 0; i < size; i++) {
418:             ToDoItem item = (ToDoItem) items.elementAt(i);
419:             Icon icon = item.getClarifier();
420:             if (icon instanceof Clarifier) {
421:                 ((Clarifier) icon).setFig(this);
422:                 ((Clarifier) icon).setToDoItem(item);
423:                 if (((Clarifier) icon).hit(x, y))
424:                     return item;
425:             }
426:         }
427:         items = list.elementsForOffender(this);
428:         size = items.size();
429:         for (int i = 0; i < size; i++) {
430:             ToDoItem item = (ToDoItem) items.elementAt(i);
431:             Icon icon = item.getClarifier();
432:             stuffPointAlongPerimeter(iconPos, p);
433:             int width = icon.getIconWidth();
434:             int height = icon.getIconHeight();
435:             if (y >= p.y + yOff
436:                 && y <= p.y + height + yOff
437:                 && x >= p.x + xOff
438:                 && x <= p.x + width + xOff)
439:                 return item;
440:             iconPos += width;
441:         }
442:         for (int i = 0; i < size; i++) {
443:             ToDoItem item = (ToDoItem) items.elementAt(i);
444:             Icon icon = item.getClarifier();
445:             if (icon instanceof Clarifier) {
446:                 ((Clarifier) icon).setFig(this);
447:                 ((Clarifier) icon).setToDoItem(item);
448:                 if (((Clarifier) icon).hit(x, y))
449:                     return item;
450:             }
451:         }
452:         return null;
453:     }
