672:     protected void modelChanged(PropertyChangeEvent e) {
673:         if (getOwner()!=null&&Model.getUmlFactory().isRemoved(getOwner()))
674:             return;
675:         if (e == null
676:             || (e.getSource() == getOwner()
677:                     && "name".equals(e.getPropertyName()))) {
678:             updateNameText();
