684:                 new CmdSetPreferredSize(CmdSetPreferredSize.MINIMUM_SIZE);
685:             cmdSPS.setFigToResize(this);
686:             cmdSPS.doIt();
687:         }
688:         if (!updateClassifiers())
689:             return;
690:     }
