706:     /**
707:      * generate the notation for the stereotype and stuff it into the text Fig
708:      */
709:     protected void updateStereotypeText() {
710:         if (SingleStereotypeEnabler.isEnabled()) {
711:             updateStereotypeTextSingleStereotype();
712:             return;
713:         }
714:         if ((getOwner() == null) || (getOwner() instanceof CommentEdge)) {
715:             return;
716:         }
717:         Object modelElement = getOwner();
718:         stereotypeFig.setOwner(modelElement);
719:         ((FigStereotypesCompartment)stereotypeFig).populate();
