722:     protected void updateStereotypeTextSingleStereotype() {
723:         if ((getOwner() == null) || (getOwner() instanceof CommentEdge)) {
724:             return;
725:         }
726:         Object stereotype = CollectionUtil.getFirstItemOrNull(
727:                 Model.getFacade().getStereotypes(getOwner()));
728:         if (stereotype == null) {
729:             ((FigText)stereotypeFig).setText("");
730:             return;
731:         }
732:         String stereoStr = Model.getFacade().getName(stereotype);
733:         if (stereoStr == null || stereoStr.length() == 0)
734:             ((FigText)stereotypeFig).setText("");
735:         else {
736:             ((FigText)stereotypeFig).setText(Notation.generateStereotype(this, stereotype));
737:         }
