923:     /**
924:      * <p>Updates the classifiers the edge is attached to.  <p>Calls a
925:      * helper method (layoutThisToSelf) to avoid this edge
926:      * disappearing if the new source and dest are the same node.
927:      *
928:      * @return boolean whether or not the update was sucessful
929:      */
930:     protected boolean updateClassifiers() {
931:         Object owner = getOwner();
932:         if (owner == null || getLayer() == null)
933:             return false;
934: 
935:         Object newSource = getSource();
936:         Object newDest = getDestination();
937: 
938:         Fig currentSourceFig = getSourceFigNode();
939:         Fig currentDestFig = getDestFigNode();
940:         Object currentSource = null;
941:         Object currentDestination = null;
942:         if (currentSourceFig != null && currentDestFig != null) {
943:             currentSource = currentSourceFig.getOwner();
944:             currentDestination = currentDestFig.getOwner();
945:         }
946:         if (newSource != currentSource || newDest != currentDestination) {
947:             Fig newSourceFig = null;
948:             if (newSource != null)
949:                 newSourceFig = getLayer().presentationFor(newSource);
950:             Fig newDestFig = null;
951:             if (newDest != null)
952:                 newDestFig = getLayer().presentationFor(newDest);
953:             if (newSourceFig == null || newDestFig == null) {
954:                 removeFromDiagram();
955:                 return false;
956:             }
957:             if (newSourceFig != null && newSourceFig != currentSourceFig) {
958:                 setSourceFigNode((FigNode) newSourceFig);
959:                 setSourcePortFig(newSourceFig);
960: 
961:             }
962:             if (newDestFig != null && newDestFig != currentDestFig) {
963:                 setDestFigNode((FigNode) newDestFig);
964:                 setDestPortFig(newDestFig);
965:             }
966:             if (newDestFig != null && newSourceFig != null) {
967:                 ((FigNode) newSourceFig).updateEdges();
968:             }
969:             if (newSourceFig != null && newDestFig != null) {
970:                 ((FigNode) newDestFig).updateEdges();
971:             }
972:             calcBounds();
973: 
974:             // adapted from SelectionWButtons from line 280
975:             // calls a helper method to avoid this edge disappearing
976:             // if the new source and dest are the same node.
977:             if (newSourceFig == newDestFig) {
978: 
979:                 layoutThisToSelf();
980:             }
981: 
982:         }
983: 
984:         return true;
985:     }
986: 
987:     /**
988:      * helper method for updateClassifiers() in order to automatically
989:      * layout an edge that is now from and to the same node type.
990:      * <p>adapted from SelectionWButtons from line 280
991:      */
992:     private void layoutThisToSelf() {
993: 
994:         FigPoly edgeShape = new FigPoly();
995:         //newFC = _content;
996:         Point fcCenter =
997:             new Point(getSourceFigNode().getX() / 2,
998:                     getSourceFigNode().getY() / 2);
999:         Point centerRight =
1000:             new Point(
1001: 		      (int) (fcCenter.x
1002: 			     + getSourceFigNode().getSize().getWidth() / 2),
1003: 		      fcCenter.y);
1004: 
1005:         int yoffset = (int) ((getSourceFigNode().getSize().getHeight() / 2));
1006:         edgeShape.addPoint(fcCenter.x, fcCenter.y);
1007:         edgeShape.addPoint(centerRight.x, centerRight.y);
1008:         edgeShape.addPoint(centerRight.x + 30, centerRight.y);
1009:         edgeShape.addPoint(centerRight.x + 30, centerRight.y + yoffset);
1010:         edgeShape.addPoint(centerRight.x, centerRight.y + yoffset);
1011: 
1012:         // place the edge on the layer and update the diagram
1013:         this.setBetweenNearestPoints(true);
1014:         edgeShape.setLineColor(Color.black);
1015:         edgeShape.setFilled(false);
1016:         edgeShape.setComplete(true);
1017:         this.setFig(edgeShape);
1018:     }
