337:     /**
338:      * distance formula: (x-h)^2 + (y-k)^2 = distance^2
339:      *
340:      * @param p1 point
341:      * @param p2 point
342:      * @return the square of the distance
343:      */
344:     public int getSquaredDistance(Point p1, Point p2) {
345:         int xSquared = p2.x - p1.x;
346:         xSquared *= xSquared;
347:         int ySquared = p2.y - p1.y;
348:         ySquared *= ySquared;
349:         return xSquared + ySquared;
350:     }
