65:     /**
66:      * @see java.awt.event.MouseListener#mousePressed(java.awt.event.MouseEvent)
67:      */
68:     public void mousePressed(MouseEvent me) {
69:         int x = me.getX(), y = me.getY();
70:         Fig underMouse = editor.hit(x, y);
71:         if (underMouse == null) {
72:             underMouse = editor.hit(x - 16, y - 16, 32, 32);
73:         }
74:         
75:         if (underMouse == null && _npoints == 0) {
76:             done();
77:             me.consume();
78:             return;
79:         }
80: 
81:         if (_npoints > 0) {
82:             me.consume();
83:             return;
84:         }
85:         
86:         Object modelElement = underMouse.getOwner();
87:         
88:         if (underMouse instanceof FigEdgeModelElement) {
89:             // If we're drawing from an edge
90:             
91:             sourceEdge = (FigEdgeModelElement) underMouse;
92:             sourceModelElement = sourceEdge.getOwner();
93:             
94:             FigCommentPort tee = new FigCommentPort();
95:             tee.setOwner(sourceModelElement);
96:             sourceEdge.addTeeFig(tee);
97:             
98:             underMouse = tee;
99:             setSourceFigNode(tee);
100:             setStartPort(sourceModelElement);
101:             setStartPortFig(tee);
102:         } else if (underMouse instanceof FigNodeModelElement) {
103:             if (getSourceFigNode() == null) {
104:                 setSourceFigNode((FigNode) underMouse);
105:                 setStartPort(getSourceFigNode().deepHitPort(x, y));
106:             }
107:             if (getStartPort() == null) {
108:                 done();
109:                 me.consume();
110:                 return;
111:             }
112:             setStartPortFig(
113:                     getSourceFigNode().getPortFig(getStartPort()));
114:         } else {
115:             done();
116:             me.consume();
117:             return;
118:         }
119: 
120:         createFig(me);
121:         me.consume();
122:     }
