124:     /**
125:      * @see org.tigris.gef.base.ModeCreatePolyEdge#mouseReleased(java.awt.event.MouseEvent)
126:      */
127:     public void mouseReleased(MouseEvent me) {
128:         if (me.isConsumed()) {
129:             return;
130:         }
131:         if (getSourceFigNode() == null) {
132:             done();
133:             me.consume();
134:             return;
135:         }
136:         int x = me.getX(), y = me.getY();
137:         Fig destFig = editor.hit(x, y);
138:         if (destFig == null) {
139:             destFig = editor.hit(x - 16, y - 16, 32, 32);
140:         }
141:         GraphModel graphModel = editor.getGraphModel();
142:         if (!(graphModel instanceof MutableGraphModel)) {
143:             destFig = null;
144:         }
145:         
146:         
147:         MutableGraphModel mutableGraphModel = (MutableGraphModel) graphModel;
148:         // TODO: potential class cast exception
149:         if (destFig instanceof FigAssociation && 
150:                 !(destFig instanceof FigAssociationClass)) {
151:             Object association = destFig.getOwner();
152:             boolean isValid =
153:                 Model.getUmlFactory().isConnectionValid(
154:                     Model.getMetaTypes().getAssociationEnd(),
155:                     getStartPort(),
156:                     association);
157:             if (isValid) {
158:                 GraphModel gm = editor.getGraphModel();
159:                 GraphNodeRenderer renderer = editor.getGraphNodeRenderer();
160:                 Layer lay = editor.getLayerManager().getActiveLayer();
161:                 mutableGraphModel.removeEdge(association);
162:                 destFig.setOwner(null);
163:                 destFig.removeFromDiagram();
164:                 mutableGraphModel.addNode(association);
165:                 FigNode figNode = (FigNode) lay.presentationFor(association);
166:                 figNode.setLocation(
167:                         x - figNode.getWidth() / 2,
168:                         y - figNode.getHeight() / 2);
169:                 editor.add(figNode);
170:                 associationEnds = 
171:                     Model.getFacade().getConnections(association);
172:                 Iterator it = associationEnds.iterator();
173:                 mutableGraphModel.addEdge(it.next());
174:                 mutableGraphModel.addEdge(it.next());
175:                 destFig = figNode;
176:             }
177:         }
178: 
179:         if (destFig instanceof FigNode &&
180:                 !(destFig instanceof FigClassAssociationClass) &&
181:                 !Model.getFacade().isANaryAssociation(destFig.getOwner())) {
182:             FigNode destFigNode = (FigNode) destFig;
183:             // If its a FigNode, then check within the
184:             // FigNode to see if a port exists
185:             Object foundPort = destFigNode.deepHitPort(x, y);
186: 
187:             if (foundPort == getStartPort() && _npoints < 4) {
188:                 // user made a false start
189:                 done();
190:                 me.consume();
191:                 return;
192:             }
193:             if (foundPort != null) {
194:                 Fig destPortFig = destFigNode.getPortFig(foundPort);
195:                 FigPoly p = (FigPoly) _newItem;
196:                 if (foundPort == getStartPort() && _npoints >= 4) {
197:                     p.setSelfLoop(true);
198:                 }
199:                 editor.damageAll();
200:                 p.setComplete(true);
201: 
202:                 Object edgeType = getArg("edgeClass");
203:                 setNewEdge(mutableGraphModel.connect(
204:                        getStartPort(), foundPort, (Class) edgeType));
205: 
206:                 // Calling connect() will add the edge to the GraphModel and
207:                 // any LayerPersectives on that GraphModel will get a
208:                 // edgeAdded event and will add an appropriate FigEdge
209:                 // (determined by the GraphEdgeRenderer).
210: 
211:                 if (getNewEdge() != null) {
212:                     getSourceFigNode().damage();
213:                     destFigNode.damage();
214:                     Layer lay = editor.getLayerManager().getActiveLayer();
215:                     FigEdge fe = (FigEdge) lay.presentationFor(getNewEdge());
216:                     _newItem.setLineColor(Color.black);
217:                     fe.setFig(_newItem);
218:                     fe.setSourcePortFig(getStartPortFig());
219:                     fe.setSourceFigNode(getSourceFigNode());
220:                     fe.setDestPortFig(destPortFig);
221:                     fe.setDestFigNode(destFigNode);
222: 
223:                     if (fe != null) {
224:                         editor.getSelectionManager().select(fe);
225:                     }
226:                     editor.damageAll();
227: 
228:                     // if the new edge implements the MouseListener
229:                     // interface it has to receive the mouseReleased() event
230:                     if (fe instanceof MouseListener) {
231:                         ((MouseListener) fe).mouseReleased(me);
232:                     }
233: 
234:                     // set the new edge in place
235:                     if (getSourceFigNode() != null) {
236:                         getSourceFigNode().updateEdges();
237:                     }
238:                     if (destFigNode != null) {
239:                         destFigNode.updateEdges();
240:                     }
241:                     endAttached();
242:                 }
243:                 done();
244:                 me.consume();
245:                 return;
246:             }
247:         }
248:         if (!nearLast(x, y)) {
249:             editor.damageAll();
250:             Point snapPt = new Point(x, y);
251:             editor.snap(snapPt);
252:             ((FigPoly) _newItem).addPoint(snapPt.x, snapPt.y);
253:             _npoints++;
254:             editor.damageAll();
255:         }
256:         _lastX = x;
257:         _lastY = y;
258:         me.consume();
259: 
260:         /* If a FigNodeAssociation has been created and placed but
261:          * the connection fails, it must be undone.
262:          */
263:         if (getNewEdge() == null
264:                 && newFigNodeAssociation != null
265:                 && newFigNodeAssociation instanceof FigNodeAssociation) {
266:             Editor editor = Globals.curEditor();
267:             editor.remove(newFigNodeAssociation);
268:             newFigNodeAssociation.removeFromDiagram();
269:             sourceEdge.setOwner(sourceModelElement);
270:         }
271:     }
272: 
273:     /**
274:      * This will be called when the edge is successfully connected.
275:      * What we do in this class is to determine if we are creating
276:      * an n-ary association. If so then FigNode representing the n-ary
277:      * association is made visible. The FigEdge representing the old
278:      * binary association is removed and replaced with edges representing
279:      * the 2 association ends of that original fig.
280:      */
281:     protected void endAttached() {
282:         if (newFigNodeAssociation != null) {
283:             newFigNodeAssociation.setVisible(true);
284: 
285:             Editor editor = Globals.curEditor();
286: 
287:             GraphModel gm = editor.getGraphModel();
288:             if (gm instanceof MutableGraphModel) {
289:                 MutableGraphModel mutableGraphModel = (MutableGraphModel) gm;
290:                 Iterator it = associationEnds.iterator();
291:                 mutableGraphModel.addEdge(it.next());
292:                 mutableGraphModel.addEdge(it.next());
293:                 editor.getSelectionManager().deselectAll();
294:                 mutableGraphModel.addNode(sourceModelElement);
295:             }
296:         }
297:         super.endAttached();
298:     }
299: 
300:     private FigNode placeTempNode(MouseEvent me) {
301:         Editor editor = Globals.curEditor();
302:         FigNode figNode = null;
303:         GraphModel gm = editor.getGraphModel();
304: 
305:         GraphNodeRenderer renderer = editor.getGraphNodeRenderer();
306:         Layer lay = editor.getLayerManager().getActiveLayer();
307:         figNode = renderer.getFigNodeFor(gm, lay, sourceModelElement, null);
308:         figNode.setLocation(
309:                 me.getX() - figNode.getWidth() / 2,
310:                 me.getY() - figNode.getHeight() / 2);
311:         figNode.setVisible(false);
312:         editor.add(figNode);
313:         editor.getSelectionManager().deselectAll();
314: 
315:         return figNode;
316:     }
