423: 
424:         String packagePath = generateRelativePackage(cls, null, ".");
425:         packagePath = packagePath.substring(1);
426:         String filename = name + getFileExtension();
427: 
428:         int lastIndex = -1;
429:         do {
430:             File f = new File (path);
431:             if (!f.isDirectory()) {
432:                 if (!f.mkdir()) {
433:                     LOG.error(" could not make directory " + path);
434:                     return null;
435:                 }
436:             }
437: 
438:             if (lastIndex == packagePath.length()) {
439:                 break;
440:             }
441: 
442:             int index = packagePath.indexOf (".", lastIndex + 1);
443:             if (index == -1) {
444:                 index = packagePath.length();
445:             }
446: 
447:             path += packagePath.substring(lastIndex + 1, index)
