677:     /**
678:      * Adds dep to the set of dependencies of currClass. If predecl
679:      * then only a predeclaration is generated, else an #include.
680:      * @param dep The classifier whose currClass depends on.
681:      * @param predecl If true then only a predeclaration is needed
682:      */
683:     private void addDependency(Object dep, boolean predecl) {
684:         if (generatorPass == NONE_PASS) {
685:             return; // skip dependencies if generating notation
686:         }
687:         if (!(Model.getFacade().isAClass(dep))
688:             && !(Model.getFacade().isAInterface(dep))) {
689:             // Do nothing for things such as datatypes, etc.
690:             // TODO: check for namespace when using directives are implemented
691:             return;
692:         }
693:         if (predecl && !includeCls.contains(dep)) {
694:             if (generatorPass == HEADER_PASS) {
695:                 predeclCls.add(dep);
696:             }
697:         } else {
698:             if (predeclCls.contains(dep)) {
699:                 predeclCls.remove(dep);
700:             }
701:             if (includeCls.add(dep)) {
702:                 // dep was not already in includeCls
703:                 Object ns = Model.getFacade().getNamespace(currentClassifier);
704:                 String name = Model.getFacade().getName(dep);
705:                 // use '/', not FILE_SEPARATOR (this is intentional)
706:                 String path =
707:                     generateRelativePackage(dep, ns, "/");
708:                 Set inc = localInc;
709:                 if (path.startsWith("/")) { // external include
710:                     path = path.substring(1); // remove leading /
711:                     inc = extInc;
712:                 }
713:                 if (path.length() > 0) {
714:                     inc.add(path + "/" + name + ".h");
715:                 } else {
716:                     inc.add(name + ".h");
717:                 }
718:             }
719:         }
720:     }
