738:     private String generateHeaderPackageEndSingle(Object pkg) {
739:         StringBuffer sb = new StringBuffer(30);
740:         String packageName = Model.getFacade().getName(pkg);
741:         StringTokenizer st = new StringTokenizer(packageName, ".");
742:         String token = "";
743:         while (st.hasMoreTokens()) {
744:             token = st.nextToken();
745:             StringBuffer tempBuf = new StringBuffer(20);
746:             String absoluteName = generatePackageAbsoluteName(pkg);
747:             if (absoluteName.indexOf(token) != -1) {
748:                 absoluteName =
749:                     absoluteName.substring(0,
750:                                (absoluteName.indexOf(token)
751:                                 + token.length()));
752:             }
753: 
754:             // create line: namespace FOO {"
755:             tempBuf.append("} /* End of namespace ").append(absoluteName);
756:             tempBuf.append(" */").append(LINE_SEPARATOR);
757:             sb.insert(0, tempBuf.toString());
758:         }
759:         return sb.toString();
