771:     /** Generate the name of item with package prefix relative to localPkg.
772:      * localPkg may be null, meaning the global namespace.
773:      */
774:     private String generateNameWithPkgSelection(Object item, Object localPkg) {
775:         if (item == null) {
776:             return "void ";
777:         }
778:         Object pkg = null;
779:         if (Model.getFacade().isADataType(item)) {
780:             return generateName(Model.getFacade().getName(item));
781:         } else if (Model.getFacade().isAParameter(item)
782:                    || Model.getFacade().isAAttribute(item)
783:                    || Model.getFacade().isAAssociationEnd(item)
784:                    || Model.getFacade().isAClassifier(item)) {
785:             pkg = getNamespaceWithoutModel(item);
786:         }
787: 
788:         if (pkg == null) {
789:             return generateName(Model.getFacade().getName(item));
790:         }
791:         String packPrefix = generateRelativePackage(item, localPkg, "::");
792:         if (packPrefix.length() > 0) {
793:             packPrefix += "::";
794:         }
795:         return packPrefix + generateName(Model.getFacade().getName(item));
