812:     /** Generate the code to go from the current namespace to cls's one
813:      */
814:     private String generateHeaderPackageStart(Object cls) {
815:         StringBuffer sb = new StringBuffer(80);
816: 
817:         if (actualNamespace != null) {
818:             Object lastSearch = actualNamespace;
819:             // iterate while fromSearch != null, but iterate one time
820:             // when it is null too, because it's the global namespace
821:             for (Object fromSearch = actualNamespace;
822:                     fromSearch != null;
823:                     lastSearch = getNamespaceWithoutModel(fromSearch)) {
824:                 fromSearch = lastSearch;
825:                 StringBuffer contPath = new StringBuffer(80);
826:                 Object toSearch = getNamespaceWithoutModel(cls);
827:                 for (; (toSearch != null) && (toSearch != fromSearch);
828:                         toSearch = getNamespaceWithoutModel(toSearch)) {
829:                     contPath.insert(0,
830:                             generateHeaderPackageStartSingle(toSearch));
831:                 }
832:                 if (toSearch == fromSearch) {
833:                     sb.append(contPath.toString());
834:                     break;
835:                 }
836:                 // close one namespace
837:                 sb.append(generateHeaderPackageEndSingle(fromSearch));
838:             }
839:         }
840:         else { // initial start
841:             for (Object toSearch = getNamespaceWithoutModel(cls);
842:                     toSearch != null;
843:                     toSearch = getNamespaceWithoutModel(toSearch)) {
844:                 sb.insert(0, generateHeaderPackageStartSingle(toSearch));
845:             }
846:         }
847:         actualNamespace = getNamespaceWithoutModel(cls);
848:         return sb.toString();
849:     }
