958:     /** 2002-11-28 Achim Spangler
959:      * seperate generation of Operation Prefix from generateOperation
960:      * so that generateOperation is language independent
961:      */
962:     private String generateOperationPrefix(Object op) {
963:         StringBuffer sb = new StringBuffer(80);
964:         // c++ doesn't have any builtin construct for concurrency
965:         //sb.append(generateConcurrency(op));
966:         if (generatorPass != SOURCE_PASS) {
967:             // make all operations to virtual - as long as they are not "leaf"
968:             Object scope = Model.getFacade().getOwnerScope(op);
969:             if (Model.getFacade().isLeaf(op)
970:                     && !Model.getFacade().isRoot(op)) {
971:                 // there's no way to make a leaf method that it's not root in
972:                 // c++, so warn the user and ignore the 'root' attribute
973:                 // (or it may be better to ignore the 'leaf' attribute?)
974:                 LOG.warn(op + " is leaf but not root: "
975:                          + "C++ can't handle this properly");
976:                 LOG.warn("    Ignoring the 'root' attribute");
977:             }
978:             // generate a function as virtual, if it can be overriden
979:             // or override another function AND if this function is
980:             // not marked as static, which disallows "virtual"
981:             // alternatively every abstract function is defined as
982:             // virtual
983:             if ((!Model.getFacade().isLeaf(op)
984:                     && !Model.getFacade().isConstructor(op)
985:                     && (!(Model.getScopeKind().getClassifier().equals(scope))))
986:                     || (Model.getFacade().isAbstract(op))) {
987:                 sb.append("virtual ");
988:             }
989:             sb.append(generateOwnerScope(op));
990:         }
991:         return sb.toString();
992:     }
