1005:     /** 2002-11-28 Achim Spangler
1006:      * seperate generation of Operation Name from generateOperation
1007:      * so that generateOperation is language independent
1008:      * -> for C++: if we create .cpp we must prepend Owner name
1009:      *
1010:      * @param sb Where to put the result.
1011:      */
1012:     private boolean generateOperationNameAndTestForConstructor(Object op,
1013:             StringBuffer sb) {
1014:         if (generatorPass == SOURCE_PASS) {
1015:             Object cls = Model.getFacade().getOwner(op);
1016:             String prefix = new String();
1017:             while (!Model.getFacade().isAPackage(cls)) {
1018:                 prefix = Model.getFacade().getName(cls) + "::" + prefix;
1019:                 cls = Model.getFacade().getNamespace(cls);
1020:             }
1021:             sb.append(prefix);
1022:         }
1023:         boolean constructor = false;
1024:         String name;
1025:         if (Model.getFacade().isConstructor(op)) {
1026:             // constructor
1027:             name = Model.getFacade().getName(Model.getFacade().getOwner(op));
1028:             constructor = true;
1029:         } else {
1030:             name = Model.getFacade().getName(op);
1031:         }
1032:         sb.append(generateName(name));
1033:         return constructor;
1034:     }
