1036:     /**
1037:      * @see org.argouml.application.api.NotationProvider2#generateOperation(
1038:      *      java.lang.Object, boolean)
1039:      *
1040:      * 2002-11-28 Achim Spangler
1041:      * modified version from Jaap Branderhorst
1042:      * -> generateOperation is language independent and seperates
1043:      *    different tasks
1044:      */
1045:     public String generateOperation(Object op, boolean documented) {
1046:         // generate nothing for abstract functions, if we generate the
1047:         // source .cpp file at the moment
1048:         if ((generatorPass == SOURCE_PASS) 
1049:                 && (Model.getFacade().isAbstract(op))) {
1050:             return "";
1051:         }
1052:         StringBuffer sb = new StringBuffer(80);
1053:         StringBuffer nameBuffer = new StringBuffer(20);
1054:         String operationIndent = (generatorPass == HEADER_PASS) ? indent : "";
1055:         boolean constructor =
1056:             generateOperationNameAndTestForConstructor(op, nameBuffer);
1057: 
1058:         // if generating a file always document
1059:         if (documented || generatorPass != NONE_PASS) {
1060:             // generate DocComment from tagged values
1061:             String tv = generateTaggedValues (op, DOC_COMMENT_TAGS);
1062:             if (tv != null && tv.length() > 0) {
1063:                 sb.append (LINE_SEPARATOR).append(operationIndent).append (tv);
1064:             }
1065:         }
1066: 
1067:         sb.append(operationIndent)
1068:             .append(generateOperationPrefix(op));
1069: 
1070:         // pick out return type
1071:         Object rp = Model.getCoreHelper().getReturnParameter(op);
1072:         if (!constructor) {
1073:             if (rp != null) {
1074:                 Object returnType = Model.getFacade().getType(rp);
1075:                 if (returnType == null) {
1076:                     sb.append("void ");
1077:                 }
1078:                 else if (returnType != null) {
1079:                     sb.append(generateNameWithPkgSelection(returnType))
1080:                         .append(' ');
1081:                     /* fixing 2862 - apply modifiers, 
1082:                      * i.e. pointer or reference TV */
1083:                     sb.append(generateAttributeParameterModifier(rp));
1084:                 }
1085:                 boolean predecl = !checkIncludeNeeded4Element(rp);
1086:                 addDependency(returnType, predecl);
1087:             }
1088:         }
1089: 
1090:         // name and params
1091:         Vector params = new Vector(Model.getFacade().getParameters(op));
1092:         params.remove(rp); // If there are several return parameters, just
1093:                            // the one found above will be removed.
1094: 
1095:         sb.append(nameBuffer.toString()).append('(');
1096: 
1097:         if (params != null) {
1098:             boolean first = true;
1099: 
1100:             for (int i = 0; i < params.size(); i++) {
1101:                 Object p = params.elementAt (i);
1102: 
1103:                 if (!first) sb.append(", ");
1104: 
1105:                 sb.append(generateParameter(p));
1106:                 first = false;
1107:             }
1108:         }
1109: 
1110:         String suffix = generateOperationSuffix(op);
1111:         if (suffix.equals(""))
1112:             sb.append(")");
1113:         else
1114:             sb.append(") ").append(suffix);
1115: 
1116:         return sb.toString();
1117:     }
