1119:     /** 2002-12-06 Achim Spangler
1120:      * check if a parameter is tagged as pointer or reference (not
1121:      * part of UML - as far as author knows - but important for C++
1122:      * developers)
1123:      * @param elem element to check
1124:      * @return one of NORMAL_MOD, REFERENCE_MOD, POINTER_MOD, or -1 if
1125:      *         no specific tag is found
1126:      */
1127:     private int getAttributeModifierType(Object elem) {
1128:         // first check whether the parameter shall be a pointer of reference
1129:         Iterator iter = Model.getFacade().getTaggedValues(elem);
1130:         while (iter.hasNext()) {
1131:             Object tv = iter.next();
1132:             String tag = Model.getFacade().getTagOfTag(tv);
1133:             String val = Model.getFacade().getValueOfTag(tv);
1134:             if (tag.indexOf("ref") != -1 || tag.equals("&")) {
1135:                 return val.equals("false") ? NORMAL_MOD
1136:                                            : REFERENCE_MOD;
1137:             } else if (tag.indexOf("pointer") != -1 || tag.equals("*")) {
1138:                 return val.equals("false") ? NORMAL_MOD
1139:                                            : POINTER_MOD;
1140:             }
1141:         }
1142:         return -1; /* no tag found */
1143:     }
