1146:     private String generateAttributeParameterModifier(Object attr,
1147:                                                       String def) {
1148:         int modType = getAttributeModifierType(attr);
1149: 
1150:         // if attr has an abstract type it must be pointer or reference
1151:         if (modType == NORMAL_MOD || modType == -1) {
1152:             // this is used for association classes to; skip them
1153:             if (!Model.getFacade().isAAssociationClass(attr)) {
1154:                 Object type = Model.getFacade().getType(attr);
1155:                 if (type == null) {
1156:                     // model corrupt (this really happened -- aslo)
1157:                     LOG.error(attr + " has no type!");
1158:                     return "";
1159:                 }
1160:                 if (Model.getFacade().isAbstract(type)
1161:                     || Model.getFacade().isAInterface(type)) {
1162:                     if (modType == NORMAL_MOD) {
1163:                         // user explicitly requested no modifier
1164:                         LOG.warn("Requested no reference or pointer "
1165:                                 + "modifier, but");
1166:                         LOG.warn("\t" + type + " cannot be instantiated, "
1167:                                 + "using reference");
1168:                     }
1169:                     modType = REFERENCE_MOD;
1170:                 }
1171:             }
1172:         }
1173: 
1174:         if (modType == NORMAL_MOD) {
1175:             return "";
1176:         } else if (modType == REFERENCE_MOD) {
1177:             return "&";
1178:         } else if (modType == POINTER_MOD) {
1179:             return "*";
1180:         } else if (def.length() == 0) {
1181:             if (Model.getFacade().isAParameter(attr)
1182:                     && (Model.getDirectionKind().getOutParameter().equals(
1183:                         Model.getFacade().getKind(attr))
1184:                     || Model.getDirectionKind().getInOutParameter().equals(
1185:                         Model.getFacade().getKind(attr)))) {
1186:                 // out or inout parameters are defaulted to reference if
1187:                 // not specified else
1188:                 return "&";
1189:             }
1190:         }
1191:         return def;
1192:     }
