1437:     /* Indent each line of the given string by n indent spaces.
1438:      */
1439:     private String indentString(String s, int n) {
1440:         String ind = new String();
1441:         for (; n > 0; n--)
1442:             ind += indent;
1443:         // This works only with jdk 1.5: return s.replace("\n", "\n" + ind);
1444:         StringBuffer result = new StringBuffer();
1445:         for (int i = s.indexOf('\n'); i != -1; i = s.indexOf('\n')) {
1446:             result.append(ind).append(s.substring(0, i + 1));
1447:             s = s.substring(i + 1);
1448:         }
1449:         if (s.length() > 0) {
1450:             result.append(ind).append(s);
1451:         }
1452:         return result.toString();
1453:     }
