1776:     private void generateClassifierBodyTaggedAccess4Attributes(
1777:             Object cls,
1778:             StringBuffer funcPrivate,
1779:             StringBuffer funcProtected,
1780:             StringBuffer funcPublic) {
1781:         Collection strs = Model.getFacade().getAttributes(cls);
1782:         if (strs.isEmpty() || (generatorPass != HEADER_PASS)) {
1783:             return;
1784:         }
1785:         String accessTag = null;
