1787:         Iterator strEnum = strs.iterator();
1788:         while (strEnum.hasNext()) {
1789:             Object attr = strEnum.next();
1790:             accessTag = Model.getFacade().getTaggedValueValue(attr, "set");
1791:             if (accessTag != null && accessTag.length() > 0) {
1792:                 if (accessTag.indexOf("public") != -1) {
1793:                     generateSingleAttributeSet(attr, funcPublic);
1794:                 }
1795:                 if (accessTag.indexOf("protected") != -1) {
1796:                     generateSingleAttributeSet(attr, funcProtected);
1797:                 }
1798:                 if (accessTag.indexOf("private") != -1) {
1799:                     generateSingleAttributeSet(attr, funcPrivate);
1800:                 }
1801:             }
1802: 
1803:             accessTag = Model.getFacade().getTaggedValueValue(attr, "get");
1804:             if (accessTag != null && accessTag.length() > 0) {
1805:                 if (accessTag.indexOf("public") != -1) {
1806:                     generateSingleAttributeGet(attr, funcPublic);
