2114:     private String generateTaggedValues(Object e, int tagSelection) {
2115:         Iterator iter = Model.getFacade().getTaggedValues(e);
2116:         if (!iter.hasNext()) {
2117:             return "";
2118:         }
2119:         StringBuffer buf = new StringBuffer();
2120:         boolean first = true;
2121: 
2122:         String s = null;
2123:         while (iter.hasNext()) {
2124:             s = generateTaggedValue(iter.next(), tagSelection);
2125:             if (s != null && s.length() > 0) {
2126:                 if (first) {
2127:                     /*
2128:                      * Corrected 2001-09-26 STEFFEN ZSCHALER
2129:                      *
2130:                      * Was:
2131:                      buf.append("// {");
2132:                      *
2133:                      * which caused problems with new lines characters
2134:                      * in tagged values (e.g. comments...). The new
2135:                      * version still has some problems with tagged
2136:                      * values containing "*"+"/" as this closes the
2137:                      * comment prematurely, but comments should be
2138:                      * taken out of the tagged values list anyway...
2139:                      */
2140: 
2141:                     if (tagSelection == DOC_COMMENT_TAGS) {
2142:                         // insert main documentation for DocComment at first
2143:                         String doc =
2144:                             (DocumentationManager.hasDocs(e))
2145:                             ? DocumentationManager.getDocs(e, indent)
2146:                             : null;
2147:                         if (doc != null && doc.trim().length() > 0) {
2148:                             buf.append(doc.substring(0, doc.indexOf("*/") + 1));
2149:                             buf.append("  ");
2150:                         }
2151:                         else {
2152:                             buf.append("/** ");
2153:                         }
2154:                     }
2155:                     else {
2156:                         buf.append("/* {");
2157:                     }
2158:                     first = false;
2159:                 } // end first
2160:                 else {
2161:                     if (tagSelection == DOC_COMMENT_TAGS) {
2162:                         buf.append(LINE_SEPARATOR)
2163:                             .append(indent).append(" *  ");
2164:                     }
2165:                     else {
2166:                         buf.append(", ");
2167:                     }
2168:                 } // end not first tag
2169:                 buf.append(s);
2170:             } // end tag not empty
2171:         } // end while
2172:         /*
2173:          * Corrected 2001-09-26 STEFFEN ZSCHALER
2174:          *
2175:          * Was:
2176:          if (!first) buf.append("}\n");
2177:          *
2178:          * which caused problems with new-lines in tagged values.
2179:          */
2180:         if (!first) {
2181:             if (tagSelection == DOC_COMMENT_TAGS) {
2182:                 buf.append(LINE_SEPARATOR).append(indent).append(" */")
2183:                     .append(LINE_SEPARATOR);
2184:             } else {
2185:                 buf.append ("}*/").append(LINE_SEPARATOR);
2186:             }
2187:         }
2188:         else if (tagSelection == DOC_COMMENT_TAGS) {
2189:             // create at least main documentation field, if no other tag found
2190:             String doc = (DocumentationManager.hasDocs(e))
2191:                 ? DocumentationManager.getDocs(e, indent)
2192:                 : null;
2193:             if (doc != null && doc.trim().length() > 0) {
2194:                 buf.append(doc).append(LINE_SEPARATOR);
2195:             }
2196:         }
2197: 
2198:         return buf.toString();
2199:     }
