2418:     /**
2419:      * @see org.argouml.application.api.NotationProvider2#generateAssociationEnd(java.lang.Object)
2420:      */
2421:     public String generateAssociationEnd(Object ae) {
2422:         if (!Model.getFacade().isNavigable(ae)) {
2423:             return "";
2424:         }
2425:         if (Model.getFacade().isAbstract(
2426:                 Model.getFacade().getAssociation(ae))) {
2427:             return "";
2428:         }
2429:         StringBuffer sb = new StringBuffer(80);
2430: 
2431:         sb.append(generateAssociationEndScope(ae));
2432: 
2433:         String n = Model.getFacade().getName(ae);
2434:         Object asc = Model.getFacade().getAssociation(ae);
2435:         String ascName = Model.getFacade().getName(asc);
2436:         String name = null;
2437: 
2438:         if (n != null && n.length() > 0) {
2439:             name = generateName(n);
2440:         } else if (ascName != null && ascName.length() > 0) {
2441:             name = generateName(ascName);
2442:         } else {
2443:             name = "my" + generateClassifierRef(Model.getFacade().getType(ae));
2444:         }
2445: 
2446:         String modifier;
2447:         if (Model.getFacade().isAAssociationClass(asc)) {
2448:             // With an association class, we actually make an association
2449:             // between us and the association class itself.
2450:             // Usually, this is a pointer or a reference, so default
2451:             // to a pointer.
2452:             modifier = generateAttributeParameterModifier(asc, "*");
2453:             // add the association class in the dependency list
2454:             addDependency(asc, !checkIncludeNeeded4Element(ae)); 
2455:         } else {
2456:             modifier = generateAttributeParameterModifier(ae);
2457:             // add the type of the association end in the dependency list
2458:             boolean predecl = !checkIncludeNeeded4Element(ae);
2459:             addDependency(Model.getFacade().getType(ae), predecl);
2460:         }
2461:         
2462:         sb.append(generateMultiplicity(ae, name,
2463:                              Model.getFacade().getMultiplicity(ae),
2464:                              modifier));
2465: 
2466:         return (sb.append(";").append(LINE_SEPARATOR)).toString();
2467:     }
