360:      * @param sep package separator
361:      * @return path relative to pack, if pack is a parent of
362:      *         cls, else relative to the project root. If the
363:      *         path is relative to the project root, it's prefixed
364:      *         with sep.
365:      */
366:     private String generateRelativePackage(Object cls, Object pack,
367:             String sep) {
368:         StringBuffer packagePath = new StringBuffer();
369:         // avoid model being used as a package name
370:         Object parent = Model.getFacade().getNamespace(cls);
371: 
372:         while (parent != null && parent != pack) {
373:             // ommit root package name; it's the model's root
374:             Object grandParent = Model.getFacade().getNamespace(parent); 
375:             if (grandParent != null) {
376:                 String name = Model.getFacade().getName(parent);
377:                 if (packagePath.length() > 0) {
378:                     packagePath.insert(0, sep);
379:                 }
380:                 packagePath.insert(0, name);
381:             }
382:             parent = grandParent;
383:         }
384:         if (parent == null) { // relative to root, prefix with sep
385:             packagePath.insert(0, sep);
386:         }
387:        return packagePath.toString();
