592:     private boolean checkIncludeNeeded4Element(Object cls) {
593:         String usageTag = "";
594:         boolean predeclareCandidate = false;
595: 
596:         Iterator iter = Model.getFacade().getTaggedValues(cls);
597:         while (iter.hasNext()) {
598:             Object tv = iter.next();
599:             String tag = Model.getFacade().getTagOfTag(tv);
600:             if (tag.equals("usage")) {
601:                 usageTag = Model.getFacade().getValueOfTag(tv);
602:             }
603: 
604:             if (tag.indexOf("ref") != -1 || tag.equals("&")
605:                     || tag.indexOf("pointer") != -1 || tag.equals("*")) {
606:                 predeclareCandidate = true;
607:             }
608:         }
609:         return checkInclude4UsageIndirection(predeclareCandidate, usageTag);
