646:     /**
647:      * Parses header_incl or source_incl tags and adds the
648:      * user-speficied headers to localInc or systemInc.
649:      * @param cls The classifier which code is being generated for.
650:      * @param source if true parses source_incl tags, else header_incl.
651:      */
652:     private void addUserHeaders(Object cls, boolean source) {
653:         Iterator iter = Model.getFacade().getTaggedValues(cls);
654:         String tagPrefix;
655:         if (source)
656:             tagPrefix = "source";
657:         else
658:             tagPrefix = "header";
659:             
660:         while (iter.hasNext()) {
661:             Object tv = iter.next();
662:             String tag = Model.getFacade().getTagOfTag(tv);
663:             if (tag.equals(tagPrefix + "_incl")
664:                     || tag.equals(tagPrefix + "_include")) {
665:                 String name = Model.getFacade().getValueOfTag(tv);
666:                 if (name.length() > 2 && name.charAt(0) == '<') {
667:                     systemInc.add(name.substring(1, name.length() - 1));
668:                 } else if (name.length() > 2 && name.charAt(0) == '"') {
669:                     localInc.add(name.substring(1, name.length() - 1));
670:                 } else if (name.length() > 0) { // skip empty values
671:                     localInc.add(name);
672:                 }
673:             }
674:         }
675:     }
