1694:     private void generateSingleAttributeSet(Object attr, StringBuffer sb) {
1695:         if (Model.getFacade().getType(attr) == null) {
1696:             return;
1697:         }
1698:         // generate for attributes with class-type:
1699:         // "indent void set_<name>( const <type> &value ) { <name> = value; };"
1700:         // generate for other (small) data types:
1701:         // "indent void set_<name>( <type> value ) { <name> = value; };"
1702:         // generate: "indent void set_<name>( "
1703:         sb.append(LINE_SEPARATOR).append(indent);
1704:         sb.append("/** simple access function to set the attribute ");
1705:         sb.append(Model.getFacade().getName(attr));
1706:         sb.append(" by function").append(LINE_SEPARATOR).append(indent);
1707:         sb.append("  * @param value value to set for the attribute ");
1708:         sb.append(Model.getFacade().getName(attr)).append(LINE_SEPARATOR);
1709:         sb.append(indent).append("  */").append(LINE_SEPARATOR);
1710:         sb.append(indent);
1711:         sb.append("void set_").append(Model.getFacade().getName(attr))
1712:             .append("( ");
1713:         String modifier = generateAttributeParameterModifier(attr);
1714:         if (modifier != null && modifier.length() > 0) {
1715:             // generate: "const <type> <modifier>value"
1716:             if (modifier.equals("&")) sb.append("const ");
1717:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)))
1718:                 .append(' ').append(modifier).append("value");
1719:         } else if (Model.getFacade().isAClass(
1720:                 Model.getFacade().getType(attr))) {
1721:             // generate: "const <type> &value"
1722:             sb.append("const ");
1723:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)));
1724:             sb.append(" &value");
1725:         } else {
1726:             // generate: "<type> value"
1727:             sb.append(generateClassifierRef(Model.getFacade().getType(attr)))
1728:                 .append(" value");
1729:         }
1730:         // generate: " ) { <name> = value; };"
1731:         sb.append(" ) { ").append(Model.getFacade().getName(attr));
1732:         sb.append(" = value; };").append(LINE_SEPARATOR);
