2014:     /**
2015:      * Generate the body of a method associated with the given
2016:      * operation.  This assumes there's at most one method associated!
2017:      *
2018:      * If no method is associated with the operation, a default method
2019:      * body will be generated.
2020:      */
2021:     private String generateMethodBody(Object op) {
2022:         if (op != null) {
2023:             StringBuffer sb = new StringBuffer(80);
2024:             Collection methods = Model.getFacade().getMethods(op);
2025:             Iterator i = methods.iterator();
2026:             Object method = null;
2027:             boolean methodFound = false;
2028:             String tv = generateTaggedValues(op, ALL_BUT_DOC_TAGS);
2029:             String operationIndent =
2030:                 (generatorPass == HEADER_PASS) ? indent : "";
2031: 
2032:             // append tags which are not Doc-Comments
2033:             if (tv.length() > 0) {
2034:                 sb.append(operationIndent).append(tv).append(LINE_SEPARATOR);
2035:             }
2036: 
2037:             // place the curley braces within the protected area, to
2038:             // allow placement of preserved contructor initialisers in
2039:             // this area otherwise all possible constructor-attribute
2040:             // initialisers would have to be autogenerated with an
2041:             // army of special tags
2042:             sb.append(generateSectionTop(op, operationIndent))
2043:                 .append(operationIndent).append("{").append(LINE_SEPARATOR);
2044: 
2045:             while (i != null && i.hasNext()) {
2046:                 method = i.next();
2047: 
2048:                 if (method != null) {
2049:                     if ((Model.getFacade().getBody(method) != null)
2050:                             && (!methodFound)) {
2051:                         Object body = Model.getFacade().getBody(method);
2052:                         sb.append(Model.getFacade().getBody(body));
2053:                         methodFound = true;
2054:                         break;
2055:                     }
2056:                 }
2057:             }
2058: 
2059:             if (!methodFound) {
2060:                 // pick out return type as default method body
2061:                 Object rp =
2062:                     Model.getCoreHelper().getReturnParameter(op);
2063:                 if (rp != null) {
2064:                     Object returnType = Model.getFacade().getType(rp);
2065:                     sb.append(generateDefaultReturnStatement(returnType));
2066:                 }
2067:             }
2068:             sb.append(operationIndent).append("}").append(LINE_SEPARATOR)
2069:                 .append(generateSectionBottom(op, operationIndent));
2070:             return sb.toString();
2071:         }
2072:         return generateDefaultReturnStatement (null);
2073:     }
