2201:     private String generateTaggedValue(Object tv, int tagSelection) {
2202:         if (tv == null) return "";
2203:         String s = generateUninterpreted(Model.getFacade().getValueOfTag(tv));
2204: 
2205:         String tagName = Model.getFacade().getTagOfTag(tv);
2206:         if (s == null || s.length() == 0 || s.equals("/** */")
2207:             || (tagName.indexOf("include") != -1)
2208:             || (tagName.indexOf("_incl") != -1)) {
2209:             return "";
2210:         }
2211:         if ((tagSelection == DOC_COMMENT_TAGS)
2212:                 && (isDocCommentTag(tagName))) {
2213:             return generateDocComment4Tag(generateName(tagName)) + s;
