2304:     /**
2305:      * Enhance/Create the doccomment for the given model element,
2306:      * including tags for any OCL constraints connected to the model
2307:      * element. The tags generated are suitable for use with the ocl
2308:      * injector which is part of the Dresden OCL Toolkit and are in
2309:      * detail:
2310:      *
2311:      * &nbsp;@invariant for each invariant specified
2312:      * &nbsp;@precondition for each precondition specified
2313:      * &nbsp;@postcondition for each postcondition specified
2314:      * &nbsp;@key-type specifying the class of the keys of a mapped association
2315:      * &nbsp; Currently mapped associations are not supported yet...
2316:      * &nbsp;@element-type specifying the class referenced in an association
2317:      *
2318:      * @since 2001-09-26 ArgoUML 0.9.3
2319:      * @author Steffen Zschaler
2320:      *
2321:      * @param me the model element for which the documentation comment is needed
2322:      * @param ae the association end which is represented by the model element
2323:      * @return the documentation comment for the specified model element, either
2324:      * enhanced or completely generated
2325:      */
2326:     public String generateConstraintEnrichedDocComment(Object me, Object ae) {
2327:         // list tagged values for documentation
2328:         String s = generateTaggedValues (me, DOC_COMMENT_TAGS);
2329: 
2330:         if (Model.getFacade().getUpper(ae) != 1) {
2331:             // Multiplicity greater 1, that means we will generate some sort of
2332:             // collection, so we need to specify the element type tag
2333:             StringBuffer sDocComment = new StringBuffer(80);
2334: 
2335:             // Prepare doccomment
2336:             if (!(s == null || "".equals(s))) {
2337:                 // Just remove closing "*/"
2338:                 sDocComment.append(indent)
2339:                     .append(s.substring(0, s.indexOf("*/") + 1));
2340:             }
2341:             else {
2342:                 sDocComment.append(indent).append("/**").append(LINE_SEPARATOR);
2343:                 sDocComment.append(indent).append(" *");
2344:             }
2345: 
2346:             // Build doccomment
2347:             Object type = Model.getFacade().getType(ae);
2348:             if (type != null) {
2349:                 sDocComment.append(" @element-type ");
2350:                 sDocComment.append(Model.getFacade().getName(type));
2351:             }
2352:             sDocComment.append(LINE_SEPARATOR).append(indent)
2353:                 .append(" */").append(LINE_SEPARATOR);
2354:             return sDocComment.toString();
2355:         }
2356:         return (s != null) ? s : "";
2357:     }
