2677:     private String generateMultiplicity(Object item, String name,
2678:             Object m, String modifier) {
2679:         String type = null;
2680:         String containerType = null;
2681:         Object typeCls = null;
2682:         if (Model.getFacade().isAAssociationEnd(item)) {
2683:             // take into account association classes
2684:             Object assoc = Model.getFacade().getAssociation(item);
2685:             if (Model.getFacade().isAAssociationClass(assoc)) {
2686:                 typeCls = assoc;
2687:                 name += "Assoc";
2688:             }
2689:             else
2690:                 typeCls = Model.getFacade().getType(item);
2691:         } else if (Model.getFacade().isAAttribute(item)) {
2692:             typeCls = Model.getFacade().getType(item);
2693:         } else if (Model.getFacade().isAClassifier(item)) {
2694:             //type = Model.getFacade().getName(item);
2695:             typeCls = item;
2696:         } else {
2697:             type = "";
2698:         }
2699:         if (typeCls != null) {
2700:             type = generateNameWithPkgSelection(typeCls);
2701:         }
2702:         if (m == null) {
2703:             return (type + " " + modifier + name);
2704:         }
2705:         StringBuffer sb = new StringBuffer(80);
2706:         int countUpper = Model.getFacade().getUpper(m);
2707:         int countLower = Model.getFacade().getLower(m);
2708: 
2709:         if (countUpper == 1 && countLower == 1) {
2710:             // simple generate identifier for default 1:1 multiplicity
2711:             sb.append(type).append(' ').append(modifier).append(name);
2712:         } else if (countUpper == 1 && countLower == 0) {
2713:             // use a simple pointer for 0:1 multiplicity
2714:             // TODO: use an auto_ptr in case of attributes or compositions
2715:             sb.append(type).append(' ').append(modifier)
2716:                 .append("* ").append(name);
2717:         } else if (countUpper == countLower) {
2718:             // fixed array -> <type> <name>[<count>];
2719:             sb.append(type).append(' ').append(modifier).append(name)
2720:                 .append("[ " + countUpper + "]");
2721:         } else {
2722:             // variable association -> if no tag found use vector
2723:             // else search for tag:
2724:             // <MultipliciyType> : vector|list|slist|map|stack|stringmap
2725:             String multType =
2726:                 Model.getFacade().getTaggedValueValue(item, "MultiplicityType");
2727:             if (multType != null && multType.length() > 0) {
2728:                 if (multType.equals("vector")) {
2729:                     containerType = "vector";
2730:                 } else if (multType.equals("list")) {
2731:                     containerType = "list";
2732:                 } else if (multType.equals("slist")) {
2733:                     containerType = "slist";
2734:                 } else if (multType.equals("map")) {
2735:                     // FIXME: map does not work this way, needs a index type
2736:                     containerType = "map";
2737:                 } else if (multType.equals("stack")) {
2738:                     containerType = "stack";
2739:                 } else if (multType.equals("stringmap")) {
2740:                     systemInc.add("string");
2741:                     systemInc.add("map");
2742:                     sb.append(stdPrefix + "map<" + stdPrefix + "string, ");
2743:                     if (modifier.indexOf('&') != -1) {
2744:                         LOG.warn("cannot generate STL container "
2745:                                 + "with references, using pointers");
2746:                         modifier = "*";
2747:                     }
2748:                     sb.append(type).append(modifier);
2749:                     sb.append(" > ").append(name);
2750:                 } else {
2751:                     LOG.warn("unknown MultiplicityType \"" + multType
2752:                             + "\", using default");
2753:                     containerType = "vector";
2754:                 }
2755:             } else {
2756:                 containerType = "vector";
2757:             }
2758: 
2759:             if (containerType != null) {
2760:                 // these container are declared the same except the name
2761:                 systemInc.add(containerType);
2762:                 sb.append(stdPrefix).append(containerType).append("< ");
2763:                 if (modifier.indexOf('&') != -1) {
2764:                     LOG.warn("cannot generate STL container "
2765:                             + "with references, using pointers");
2766:                     modifier = "*";
2767:                 }
2768:                 sb.append(type).append(modifier);
2769:                 sb.append(" > ").append(name);
2770:             }
2771:         }
2772:         return sb.toString();
2773:     }
