3030:      */
3031:     private Collection generateFilesForElem(Object o,
3032:                                             String path, boolean deps) {
3033:         Vector ret = new Vector();
3034:         if (generatedFiles.contains(o)) {
3035:             return ret; // generated already
3036:         }
3037:         if (!Model.getFacade().isAClass(o)
3038:                 && !Model.getFacade().isAInterface(o)) {
