3040:         }
3041:         while (isAInnerClass(o)) {
3042:             o = Model.getFacade().getNamespace(o);
3043:         }
3044:         String pathname = null;
3045: 
3046:         // use unique section for both passes -> allow move of
3047:         // normal function body to inline and vice versa
3048:         if (Section.getUseSect() != Section.SECT_NONE) {
3049:             sect = new Section();
3050: 
3051:             /*
