3064:                     sect.read(pathname);
3065:                     File bakFile = new File(pathname + ".bak");
3066:                     if (bakFile.exists()) {
3067:                         bakFile.delete();
3068:                     }
3069:                     f.renameTo(bakFile);
3070:                 } else {
3071:                     LOG.info("Generating (new) " + f.getPath());
3072:                 }
3073:             }
3074:         }
3075: 
3076:         Set dependencies = null;
3077:         if (deps) dependencies = new TreeSet();
3078:         /**
3079:          * 2002-11-28 Achim Spangler
3080:          * run basic generation function two times for header and implementation
3081:          */
3082:         for (generatorPass = HEADER_PASS;
3083:              generatorPass <= SOURCE_PASS;
3084:              generatorPass++) {
3085:             pathname = createDirectoriesPathname(o, path);
3086:             String fileContent = generateFileAsString(o, pathname);
3087:             if (fileContent.length() == 0) continue;
3088:             BufferedWriter fos = null;
3089:             //String pathname = path + filename;
3090:             // TODO: package, project basepath, tagged values to configure
3091:             File f = new File(pathname);
3092:             try {
3093:                 fos = new BufferedWriter (new FileWriter (f));
3094:                 writeTemplate(o, path, fos);
3095:                 fos.write(fileContent);
3096:             }
3097:             catch (IOException exp) { }
3098:             finally {
