3100:                     if (fos != null) fos.close();
3101:                 }
3102:                 catch (IOException exp) {
3103:                     LOG.error("FAILED: " + f.getPath());
3104:                 }
3105:             }
3106: 
3107:             LOG.info("written: " + pathname);
3108: 
3109:             if (Section.getUseSect() != Section.SECT_NONE) {
3110:                 // output lost sections only in the second path
3111:                 // -> sections which are moved from header(inline) to source
3112:                 // file are prevented to be outputted in header pass
3113:                 File outFile = new File(pathname + ".out");
3114:                 if (outFile.exists()) {
3115:                     outFile.delete(); // remove junk
3116:                 }
3117:                 if (generatorPass == HEADER_PASS)   {
3118:                     sect.write(pathname, indent, false);
3119:                 } else {
3120:                     sect.write(pathname, indent, true);
3121:                 }
3122: 
3123:                 if (outFile.exists()) {
3124:                     assert f.exists();
3125:                     f.delete();
3126:                     outFile.renameTo(f);
3127:                     LOG.info("added sections to: " + pathname);
3128:                 }
3129:             }
3130:             LOG.info("----- end updating " + pathname + "-----");
3131:             ret.add(pathname);
