3134:                 dependencies.add(predeclCls);
3135:             }
3136:         }
3137:         cleanupGenerator();
3138:         // reset generator pass to NONE for the notation to be correct
3139:         generatorPass = NONE_PASS;
3140:         generatedFiles.add(o);
3141:         if (deps) {
3142:             Iterator it = dependencies.iterator();
3143:             while (it.hasNext()) {
3144:                 ret.add(generateFilesForElem(it.next(), path, deps));
3145:             }
3146:         }
