296:     private void initMenuCreateModelElements() {
297: 	List targets = TargetManager.getInstance().getTargets();
298:         List menuItems = new ArrayList();
299: 	if (targets.size() >= 2) {
300: 	    // Check to see if all targets are classifiers
301: 	    // before adding an option to create an association between
302: 	    // them all
303: 	    boolean classifiersOnly = true;
304: 	    for (Iterator it = targets.iterator();
305: 	            it.hasNext() && classifiersOnly; ) {
306: 		if (!Model.getFacade().isAClassifier(it.next())) {
307: 		    classifiersOnly = false;
