336: 	        Collection menuItems,
337: 		Object metaType) {
338: 	List targets = TargetManager.getInstance().getTargets();
339: 	Object source = targets.get(0);
340: 	Object dest = targets.get(1);
341: 	if (Model.getUmlFactory().isConnectionValid(
