185:                 if (!LastLoadInfo.getInstance().getLastLoadStatus()) {
186:                     p = oldProject;
187:                     success = false;
188:                     showErrorPane(
189:                             "Problem in loading the project "
190:                             + url.toString()
191:                             + "\n"
192:                             + "Project file probably corrupt from "
193:                             + "an earlier version or ArgoUML.\n"
194:                             + "Error message:\n"
195:                             + LastLoadInfo.getInstance().getLastLoadMessage()
196:                             + "\n"
197:                             + "Since the project was incorrectly "
198:                             + "saved some things might be missing "
199:                             + "from before you saved it.\n"
200:                             + "These things cannot be restored. "
201:                             + "You can continue working with what "
202:                             + "was actually loaded.\n");
203:                 }
204:                 else if (oldProject != null) {
205:                     // if p equals oldProject there was an exception and we do
206:                     // not have to gc (garbage collect) the old project
207:                     if (p != null && !p.equals(oldProject)) {
208:                         //prepare the old project for gc
209:                         ProjectManager.getManager().removeProject(oldProject);
210:                     }
211:                 }
212:                 ProjectManager.getManager().setCurrentProject(p);
213:                 Designer.enableCritiquing();
214:             }
215:         }
216:         return success;
217:     }
