38: /**
39:  * To persist to and from XMI file storage.
40:  * 
41:  * @author Bob Tarling
42:  */
43: public class XmiFilePersister extends AbstractFilePersister {
44:     
45:     private static final Logger LOG = 
46:         Logger.getLogger(XmiFilePersister.class);
47:     
48:     /**
49:      * The constructor.
50:      */
51:     public XmiFilePersister() {
52:     }
53: 
54:     /**
55:      * @see org.argouml.persistence.AbstractFilePersister#getExtension()
56:      */
57:     public String getExtension() {
58:         return "xmi";
59:     }
60:     
61:     /**
62:      * @see org.argouml.persistence.AbstractFilePersister#getDesc()
63:      */
64:     protected String getDesc() {
65:         return "XML Metadata Interchange";
66:     }
67:     
68:     /**
69:      * Save a project to a file in XMI format.
70:      * 
71:      * @param project the project to save.
72:      * @param file The file to write.
73:      * @throws SaveException if anything goes wrong.
74:      */
75:     public void doSave(Project project, File file)
76:         throws SaveException {
77: 
78:         // frank: first backup the existing file to name+"#"
79:         File tempFile = new File( file.getAbsolutePath() + "#");
80:         File backupFile = new File( file.getAbsolutePath() + "~");
81:         if (tempFile.exists()) {
82:             tempFile.delete();
83:         }
84:         
85:         BufferedWriter writer = null;
86:         try {
87:             if (file.exists()) {
88:                 copyFile(tempFile, file);
89:             }
90:             // frank end
91:     
92:             project.setFile(file);
93:             
94:             writer =
95:                 new BufferedWriter(new FileWriter(file));
96:     
97:             int size = project.getMembers().size();
98:             for (int i = 0; i < size; i++) {
99:                 ProjectMember projectMember = 
100:                     (ProjectMember) project.getMembers().elementAt(i);
101:                 if (projectMember.getType().equalsIgnoreCase("xmi")) {
102:                     if (LOG.isInfoEnabled()) {
103:                         LOG.info("Saving member of type: "
104:                               + ((ProjectMember) project.getMembers()
105:                                     .elementAt(i)).getType());
106:                     }
107:                     projectMember.save(writer, null);
108:                 }
109:             }
110:             
111:             // if save did not raise an exception 
112:             // and name+"#" exists move name+"#" to name+"~"
113:             // this is the correct backup file
114:             if (backupFile.exists()) {
115:                 backupFile.delete();
116:             }
117:             if (tempFile.exists() && !backupFile.exists()) {
118:                 tempFile.renameTo(backupFile);
119:             }
120:             if (tempFile.exists()) {
121:                 tempFile.delete();
122:             }
123:         } catch (Exception e) {
124:             LOG.error("Exception occured during save attempt", e);
125:             try {
126:                 writer.close();
127:             } catch (IOException ex) { }
128:             
129:             // frank: in case of exception 
130:             // delete name and mv name+"#" back to name if name+"#" exists
131:             // this is the "rollback" to old file
132:             file.delete();
133:             tempFile.renameTo( file);
134:             // we have to give a message to user and set the system to unsaved!
135:             throw new SaveException(e);
136:         }
137: 
138:         try {
139:             writer.close();
140:         } catch (IOException ex) {
141:             LOG.error("Failed to close save output writer", ex);
142:         }
143:     }
