102:      *
103:      * @see org.argouml.persistence.ProjectFilePersister#doSave(
104:      * org.argouml.kernel.Project, java.io.File)
105:      */
106:     public void doSave(Project project, File file)
107:         throws SaveException {
108:         
109:         // frank: first backup the existing file to name+"#"
110:         File tempFile = new File( file.getAbsolutePath() + "#");
111:         File backupFile = new File( file.getAbsolutePath() + "~");
112:         if (tempFile.exists()) {
113:             tempFile.delete();
114:         }
115:         
116:         BufferedWriter writer = null;
117:         try {
118:             if (file.exists()) {
119:                 copyFile(tempFile, file);
120:             }
121:             // frank end
122:     
123:             project.setFile(file);
124:             project.setVersion(ArgoVersion.getVersion());
125:             project.setPersistenceVersion(PERSISTENCE_VERSION);
126: 
127:             ZipOutputStream stream =
128:                 new ZipOutputStream(new FileOutputStream(file));
129:             writer =
130:                 new BufferedWriter(new OutputStreamWriter(stream, "UTF-8"));
131:     
132:             ZipEntry zipEntry =
133:                 new ZipEntry(project.getBaseName() 
134:                         + FileConstants.UNCOMPRESSED_FILE_EXT);
135:             stream.putNextEntry(zipEntry);
136:             
137:             Hashtable templates = TemplateReader.getInstance()
138:                 .read(ARGO_MINI_TEE);
139:             OCLExpander expander = new OCLExpander(templates);
140:             expander.expand(writer, project, "", "");
141:                 
142:             writer.flush();
143:             
144:             stream.closeEntry();
145:     
146:             // First we save all objects that are not XMI objects i.e. the
147:             // diagrams (first for loop).
148:             // Then we save all XMI objects (second for loop).
149:             // This is because order is important on saving.
150:             // Bob - Why not do it the other way around? Surely
151:             // when reloading it is better to load XMI first
152:             // then the diagrams.
153:             Collection names = new ArrayList();
154:             int counter = 0;  
155:             int size = project.getMembers().size();
156:             for (int i = 0; i < size; i++) {
157:                 ProjectMember projectMember = 
158:                     (ProjectMember) project.getMembers().elementAt(i);
159:                 if (!(projectMember.getType().equalsIgnoreCase("xmi"))) {
160:                     if (LOG.isInfoEnabled()) {
161:                         LOG.info("Saving member: "
162:                               + ((ProjectMember) project.getMembers()
163:                                     .elementAt(i)).getName());
164:                     }
165:                     String name = projectMember.getName();
166:                     String originalName = name;
167:                     while (names.contains(name)) {
168:                         name = ++counter + originalName;
169:                     }
170:                     names.add(name);
171:                     stream.putNextEntry(new ZipEntry(name));
172:                     projectMember.save(writer, null);
173:                     writer.flush();
174:                     stream.closeEntry();
175:                 }
176:             }
177: 
178:             for (int i = 0; i < size; i++) {
179:                 ProjectMember projectMember = 
180:                     (ProjectMember) project.getMembers().elementAt(i);
181:                 if (projectMember.getType().equalsIgnoreCase("xmi")) {
182:                     if (LOG.isInfoEnabled()) {
183:                         LOG.info("Saving member of type: "
184:                               + ((ProjectMember) project.getMembers()
185:                                     .elementAt(i)).getType());
186:                     }
187:                     stream.putNextEntry(new ZipEntry(projectMember.getName()));
188:                     projectMember.save(writer, null);
189:                 }
190:             }
191:             
192:             // if save did not raise an exception 
193:             // and name+"#" exists move name+"#" to name+"~"
194:             // this is the correct backup file
195:             if (backupFile.exists()) {
196:                 backupFile.delete();
197:             }
198:             if (tempFile.exists() && !backupFile.exists()) {
199:                 tempFile.renameTo(backupFile);
200:             }
201:             if (tempFile.exists()) {
202:                 tempFile.delete();
203:             }
204:         } catch (Exception e) {
205:             LOG.error("Exception occured during save attempt", e);
206:             try {
207:                 writer.close();
208:             } catch (IOException ex) { }
209:             
210:             // frank: in case of exception 
211:             // delete name and mv name+"#" back to name if name+"#" exists
212:             // this is the "rollback" to old file
213:             file.delete();
214:             tempFile.renameTo( file);
215:             // we have to give a message to user and set the system to unsaved!
216:             throw new SaveException(e);
217:         }
218: 
219:         try {
220:             writer.close();
221:         } catch (IOException ex) {
222:             LOG.error("Failed to close save output writer", ex);
223:         }
224:     }
