63:         extends AbstractArgoJPanel
64:         implements
65:                 Runnable,
66:                 MouseListener,
67:                 ActionListener,
68:                 ListSelectionListener,
69:                 KeyListener {
70:     private static final Logger LOG = Logger.getLogger(TabResults.class);
71: 
72:     private static int numJumpToRelated = 0;
73: 
74:     /** Insets in pixels  */
75:     private static final int INSET_PX = 3;
