93:     private JTable relatedTable = new JTable(4, 4);
94:     private TMResults relatedModel = new TMResults();
95: 
96:     /**
97:      * The constructor.
98:      *
99:      */
100:     public TabResults() {
101: 	this(true);
102:     }
103: 
104:     /**
105:      * The constructor.
106:      *
107:      * @param showRelated true if related results should be shown
108:      */
