297:     // KeyListener implementation
298: 
299:     /**
300:      * @see java.awt.event.KeyListener#keyPressed(java.awt.event.KeyEvent)
301:      */
302:     public void keyPressed(KeyEvent e) {
303:         
304:         if (e.getKeyCode() == KeyEvent.VK_ENTER) {
305:             e.consume();
306:             myDoubleClick(e.getSource());
307:         }
308:     }
309: 
310:     /**
311:      * @see java.awt.event.KeyListener#keyReleased(java.awt.event.KeyEvent)
312:      */
313:     public void keyReleased(KeyEvent e) {
314:     }
315: 
316:     /**
317:      * @see java.awt.event.KeyListener#keyTyped(java.awt.event.KeyEvent)
318:      */
319:     public void keyTyped(KeyEvent e) {
320:     }
321: 
322:     ////////////////////////////////////////////////////////////////
323:     // ListSelectionListener implementation
324: 
325:     /**
326:      * @see javax.swing.event.ListSelectionListener#valueChanged(javax.swing.event.ListSelectionEvent)
327:      */
328:     public void valueChanged(ListSelectionEvent lse) {
329: 	if (lse.getValueIsAdjusting()) {
330: 	    return;
331: 	}
332: 	if (relatedShown) {
333: 	    int row = lse.getFirstIndex();
334: 	    Object sel = results.elementAt(row);
335: 	    LOG.debug("selected " + sel);
336: 	    related.removeAllElements();
337: 	    Enumeration elems =
338: 		ChildGenRelated.getSingleton().gen(sel);
339: 	    if (elems != null) {
340: 		while (elems.hasMoreElements()) {
341: 		    related.addElement(elems.nextElement());
342: 		}
343: 	    }
344: 	    relatedModel.setTarget(related, null);
345: 	    Object[] msgArgs = {new Integer(related.size()) };
346: 	    relatedLabel.setText(Translator.messageFormat(
347:                 "dialog.find.related-elements", msgArgs));
348: 	}
349:     }
350: 
351:     ////////////////////////////////////////////////////////////////
352:     // actions
353: 
354:     /**
355:      * @see java.lang.Runnable#run()
356:      */
357:     public void run() {
358: 	resultsLabel.setText(Translator.localize("dialog.find.searching"));
359: 	results.removeAllElements();
360: 	depthFirst(root, null);
361: 	setResults(results, diagrams);
362:     }
363: 
364:     private void depthFirst(Object node, Diagram lastDiagram) {
365: 	if (node instanceof Diagram) {
366: 	    lastDiagram = (Diagram) node;
367: 	    if (!pred.matchDiagram(lastDiagram))
368: 		return;
369: 	    // diagrams are not placed in search results
370: 	}
371: 	Enumeration elems = cg.gen(node);
372: 	while (elems.hasMoreElements()) {
373: 	    Object c = elems.nextElement();
374: 	    if (pred.predicate(c)) {
375: 		results.addElement(c);
376: 		diagrams.addElement(lastDiagram);
377: 	    }
378: 	    depthFirst(c, lastDiagram);
379: 	}
380:     }
381: 
382: } /* end class TabResults */
