536:      */
537:     protected void updateBounds() {
538:         Rectangle bbox = getBounds();
539:         Dimension minSize = getMinimumSize();
540:         bbox.width = Math.max(bbox.width, minSize.width);
541:         bbox.height = Math.max(bbox.height, minSize.height);
542:         setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
543:     }
