553:      */
554:     protected final void modelChanged(PropertyChangeEvent mee) {
555:         super.modelChanged(mee);
556: 
557:         if (mee instanceof AttributeChangeEvent
558:                 && mee.getPropertyName().equals("body")) {
559:             
560:             bodyTextFig.setText(mee.getNewValue().toString());
561:             calcBounds();
562:             setBounds(getBounds());
563:             damage();
