632:      */
633:     public Point getClosestPoint(Point anotherPt) {
634:         Rectangle r = getBounds();
635:         int xs[] = {r.x, r.x + r.width - dogear, r.x + r.width, 
636:                     r.x + r.width,  r.x,            r.x};
637:         int ys[] = {r.y, r.y,                    r.y + dogear,
638:                     r.y + r.height, r.y + r.height, r.y};
639:         Point p = Geometry.ptClosestTo(
640:                 xs, 
641:                 ys,
642:                 6 , anotherPt);
643:         return p;
644:     }
