142:             valid = contains(getChangedElement(e));
143:         } else {
144:             Collection removedElements = (Collection) getChangedElement(e);
145:             Iterator it = removedElements.iterator();
146:             valid = true;
147:             while (it.hasNext()) {
148:                 Object o = it.next();
149:                 if (!contains(o)) {
150:                     valid = false;
151:                     break;
152:                 }
153:             }
154:         }
155:         if (valid) {
156:             Object o = getChangedElement(e);
157:             if (o instanceof Collection) {
