293:     /**
294:      * Returns true if some event is valid. An event is valid if the
295:      * element changed in the event is valid. This is determined via a
296:      * call to isValidElement.  This method can be overriden by
297:      * subclasses if they cannot determine if it is a valid event just
298:      * by checking the changed element.
299:      *
300:      * @param e
301:      * @return boolean
302:      */
303:     protected boolean isValidEvent(MElementEvent e) {
304:         boolean valid = false;
305:         if (!(getChangedElement(e) instanceof Collection)) {
306:             valid = isValidElement(/*(MBase)*/getChangedElement(e));
307:             if (!valid && e.getNewValue() == null && e.getOldValue() != null) {
308:                 valid = true; // we tried to remove a value
309:             }
310:         } else {
311:             Collection col = (Collection) getChangedElement(e);
312:             Iterator it = col.iterator();
313:             if (!col.isEmpty()) {
314:                 valid = true;
315:                 while (it.hasNext()) {
316:                     Object o = it.next();
317:                     if (!isValidElement(/*(MBase)*/o)) {
318:                         valid = false;
319:                         break;
320:                     }
321:                 }
322:             } else {
323:                 if (e.getOldValue() instanceof Collection
324:                     && !((Collection) e.getOldValue()).isEmpty()) {
325:                     valid = true;
326:                 }
327:             }
328:         }
329:         return valid;
330:     }
