543:     public void addMember(String name, String type) {
544:         
545:         URL memberURL = findMemberURLInSearchPath(name);
546:         if (memberURL == null) {
547:             LOG.debug("null memberURL");
548:             return;
549:         } else
550:             LOG.debug("memberURL = " + memberURL);
551:         ProjectMember pm = findMemberByName(name);
552:         if (pm != null)
553:             return;
554:         if ("pgml".equals(type))
555:             pm = new ProjectMemberDiagram(name, this);
556:         else if ("xmi".equals(type))
557:             pm = new ProjectMemberModel(name, this);
558:         else
559:             throw new RuntimeException("Unknown member type " + type);
560:         members.addElement(pm);
561:     }
