639:         // should remove the corresponding ProjectMemberDiagram not
640:         // the ArgoDiagram from the members
641: 
642:         // _members.removeElement(d);
643:         // ehhh lets remove the diagram really and remove it from its
644:         // corresponding projectmember too
645:         Iterator it = members.iterator();
646:         while (it.hasNext()) {
647:             Object obj = it.next();
648:             if (obj instanceof ProjectMemberDiagram) {
