661:         }
662:         for (int i = 0; i < members.size(); i++) {
663:             ProjectMember pm = (ProjectMember) members.elementAt(i);
664:             if (name.equals(pm.getPlainName()))
665:                 return pm;
666:         }
667:         if (LOG.isDebugEnabled()) {
668:             LOG.debug("Member \"" + name + "\" not found.");
669:         }
670:         return null;
671:     }
