827:     /**
828:      * Searches for a type/classifier with name s. If the type is not found,
829:      * a new type is created and added to the current namespace.
830:      * @param s
831:      * @return MClassifier
832:      */
833:     public Object findType(String s) {
834:         return findType(s, true);
