837:     /**
838:      * Searches for a type/classifier with name s. If defineNew is
839:      * true, a new type is defined if the type/classifier is not
840:      * found. The newly created type is added to the currentNamespace
841:      * and given the name s.
842:      * @param s
843:      * @param defineNew
844:      * @return MClassifier
845:      */
846:     public Object findType(String s, boolean defineNew) {
847:         if (s != null) {
848:             s = s.trim();
849:         }
850:         if (s == null || s.length() == 0) {
851:             return null;
852:         }
853:         Object cls = null;
854:         int numModels = _models.size();
855:         for (int i = 0; i < numModels; i++) {
856:             cls = findTypeInModel(s, _models.elementAt(i));
857:             if (cls != null) {
858:                 return cls;
859:             }
860:         }
861:         cls = findTypeInModel(s, _defaultModel);
862:         // hey, now we should move it to the model the user is working in
863:         if (cls != null) {
864:             cls = ModelManagementHelper.
865:                 getHelper().getCorrespondingElement(cls, getRoot());
866:         }
867:         if (cls == null && defineNew) {
868:             LOG.debug("new Type defined!");
869:             cls = UmlFactory.getFactory().getCore()
870:         		  .buildClass(getCurrentNamespace());
871:             ModelFacade.setName(cls, s);
872:         }
873:         return cls;
874:     }
