35: /**
36:  * The list model for the connections of the association. <p>
37:  * 
38:  * The specialty of this list model, is that it need to be aware 
39:  * of name changes in the ends connected to the association. 
40:  * Most other listmodels only listen to 
41:  * model changes in one UML element, but in this case, we also have to listen to
42:  * changes in some related elements. <p>
43:  * 
44:  * Why is this case different: because it is possible to modify the 
45:  * associationend names on the diagram, without changing the target - i.e.
46:  * the target remains the association throughout this modification.
47:  *
48:  * @author jaap.branderhorst@xs4all.nl
49:  * @since Jan 4, 2003
50:  */
51: public class UMLAssociationConnectionListModel
52:     extends UMLModelElementOrderedListModel2 {
53: 
54:     private Collection others;
55: 
56:     /**
57:      * Constructor for UMLModelElementClientDependencyListModel.
58:      */
59:     public UMLAssociationConnectionListModel() {
60:         super("connection");
61:     }
62: 
63:      /**
64:      * @see org.argouml.uml.ui.UMLModelElementListModel2#addOtherModelEventListeners(java.lang.Object)
65:      */
66:     protected void addOtherModelEventListeners(Object newTarget) {
67:         super.addOtherModelEventListeners(newTarget);
68:         /* Make a copy of the modelelements: */
69:         others = new ArrayList(Model.getFacade().getConnections(newTarget));
70:         Iterator i = others.iterator();
71:         while (i.hasNext()) {
72:             Object end = i.next();
73:             Model.getPump().addModelEventListener(this, end, "name");
74:         }
75:     }
76: 
77:     /**
78:      * @see org.argouml.uml.ui.UMLModelElementListModel2#removeOtherModelEventListeners(java.lang.Object)
79:      */
80:     protected void removeOtherModelEventListeners(Object oldTarget) {
81:         super.removeOtherModelEventListeners(oldTarget);
82:         Iterator i = others.iterator();
83:         while (i.hasNext()) {
84:             Object end = i.next();
85:             Model.getPump().removeModelEventListener(this, end, "name");
86:         }
87:         others.clear();
88:     }
89: 
90:     /**
91:      * @see org.argouml.uml.ui.UMLModelElementListModel2#buildModelList()
92:      */
93:     protected void buildModelList() {
94:         if (getTarget() != null) {
95:             setAllElements(Model.getFacade().getConnections(getTarget()));
96:         }
97:     }
98: 
99:     /**
100:      * @see org.argouml.uml.ui.UMLModelElementListModel2#isValidElement(Object)
101:      */
102:     protected boolean isValidElement(Object/*MBase*/ o) {
103:         return Model.getFacade().isAAssociationEnd(o)
104:             && Model.getFacade().getConnections(getTarget()).contains(o);
105:     }
106: 
107: 
108:     /**
109:      * @see org.argouml.uml.ui.UMLModelElementOrderedListModel2#moveTo(int, int)
110:      */
111:     public void swap(int index1, int index2) {
112:         Object assoc = getTarget();
113:         List c = new ArrayList(Model.getFacade().getConnections(assoc));
114:         Object mem1 = c.get(index1);
115:         Object mem2 = c.get(index2);
116:         c.set(index1, mem2);
117:         c.set(index2, mem1);
118:         Model.getCoreHelper().setConnections(assoc, c);
119:         buildModelList();
120:     }
121: }
