45: /**
46:  * Mode to create a link between two figobjects. This mode extends
47:  * ModeCreate and not ModeCreateEdge because ModeCreateEdge hides its
48:  * variables a bit too much...
49:  *
50:  * @author jaap.branderhorst@xs4all.nl
51:  */
52: public class ModeCreateMessage extends ModeCreate {
53: 
54:     private static final Logger LOG =
55: 	Logger.getLogger(ModeCreateMessage.class);
56: 
57:     /**
58:      * The NetPort where the arc is paintn from.
59:      */
60:     private Object startPort;
61: 
62:     /**
63:      * The Fig that presents the starting NetPort.
64:      */
65:     private Fig startPortFig;
66: 
67:     /**
68:      * The FigNode on the NetNode that owns the start port.
69:      */
70:     private FigNode sourceFigClassifierRole;
71: 
72:     /**
73:      * The new NetEdge that is being created.
74:      */
75:     private Object newEdge;
76: 
77:     /**
78:      * The constructor.
79:      *
80:      */
81:     public ModeCreateMessage() {
82:         super();
83:     }
84: 
85:     /**
86:      * The constructor.
87:      *
88:      * @param par the editor
89:      */
90:     public ModeCreateMessage(Editor par) {
91:         super(par);
92:     }
93: 
94:     /**
95:      * @see org.tigris.gef.base.ModeCreate#createNewItem(
96:      * java.awt.event.MouseEvent, int, int)
97:      */
98:     public Fig createNewItem(MouseEvent me, int snapX, int snapY) {
99:         return new FigLine(
100:             snapX,
101:             snapY,
102:             me.getX(),
103:             snapY,
104:             Globals.getPrefs().getRubberbandColor());
105:     }
106: 
107:     /**
108:      * @see org.tigris.gef.base.FigModifyingMode#instructions()
109:      */
110:     public String instructions() {
111:         return Translator.localize("action.sequence.new."
112: 				   + getArg("actionName"));
113:     }
114: 
115:     /**
116:      * On mousePressed determine what port the user is dragging from.
117:      * The mousePressed event is sent via ModeSelect.
118:      *
119:      * @see java.awt.event.MouseListener#mousePressed(java.awt.event.MouseEvent)
120:      */
121:     public void mousePressed(MouseEvent me) {
122:         if (me.isConsumed()) {
123:             return;
124: 	}
125:         int x = me.getX(), y = me.getY();
126:         Editor ce = Globals.curEditor();
127:         Fig underMouse = ce.hit(x, y);
128:         if (underMouse == null) {
129:             underMouse = ce.hit(x - 16, y - 16, 32, 32);
130:         }
131:         if (underMouse == null) {
132:             done();
133:             me.consume();
134:             return;
135:         }
136:         if (!(underMouse instanceof FigNode)) {
137:             done();
138:             me.consume();
139:             return;
140:         }
141:         sourceFigClassifierRole = (FigNode) underMouse;
142:         startPort = sourceFigClassifierRole.deepHitPort(x, y);
143:         if (startPort == null) {
144:             done();
145:             me.consume();
146:             return;
147:         }
148:         startPortFig = sourceFigClassifierRole.getPortFig(startPort);
149:         start();
150:         Point snapPt = new Point();
151:         synchronized (snapPt) {
152:             snapPt.setLocation(
153:                 startPortFig.getX() + FigClassifierRole.WIDTH / 2,
154:                 startPortFig.getY());
155:             editor.snap(snapPt);
156:             anchorX = snapPt.x;
157:             anchorY = snapPt.y;
158:         }
159:         _newItem = createNewItem(me, anchorX, anchorY);
160:         me.consume();
161:         setCursor(Cursor.getPredefinedCursor(Cursor.CROSSHAIR_CURSOR));
162:     }
163: 
164:     /**
165:      * On mouseReleased, find the port in the destination node that's
166:      * on the same height as the source port fig, ask the GraphModel
167:      * to connect the two ports.  If that connection is allowed, then
168:      * construct a new FigEdge and add it to the Layer and send it to
169:      * the back.
170:      *
171:      * @see java.awt.event.MouseListener#mouseReleased(java.awt.event.MouseEvent)
172:      */
173:     public void mouseReleased(MouseEvent me) {
174:         if (me.isConsumed()) {
175:             return;
176: 	}
177:         if (sourceFigClassifierRole == null) {
178:             done();
179:             me.consume();
180:             return;
181:         }
182: 
183:         int x = me.getX(), y = me.getY();
184:         Class arcClass;
185:         Editor ce = Globals.curEditor();
186:         Fig f = ce.hit(x, y);
187:         if (f == null) {
188:             f = ce.hit(x - 16, y - 16, 32, 32);
189:         }
190:         GraphModel gm = ce.getGraphModel();
191:         if (!(gm instanceof MutableGraphModel)) {
192:             f = null;
193: 	}
194:         MutableGraphModel mgm = (MutableGraphModel) gm;
195:         if (f instanceof FigNode) {
196:             FigNode destFigNode = (FigNode) f;
197:             // If its a FigNode, then check within the
198:             // FigNode to see if a port exists
199:             Object foundPort = null;
200:             if (destFigNode != sourceFigClassifierRole) {
201:                 y = startPortFig.getY();
202:                 foundPort = destFigNode.deepHitPort(x, y);
203:             } else {
204:                 foundPort = destFigNode.deepHitPort(x, y);
205:             }
206: 
207:             if (foundPort != null && foundPort != startPort) {
208:                 Fig destPortFig = destFigNode.getPortFig(foundPort);
209:                 Object edgeType = getArg("edgeClass");
210:                 if (edgeType != null) {
211:                     newEdge =
212:                         mgm.connect(startPort, foundPort, edgeType);
213:                 } else {
214:                     newEdge = mgm.connect(startPort, foundPort);
215:                 }
216: 
217:                 // Calling connect() will add the edge to the GraphModel and
218:                 // any LayerPersectives on that GraphModel will get a
219:                 // edgeAdded event and will add an appropriate FigEdge
220:                 // (determined by the GraphEdgeRenderer).
221: 
222:                 if (null != newEdge) {
223:                     LayerManager lm = ce.getLayerManager();
224:                     ce.damaged(_newItem);
225:                     sourceFigClassifierRole.damage();
226:                     destFigNode.damage();
227:                     _newItem = null;
228:                     FigMessage fe =
229:                         (FigMessage) ce.getLayerManager()
230:                             .getActiveLayer().presentationFor(newEdge);
231:                     fe.setSourcePortFig(startPortFig);
232:                     fe.setSourceFigNode(sourceFigClassifierRole);
233:                     fe.setDestPortFig(destPortFig);
234:                     fe.setDestFigNode(destFigNode);
235: 				// set the new edge in place
236:                     if (sourceFigClassifierRole != null) {
237:                         sourceFigClassifierRole.updateEdges();
238: 		    }
239:                     if (destFigNode != null) {
240:                         destFigNode.updateEdges();
241: 		    }
242:                     if (fe != null) {
243:                         ce.getSelectionManager().select(fe);
244: 		    }
245:                     done();
246:                     me.consume();
247:                     return;
248:                 } else {
249:                     LOG.debug("connection return null");
250: 		}
251:             }
252:         }
253:         sourceFigClassifierRole.damage();
254:         ce.damaged(_newItem);
255:         _newItem = null;
256:         done();
257:         me.consume();
258:     }
259: 
260:     /**
261:      * @see java.awt.event.MouseMotionListener#mouseDragged(java.awt.event.MouseEvent)
262:      */
263:     public void mouseDragged(MouseEvent me) {
264:         if (me.isConsumed()) {
265:             return;
266: 	}
267:         if (_newItem != null) {
268:             editor.damaged(_newItem);
269:             creationDrag(me.getX(), startPortFig.getY());
270:             editor.damaged(_newItem);
271:         }
272:         editor.scrollToShow(me.getX(), startPortFig.getY());
273:         me.consume();
274:     }
275: } /* end class ModeCreateEdge */
