217:                 // Calling connect() will add the edge to the GraphModel and
218:                 // any LayerPersectives on that GraphModel will get a
219:                 // edgeAdded event and will add an appropriate FigEdge
220:                 // (determined by the GraphEdgeRenderer).
221: 
222:                 if (null != newEdge) {
223:                     LayerManager lm = ce.getLayerManager();
224:                     ce.damaged(_newItem);
225:                     sourceFigClassifierRole.damage();
226:                     destFigNode.damage();
227:                     _newItem = null;
228:                     FigMessage fe =
229:                         (FigMessage) ce.getLayerManager()
230:                             .getActiveLayer().presentationFor(newEdge);
231:                     fe.setSourcePortFig(startPortFig);
232:                     fe.setSourceFigNode(sourceFigClassifierRole);
233:                     fe.setDestPortFig(destPortFig);
234:                     fe.setDestFigNode(destFigNode);
235: 				// set the new edge in place
236:                     if (sourceFigClassifierRole != null) {
237:                         sourceFigClassifierRole.updateEdges();
238: 		    }
239:                     if (destFigNode != null) {
240:                         destFigNode.updateEdges();
241: 		    }
242:                     if (fe != null) {
243:                         ce.getSelectionManager().select(fe);
244: 		    }
245:                     done();
246:                     me.consume();
247:                     return;
248:                 } else {
249:                     LOG.debug("connection return null");
250: 		}
251:             }
252:         }
253:         sourceFigClassifierRole.damage();
254:         ce.damaged(_newItem);
255:         _newItem = null;
256:         done();
257:         me.consume();
258:     }
