24: package uci.gef;
25: 
26: import java.awt.*;
27: import java.awt.event.KeyListener;
28: import java.awt.event.KeyEvent;
29: import java.util.*;
30: import uci.ui.*;
31: 
32: /** This class handles painting and editing text Fig's in a
33:  *  LayerDiagram. Needs-More-Work: should eventually allow styled text
34:  *  editing, ... someday...
35:  *  <A HREF="../features.html#basic_shapes_text">
36:  *  <TT>FEATURE: basic_shapes_text</TT></A>
37:  */
38: 
39: public class FigText extends Fig
40: implements KeyListener {
41: 
42:   ////////////////////////////////////////////////////////////////
43:   // constants
44: 
45:   /** Constants to specify text justification. Needs-More-Work: some
46:    *  parts of the code refer to this as "justification", and that is
47:    *  confusing. */
48:   public final int JUSTIFY_LEFT = 0;
49:   public final int JUSTIFY_RIGHT = 1;
50:   public final int JUSTIFY_CENTER = 2;
51: 
52:   /** Minimum size of a FigText object. */
53:   public final int MIN_TEXT_WIDTH = 30;
54: 
55:   ////////////////////////////////////////////////////////////////
56:   // instance variables
57: 
58:   /** Font info. */
59:   protected Font _font = new Font("TimesRoman", Font.PLAIN, 10);
60:   protected FontMetrics _fm;
61:   protected int _lineHeight;
62: 
63:   /** Color of the actual text characters. */
64:   protected Color _textColor = Color.black;
65: 
66:   /** Color to be drawn behind the actual text characters. Note that
67:    *  this will be a smaller area than the bounding box which is
68:    *  filled with FillColor. */
69:   protected Color _textFillColor = Color.white;
70: 
71:   /** True if the area behind individual characters is to be filled
72:    *  with TextColor. */
73:   protected boolean _textFilled = false;
74:   protected boolean _underline = false;
75:   // needs-more-work: use insets instead
76:   protected int _lineSpacing = -4;
77:   protected int _topMargin = 1;
78:   protected int _botMargin = 1;
79:   protected int _leftMargin = 1;
80:   protected int _rightMargin = 1;
81: 
82:   /** True if the FigText can only grow in size, never shrink. */
83:   protected boolean _expandOnly = false;
84: 
85:   /** Text justification can be JUSTIFY_LEFT, JUSTIFY_RIGHT, or JUSTIFY_CENTER. */
86:   protected int _justification;
87: 
88:   /** The current string to display. */
89:   protected String _curText;
90: 
91:   ////////////////////////////////////////////////////////////////
92:   // static initializer
93:   static {
94:     PropCategoryManager.categorizeProperty("Text", "font");
95:     PropCategoryManager.categorizeProperty("Text", "underline");
96:     PropCategoryManager.categorizeProperty("Text", "expandOnly");
97:     PropCategoryManager.categorizeProperty("Text", "lineSpacing");
98:     PropCategoryManager.categorizeProperty("Text", "topMargin");
99:     PropCategoryManager.categorizeProperty("Text", "botMargin");
100:     PropCategoryManager.categorizeProperty("Text", "leftMargin");
101:     PropCategoryManager.categorizeProperty("Text", "rightMargin");
102:     PropCategoryManager.categorizeProperty("Text", "text");
103:     PropCategoryManager.categorizeProperty("Style", "alignment");
104:     PropCategoryManager.categorizeProperty("Style", "textFilled");
105:     PropCategoryManager.categorizeProperty("Style", "textFillColor");
106:     PropCategoryManager.categorizeProperty("Style", "textColor");
107:   }
108: 
109:   ////////////////////////////////////////////////////////////////
110:   // constructors
111: 
112:   /** Construct a new FigText with the given position, size, color,
113:    *  string, and font. */
114:   public FigText(int x, int y, int w, int h,
115: 		 Color textColor, String familyName, int fontSize) {
116:     super(x, y, w, h);
117:     _x = x; _y = y; _w = w; _h = h;
118:     _textColor = textColor;
119:     _font = new Font(familyName, Font.PLAIN, fontSize);
120:     _justification = JUSTIFY_CENTER;
121:     _curText = "";
122:   }
123: 
124:   /** Construct a new FigText with the given position, size, and attributes. */
125:   public FigText(int x, int y, int w, int h, Hashtable gAttrs ) {
126:     this(x, y, w, h, Color.blue, "TimesRoman", 10);
127:     //    put(gAttrs);
128:   }
129: 
130:   ////////////////////////////////////////////////////////////////
131:   // invariant
132: 
133:   public boolean OK() {
134:     if (!super.OK()) return false;
135:     return _font != null && _lineSpacing > -20 && _topMargin >= 0 &&
136:       _botMargin >= 0 && _leftMargin >= 0 && _rightMargin >= 0 &&
137:       (_justification == JUSTIFY_LEFT || _justification == JUSTIFY_CENTER ||
138:        _justification == JUSTIFY_RIGHT) && _textColor != null &&
139:       _textFillColor != null;
140:   }
141:   ////////////////////////////////////////////////////////////////
142:   // accessors
143: 
144:   /** Reply a string that indicates how the text is justified: Left,
145:    *  Center, or Right. */
146:   public String justificationByName() {
147:     // needs-more-work: index into static array?
148:     // return _AlignmentNames[_alignment];
149:     if (_justification == JUSTIFY_LEFT) return "Left";
150:     else if (_justification == JUSTIFY_CENTER) return "Center";
151:     else if (_justification == JUSTIFY_RIGHT) return "Right";
152:     System.out.println("internal error, unknown text alignment");
153:     return "Unknown";
154:   }
155: 
156:   /** Set the text justification given one of these strings: Left,
157:    *  Center, or Right. */
158:   public void justificationByName(String alignString) {
159:     if (alignString.equals("Left")) _justification = JUSTIFY_LEFT;
160:     else if (alignString.equals("Center")) _justification = JUSTIFY_CENTER;
161:     else if (alignString.equals("Right")) _justification = JUSTIFY_RIGHT;
162:     _fm = null;
163:   }
164: 
165: 
166: 
167:   ////////////////////////////////////////////////////////////////
168:   // accessors and modifiers
169: 
170:   public Color getTextColor() { return _textColor; }
171:   public void setTextColor(Color c) { _textColor = c; }
172:   public Color getTextFillColor() { return _textFillColor; }
173:   public void setTextFillColor(Color c) { _textFillColor = c; }
174:   public boolean getTextFilled() { return _textFilled; }
175:   public void setTextFilled(boolean b) { _textFilled = b; }
176:   public boolean getUnderline() { return _underline; }
177:   public void setUnderline(boolean b) { _underline = b; }
178: 
179:   public String getJustification() { return justificationByName(); }
180:   public void setJustification(String align) { justificationByName(align); }
181:   public int getLineSpacing() { return _lineSpacing; }
182:   public void setLineSpacing(int s) { _lineSpacing = s; calcBounds(); }
183: 
184:   public int getTopMargin() { return _topMargin; }
185:   public void setTopMargin(int m) { _topMargin = m; calcBounds(); }
186:   public int getBotMargin() { return _botMargin; }
187:   public void setBotMargin(int m) { _botMargin = m; calcBounds(); }
188:   public int getLeftMargin() { return _leftMargin; }
189:   public void setLeftMargin(int m) { _leftMargin = m; calcBounds(); }
190:   public int getRightMargin() { return _rightMargin; }
191:   public void setRightMargin(int m) { _rightMargin = m; calcBounds(); }
192: 
193:   public boolean getExpandOnly() { return _expandOnly; }
194:   public void setExpandOnly(boolean b) { _expandOnly = b; }
195: 
196:   public Font getFont() { return _font; }
197:   public void setFont(Font f) { _font = f; _fm = null; calcBounds(); }
198: 
199:   public boolean getItalic() { return _font.isItalic(); }
200:   public void setItalic(boolean b) {
201:     int style = (getBold() ? Font.BOLD : 0) + (b ? Font.ITALIC : 0);
202:     setFont(new Font(_font.getFamily(), _font.getSize(), style));
203:   }
204: 
205:   public boolean getBold() { return _font.isBold(); }
206:   public void setBold(boolean b) {
207:     int style = (b ? Font.BOLD : 0) + (getItalic() ? Font.ITALIC : 0);
208:     setFont(new Font(_font.getFamily(), _font.getSize(), style));
209:   }
210: 
211:   /** Remove the last char from the current string line and return the
212:    *  new string.  Called whenever the user hits the backspace key.
213:    *  Needs-More-Work: Very slow.  This will eventually be replaced by
214:    *  full text editing... if there are any volunteers to do that...*/
215:   public String deleteLastCharFromString(String string) {
216:     int string_length = Math.max(string.length() - 1, 0);
217:     char[] string_char = string.toCharArray();
218:     String new_string = new String(string_char,0,string_length);
219:     return new_string;
220:   }
221: 
222:   /** Delete the last char from the current string. Called whenever
223:    *  the user hits the backspace key */
224:   public void deleteLastChar() {
225:     _curText = deleteLastCharFromString(_curText);
226:     calcBounds();
227:   }
228: 
229:   /** Append a character to the current String .*/
230:   public void append(char c) { setText(_curText + c); }
231: 
232:   /** Append the given String to the current String. */
233:   public void append(String s) { setText(_curText + s); }
234: 
235:   /** set the current String to be the given String. */
236:   public void setText(String s) { _curText = s; calcBounds(); }
237: 
238:   /** Get the String held by this FigText. Multi-line text is
239:    *  represented by newline characters embedded in the String. */
240:   public String getText() { return _curText; }
241: 
242:   ////////////////////////////////////////////////////////////////
243:   // painting methods
244: 
245:   /** Paint the FigText. */
246:   public void paint(Graphics g) {
247:     int chunkX = _x + _leftMargin;
248:     int chunkY = _y + _topMargin;
249:     StringTokenizer lines;
250: 
251:     if (_filled) {
252:       g.setColor(_fillColor);
253:       g.fillRect(_x, _y, _w, _h);
254:     }
255:     if (_lineWidth > 0) {
256:       g.setColor(_lineColor);
257:       g.drawRect(_x - 1, _y - 1, _w + 1, _h + 1);
258:     }
259: 
260:     if (_font != null) g.setFont(_font);
261:     _fm = g.getFontMetrics(_font);
262:     int chunkH = _lineHeight + _lineSpacing;
263:     chunkY = _y + _topMargin + chunkH;
264:     if (_textFilled) {
265:       g.setColor(_textFillColor);
266:       lines = new StringTokenizer(_curText, "\n\r", true);
267:       while (lines.hasMoreTokens()) {
268: 	String curLine = lines.nextToken();
269: 	//if (curLine.equals("\r")) continue;
270: 	int chunkW = _fm.stringWidth(curLine);
271: 	switch (_justification) {
272: 	case JUSTIFY_LEFT: break;
273: 	case JUSTIFY_CENTER: chunkX = _x + (_w - chunkW) / 2; break;
274: 	case JUSTIFY_RIGHT: chunkX = _x + _w - chunkW - _rightMargin; break;
275: 	}
276: 	if (curLine.equals("\n") || curLine.equals("\r")) chunkY += chunkH;
277: 	else g.fillRect(chunkX, chunkY - chunkH, chunkW, chunkH);
278:       }
279:     }
280: 
281:     g.setColor(_textColor);
282:     chunkX = _x + _leftMargin;
