85:      * the action attached to the owner of the {@link FigMessage}.  Also
86:      * adds FigActivations etc or moves the {@link FigObject}s
87:      * if necessary.<p>
88:      *
89:      * @see org.tigris.gef.presentation.FigEdge#computeRoute()
90:      */
91:     public void computeRoute() {
92:         if (computeRouteNumbersOfTime == 0) {
93:             computeRouteNumbersOfTime++;
94:         } else if (computeRouteNumbersOfTime == 1) {
95:             Point srcPt = getSourcePortFig().center();
96:             Point dstPt = getSourcePortFig().center();
97:             Point centerPnt =
98:                 new Point(
99:                     (int) (srcPt.getX() > dstPt.getX()
100:                         ? (dstPt.getX() + (srcPt.getX() - dstPt.getX()))
101:                         : (srcPt.getX() + (dstPt.getX() - srcPt.getX()))),
102:                     (int) srcPt.getY());
103:             srcPt = getSourcePortFig().connectionPoint(centerPnt);
104:             dstPt = getDestPortFig().connectionPoint(centerPnt);
105:             setEndPoints(srcPt, dstPt);
106:             layoutEdge();
107:             computeRouteNumbersOfTime++;
108:             calcBounds();
109:         } else if (computeRouteNumbersOfTime > 1) {
110:             FigPoly p = ((FigPoly) _fig);
111: 
112:             Point srcPt = getSourcePortFig().center();
113:             Point dstPt = getDestPortFig().center();
114: 
115:             if (_useNearest) {
116:                 if (p.getNumPoints() == 2) {
117:                     //? two iterations of refinement, maybe should be a for-loop
118:                     srcPt = getSourcePortFig().connectionPoint(p.getPoint(1));
119:                     dstPt =
120:                         getDestPortFig().connectionPoint(
121:                             p.getPoint(p.getNumPoints() - 2));
122:                     srcPt = getSourcePortFig().connectionPoint(dstPt);
123:                     dstPt = getDestPortFig().connectionPoint(srcPt);
124:                 } else {
125:                     srcPt = getSourcePortFig().connectionPoint(p.getPoint(1));
126:                     dstPt =
127:                         getDestPortFig().connectionPoint(
128:                             p.getPoint(p.getNumPoints() - 2));
129:                 }
130:             }
131:             setEndPoints(srcPt, dstPt);
132:             calcBounds();
133:         }
134:     }
