139:      *
140:      * @return the message.
141:      */
142:     public Object getMessage() {
143:         Object action = getAction();
144:         if (action != null) {
145:             Collection col = Model.getFacade().getMessages(action);
146:             if (!col.isEmpty()) {
147:                 return col.iterator().next();
148:             }
149:         }
150:         return null;
