918:      *
919:      * @param node is the given node
920:      * @return the Node
921:      */
922:     public Node nextNode(Node node) {
923:         if (getIndexOf(node) < linkPositions.size())
924:             return (Node) linkPositions.get(getIndexOf(node) + 1);
925:         else
926:             return null;
927:     }
