930:      * Returns the node that's before the given node in the nodes list.
931:      *
932:      * @param node is the given node
933:      * @return the node
934:      */
935:     public Node previousNode(Node node) {
936:         if (getIndexOf(node) > 0) {
937:             return (Node) linkPositions.get(getIndexOf(node) - 1);
938:         } else
939:             return null;
940:     }
