942:     /**
943:      * Returns true if this {@link FigObject} has activations. An
944:      * activation is in this case a start ActivationNode and an end
945:      * ActivationNode in the Nodes list (_linkPositions).<p>
946:      *
947:      * @return true if this {@link FigObject} has activations.
948:      */
949:     public boolean hasActivations() {
950:         for (int i = 0; i < linkPositions.size(); i++) {
951:             Node node = (Node) linkPositions.get(i);
952:             if (node instanceof ActivationNode) {
953:                 if (getActivationNodes(node).isEmpty()) {
954:                     return false;
955:                 }
956:             }
957:         }
958:         return true;
