1027:      * @param position the position in which the node will be added
1028:      * @param node the node to be added
1029:      */
1030:     public void addNode(int position, Node node) {
1031:         linkPositions.add(position, node);
1032:         Iterator it =
1033:             linkPositions
1034:                 .subList(position + 1, linkPositions.size())
1035:                 .iterator();
1036:         while (it.hasNext()) {
1037:             Object o = it.next();
1038:             if (o instanceof LinkPort) {
1039:                 FigLinkPort figLinkPort = ((LinkPort) o).getFigLinkPort();
1040:                 if (figLinkPort != null) {
1041:                     figLinkPort.setY(
1042:                         figLinkPort.getY()
1043:                             + SequenceDiagramLayout.LINK_DISTANCE);
1044:                 }
1045:             }
1046:         }
1047:         calcBounds();
1048:     }
