540:      */
541:     public boolean canAddNode(Object node) {
542:         if (node == null) {
543:             return false;
544:         }
545:         if (getNodes().contains(node)) {
546:             return false;
547:         }
548:         return Model.getFacade().isAObject(node);
549:     }
550: 
551:     /**
552:      * Return true if the given object is a valid edge in this graph.
553:      *
554:      * @see org.tigris.gef.graph.MutableGraphModel#canAddEdge(java.lang.Object)
555:      */
556:     public boolean canAddEdge(Object edge) {
557:         if (edge == null) {
558:             return false;
559:         }
560:         Object end0 = null;
561:         Object end1 = null;
562:         if (Model.getFacade().isALink(edge)) {
563:             end0 =
564: 		Model.getCommonBehaviorHelper().getSource(/*(MLink)*/
565: 							   edge);
566:             end1 =
567: 		Model.getCommonBehaviorHelper().getDestination(/*(MLink)*/
568: 								edge);
569:         }
570:         if (end0 == null || end1 == null) {
571:             return false;
572:         }
573:         if (!getNodes().contains(end0)) {
574:             return false;
575:         }
576:         if (!getNodes().contains(end1)) {
577:             return false;
578:         }
579:         if (getEdges().contains(edge)) {
580:             return false;
581:         }
582:         return true;
583: 
584:     }
585: 
586:     /**
587:      * Add the given node to the graph, if valid.
588:      *
589:      * @see org.tigris.gef.graph.MutableGraphModel#addNode(java.lang.Object)
590:      */
591:     public void addNode(Object node) {
592:         if (canAddNode(node)) {
593:             Object clasrole =
594:                 Model.getCollaborationsFactory().buildClassifierRole(
595:                                 getHomeModel());
596:             Model.getCollaborationsHelper().addInstance(clasrole, node);
597:             fireNodeAdded(node);
598:         }
599: 
600:     }
