614:     /**
615:      * @see org.tigris.gef.graph.MutableGraphModel#addNodeRelatedEdges(java.lang.Object)
616:      */
617:     public void addNodeRelatedEdges(Object node) {
618:         super.addNodeRelatedEdges(node);
619: 
620:         if (Model.getFacade().isAInstance(node)) {
621:             Collection ends = Model.getFacade().getLinkEnds(node);
622:             Iterator iter = ends.iterator();
623:             while (iter.hasNext()) {
624:                 Object /*MLinkEnd*/ le = iter.next();
625:                 if (canAddEdge(Model.getFacade().getLink(le))) {
626:                     addEdge(Model.getFacade().getLink(le));
627:                 }
628:                 return;
629:             }
630:         }
631:     }
