37: import org.tigris.gef.base.LayerPerspectiveMutable;
38: import org.tigris.gef.graph.GraphEvent;
39: import org.tigris.gef.graph.MutableGraphModel;
40: import org.tigris.gef.presentation.Fig;
41: import org.tigris.gef.presentation.FigEdge;
42: 
43: /**
44:  * The layer on which the figs in a sequence diagram are placed. Also
45:  * responsible for distributing figs on the diagram if a fig is added
46:  * or removed.
47:  *
48:  * @author : jaap.branderhorst@xs4all.nl
49:  */
50: public class SequenceDiagramLayout extends LayerPerspectiveMutable {
51:     /**
52:      * The distance between two objects on the sequence diagram.
53:      */
54:     public static final int OBJECT_DISTANCE = 30;
55: 
56:     /**
57:      * The distance between the left side of the diagram and the first
58:      * {@link FigClassifierRole}.
59:      */
60:     public static final int DIAGRAM_LEFT_MARGE = 50;
61: 
62:     /**
63:      * The distance between the top side of the diagram and the top of
64:      * the highest {@link FigClassifierRole}
65:      */
66:     public static final int DIAGRAM_TOP_MARGE = 50;
67: 
68:     /**
69:      * The vertical distance between two links
70:      */
71:     public static final int LINK_DISTANCE = 60;
72: 
73:     /**
74:      * Linked list with all fig objects sorted by x coordinate in it
75:      */
76:     private LinkedList figObjectsX = new LinkedList();
77: 
78:     /**
79:      * The heighest height of the outer box of a figobject.
80:      */
81:     private int heighestObjectHeight = 0;
82: 
83:     /**
84:      * The constructor.
85:      *
86:      * @param name the name
87:      * @param gm the graph model
88:      */
89:     public SequenceDiagramLayout(String name, MutableGraphModel gm) {
90:         super(name, gm);
91: 
92:     }
93: 
94:     /**
95:      * @see org.tigris.gef.base.LayerPerspective#putInPosition(Fig)
96:      */
97:     public void putInPosition(Fig f) {
98:         if (f instanceof FigClassifierRole) {
99:             distributeFigObjects(f);
100:             ((FigClassifierRole) f).updateEdges();
101:         } else
102:             super.putInPosition(f);
103:     }
104: 
105:     /**
106:      * Distributes the fig objects contained in _figObjectsX over the
107:      * sequencediagram.
108:      *
109:      * @param f
110:      */
111:     private void distributeFigObjects(Fig f) {
112:         int listPosition = figObjectsX.indexOf(f);
113:         if (listPosition < 0)
114:             return;
115:         if (listPosition < figObjectsX.size() - 1) {
116:             Fig next = (Fig) figObjectsX.get(listPosition + 1);
117:             if (next.getX() < f.getX()) {
118:                 reshuffelFigObjectsX(f);
119:                 listPosition = figObjectsX.indexOf(f);
120:             }
121:         } else if (listPosition > 0) {
122:             Fig previous = (Fig) figObjectsX.get(listPosition - 1);
123:             if (previous.getX() > f.getX()) {
124:                 reshuffelFigObjectsX(f);
125:                 listPosition = figObjectsX.indexOf(f);
126:             }
127:         }
128:         Iterator it =
129:             figObjectsX.subList(listPosition, figObjectsX.size()).iterator();
130:         int positionX =
131:             listPosition == 0
132:                 ? DIAGRAM_LEFT_MARGE
133:                 : (((Fig) figObjectsX.get(listPosition - 1)).getX()
134:                     + ((Fig) figObjectsX.get(listPosition - 1)).getWidth()
135:                     + OBJECT_DISTANCE);
136:         while (it.hasNext()) {
137:             Fig fig = (Fig) it.next();
138:             if (fig.getX() == positionX) {
139:                 break;
140:             }
141:             fig.setX(positionX);
142:             ((FigClassifierRole) fig).updateEdges();
143:             positionX += (fig.getWidth() + OBJECT_DISTANCE);
144:         }
145:         if (heighestObjectHeight < f.getHeight()) {
146:             heighestObjectHeight = f.getHeight();
147:             it = figObjectsX.iterator();
148:             while (it.hasNext()) {
149:                 Fig fig = (Fig) it.next();
150:                 fig.setY(
151:                     DIAGRAM_TOP_MARGE + heighestObjectHeight - f.getHeight());
152:                 fig.damage();
153:             }
154:         } else {
155:             f.setY(DIAGRAM_TOP_MARGE + heighestObjectHeight - f.getHeight());
156:             f.damage();
157:         }
158:     }
159: 
160:     /**
161:      * @see org.tigris.gef.graph.GraphListener#nodeAdded(GraphEvent)
162:      */
163:     public void nodeAdded(GraphEvent ge) {
164:         super.nodeAdded(ge);
165:         Fig fig = presentationFor(ge.getArg());
166:         if (fig instanceof FigClassifierRole) {
167:             ((FigClassifierRole) fig).renderingChanged();
168:         }
169:     }
170: 
171:     /**
172:      * @see org.tigris.gef.base.Layer#add(org.tigris.gef.presentation.Fig)
173:      */
174:     public void add(Fig f) {
175:         super.add(f);
176:         if (f instanceof FigClassifierRole) {
177:             SortedMap x = new TreeMap();
178:             if (!figObjectsX.isEmpty()) {
179:                 Iterator it = figObjectsX.iterator();
180:                 while (it.hasNext()) {
181:                     Fig fig = (Fig) it.next();
182:                     x.put(new Integer(fig.getX()), fig);
183:                 }
184:                 Object o = x.get(x.headMap(new Integer(f.getX())).lastKey());
185:                 figObjectsX.add(figObjectsX.indexOf(o) + 1, f);
186:             } else
187:                 figObjectsX.add(f);
188:             heighestObjectHeight =
189:                 Math.max(heighestObjectHeight, f.getHeight());
190:         }
191:     }
192: 
193:     private void reshuffelFigObjectsX(Fig f) {
194:         figObjectsX.remove(f);
195:         int x = f.getX();
196:         int newPosition = 0;
197:         for (int i = 0; i < figObjectsX.size(); i++) {
198:             Fig fig = (Fig) figObjectsX.get(i);
199:             if (fig.getX() < x) {
200:                 if (i != (figObjectsX.size() - 1)
201:                     && ((Fig) figObjectsX.get(i + 1)).getX() > x) {
202:                     newPosition = i + 1;
203:                     break;
204:                 }
205:                 if (i == (figObjectsX.size() - 1)) {
206:                     newPosition = i;
207:                 }
208:             }
209:         }
210:         figObjectsX.add(newPosition, f);
211: 
212:     }
213: 
214:     /**
215:      * @see org.tigris.gef.base.Layer#deleted(org.tigris.gef.presentation.Fig)
216:      */
217:     public void deleted(Fig f) {
218:         super.deleted(f);
219:         figObjectsX.remove(f);
220:         if (f.getHeight() == heighestObjectHeight) {
221:             Iterator it = figObjectsX.iterator();
222:             while (it.hasNext()) {
223:                 heighestObjectHeight =
224:                     Math.max(
225:                         heighestObjectHeight,
226:                         ((Fig) it.next()).getHeight());
227:             }
228:         }
229:         if (!figObjectsX.isEmpty()) {
230:             putInPosition((Fig) figObjectsX.get(0));
231:         }
232:     }
233: 
234:     /**
235:      * Update Activations.
236:      * First removes all current activation boxes, then adds new ones
237:      * to all figobject depending on the state of the nodes.
238:      */
239:     public void updateActivations() {
240:         Iterator it = getContentsNoEdges().iterator();
241:         while (it.hasNext()) {
242:             Fig fig = (Fig) it.next();
243:             if (fig instanceof FigClassifierRole) {
244:                 ((FigClassifierRole) fig).updateActivations();
245:             }
246:         }
247:     }
248: 
249:     /**
250:      * Returns a list with all {@link FigLink}s that intersect with
251:      * the given y coordinate.<p>
252:      *
253:      * @param y is the given y coordinate.
254:      * @return the list with {@link FigLink}s.
255:      */
256:     public List getFigLinks(int y) {
257:         if (getContents(null).isEmpty()
258: 	    || getContentsEdgesOnly().isEmpty()) {
259:             return Collections.EMPTY_LIST;
260:         }
261:         List retList = new ArrayList();
262:         Iterator it = getContentsEdgesOnly().iterator();
263:         while (it.hasNext()) {
264:             FigEdge fig = (FigEdge) it.next();
265:             if (fig instanceof FigLink
266:                 && fig.hit(new Rectangle(fig.getX(), y, 8, 8))) {
267:                 retList.add(fig);
268:             }
269: 
270:         }
271:         return retList;
272: 
273:     }
274: 
275:     /**
276:      * @param position the position for the node
277:      * @param node the node to be added
278:      */
279:     public void addNode(int position, Node node) {
280:         Iterator it = getContentsNoEdges().iterator();
281:         while (it.hasNext()) {
282:             Object o = it.next();
283:             if (o instanceof FigClassifierRole) {
284:                 ((FigClassifierRole) o).addNode(position, node);
285:                 ((FigClassifierRole) o).updateActivations();
286:             }
287:         }
288:     }
289: 
290: }
