201:                     && ((Fig) figObjectsX.get(i + 1)).getX() > x) {
202:                     newPosition = i + 1;
203:                     break;
204:                 }
205:                 if (i == (figObjectsX.size() - 1)) {
206:                     newPosition = i;
207:                 }
208:             }
209:         }
210:         figObjectsX.add(newPosition, f);
211: 
212:     }
