216:      */
217:     public void deleted(Fig f) {
218:         super.deleted(f);
219:         figObjectsX.remove(f);
220:         if (f.getHeight() == heighestObjectHeight) {
221:             Iterator it = figObjectsX.iterator();
222:             while (it.hasNext()) {
223:                 heighestObjectHeight =
224:                     Math.max(
225:                         heighestObjectHeight,
226:                         ((Fig) it.next()).getHeight());
227:             }
228:         }
229:         if (!figObjectsX.isEmpty()) {
230:             putInPosition((Fig) figObjectsX.get(0));
231:         }
232:     }
