235:      * Update Activations.
236:      * First removes all current activation boxes, then adds new ones
237:      * to all figobject depending on the state of the nodes.
238:      */
239:     public void updateActivations() {
240:         Iterator it = getContentsNoEdges().iterator();
241:         while (it.hasNext()) {
242:             Fig fig = (Fig) it.next();
243:             if (fig instanceof FigClassifierRole) {
244:                 ((FigClassifierRole) fig).updateActivations();
245:             }
246:         }
247:     }
