249:     /**
250:      * Returns a list with all {@link FigLink}s that intersect with
251:      * the given y coordinate.<p>
252:      *
253:      * @param y is the given y coordinate.
254:      * @return the list with {@link FigLink}s.
255:      */
256:     public List getFigLinks(int y) {
257:         if (getContents(null).isEmpty()
258: 	    || getContentsEdgesOnly().isEmpty()) {
259:             return Collections.EMPTY_LIST;
260:         }
261:         List retList = new ArrayList();
262:         Iterator it = getContentsEdgesOnly().iterator();
263:         while (it.hasNext()) {
264:             FigEdge fig = (FigEdge) it.next();
265:             if (fig instanceof FigLink
266:                 && fig.hit(new Rectangle(fig.getX(), y, 8, 8))) {
267:                 retList.add(fig);
268:             }
269: 
270:         }
271:         return retList;
272: 
273:     }
