277:      * @param node the node to be added
278:      */
279:     public void addNode(int position, Node node) {
280:         Iterator it = getContentsNoEdges().iterator();
281:         while (it.hasNext()) {
282:             Object o = it.next();
283:             if (o instanceof FigClassifierRole) {
284:                 ((FigClassifierRole) o).addNode(position, node);
285:                 ((FigClassifierRole) o).updateActivations();
286:             }
287:         }
288:     }
