313:             if (!(this.getDestPort() instanceof LinkPort)
314:                 || !(getSrcPort() instanceof LinkPort)) {
315:                 return false;
316:             }
317: 	    if (getDestFigObject().getActivationNodes(
318: 		    (Node) this.getDestPort()).isEmpty()) {
