633:     /**
634:      * Return true if the two given ports can be connected by a
635:      * kind of edge to be determined by the ports.
636:      *
637:      * @see org.tigris.gef.graph.MutableGraphModel#canConnect(
638:      * java.lang.Object, java.lang.Object)
639:      */
640:     public boolean canConnect(Object fromP, Object toP) {
641:         Editor curEditor = Globals.curEditor();
642:         ModeManager modeManager = curEditor.getModeManager();
643:         Mode mode = (Mode) modeManager.top();
644:         Hashtable args = mode.getArgs();
645:         Object actionType = args.get("action");
646:         CanConnectCmd cmd = null;
647:         if (Model.getMetaTypes().getCallAction().equals(actionType)) {
648:             cmd = new CanConnectCallActionCmd(fromP, toP);
649:         } else if (Model.getMetaTypes().getReturnAction().equals(actionType)) {
650:             cmd = new CanConnectReturnActionCmd(fromP, toP);
651:         } else if (Model.getMetaTypes().getCreateAction().equals(actionType)) {
652:             cmd = new CanConnectCreateActionCmd(fromP, toP);
653:         } else if (Model.getMetaTypes().getDestroyAction().equals(actionType)) {
654:             cmd = new CanConnectDestroyActionCmd(fromP, toP);
655:         } else {
656:             // not supported action
657:             return false;
658:         }
659:         return cmd.doit();
660:     }
