234:             if (this.getDestPort() instanceof ActivationNode
235: 		&& !(getDestFigObject().getActivationNodes(
236: 			 (Node) this.getDestPort()).isEmpty())) {
237:                 // cannot connect a callaction to a destactivation
238:                 // that already exists
