241:            //  if (getSrcFigObject().getPreviousActivation((Node)getSrcPort()).)
242:             if (getSrcPort() instanceof LinkNode
243: 		&& ((LinkNode) getSrcPort()).isDestroyed()) {
244:                 // cannot connect a callaction to a sourceActivation
245:                 // that is allready destroyed.
246:                 return false;
247:             }
248:             if (getSrcPort() instanceof LinkNode) {
249:             	int index =
250: 		    getSrcFigObject().getIndexOf((LinkNode) getSrcPort());
251:             	Iterator it =
252: 		    getSrcFigObject().getActivationNodes(
253: 		        (Node) getSrcPort()).iterator();
254:             	while (it.hasNext()) {
255: 		    Node node = (Node) it.next();
256: 		    if (node instanceof LinkPort
257: 			&& (getSrcFigObject().getFigLink(
258: 				((LinkPort) node).getFigLinkPort())
259: 			    instanceof FigReturnActionLink)
260: 			&& index > getSrcFigObject().getIndexOf(node)) {
261: 
262: 			// cannot connect a callaction to a
263: 			// sourceActivation that is allready returned.
264: 			return false;
265: 
266: 		    }
267:             	}
268:             }
