303:     private class CanConnectReturnActionCmd extends CanConnectCmd {
304: 
305:         public CanConnectReturnActionCmd(Object fromPort, Object toPort) {
306:             super(fromPort, toPort);
307:         }
308: 
309:         /**
310:          * @see SequenceDiagramGraphModel.CanConnectCmd#doit()
311:          */
312:         public boolean doit() {
313:             if (!(this.getDestPort() instanceof LinkPort)
314:                 || !(getSrcPort() instanceof LinkPort)) {
315:                 return false;
316:             }
317: 	    if (getDestFigObject().getActivationNodes(
318: 		    (Node) this.getDestPort()).isEmpty()) {
319: 		// there must be a destination activation.
320: 		return false;
321: 	    }
322: 	    if (this.getSrcPort() instanceof ActivationNode
323: 		&& !((ActivationNode) this.getSrcPort()).isEnd()) {
324: 
325: 		// cannot return in the middle of an activation.
326: 		return false;
327: 	    }
328: 	    Node startNode =
329: 		(Node) getSrcFigObject().getActivationNodes(
330: 		    (Node) getSrcPort()).get(0);
331: 	    if (startNode instanceof LinkPort) {
332: 		LinkPort linkNode = (LinkPort) startNode;
333: 		FigLink figLink =
334: 		    getSrcFigObject().getFigLink(linkNode.getFigLinkPort());
335: 
336: 		if (!(getDestFigObject().getActivationNodes(
337: 			  (Node) ((FigLinkPort) figLink.getSourcePortFig())
338: 			             .getOwner())
339: 		      .contains(this.getDestPort()))) {
340: 		    // cannot let a activation return to an activation
341: 		    // that did not start the source activation
342: 		    return false;
343: 		}
344: 	    } else {
345: 		return false;
346: 	    }
347:             return true;
348: 
349:         }
350:     }
