662:     /**
663:      * Creates a link based on the given from and toPort. The fromPort
664:      * should allways point to a LinkCoordinates instance. The toPort
665:      * can point to a LinkCoordinates instance or to a Object
666:      * instance. On a sequence diagram you can only draw Links. So
667:      * other edgeClasses then links are not supported.
668:      *
669:      * @see org.tigris.gef.graph.MutableGraphModel#connect(
670:      *          Object, Object, Class)
671:      */
672:     public Object connect(Object fromPort, Object toPort, Class edgeType) {
673:         if (!canConnect(fromPort, toPort)) {
674:             return null;
675:         }
676:         Object edge = null;
677:         Object fromObject = null;
678:         Object toObject = null;
679:         Object action = null;
680:         if (Model.getMetaTypes().getLink().equals(edgeType)) {
681:             Editor curEditor = Globals.curEditor();
682:             ModeManager modeManager = curEditor.getModeManager();
683:             Mode mode = modeManager.top();
684:             Hashtable args = mode.getArgs();
685:             Object actionType = args.get("action");
686:             if (Model.getMetaTypes().getCallAction().equals(actionType)) {
687:                 if (fromPort instanceof LinkPort
688:                     && toPort instanceof LinkPort) {
689:                     fromObject = ((LinkPort) fromPort).getObject();
690:                     toObject = ((LinkPort) toPort).getObject();
691: 
692:                     action =
693:                         Model.getCommonBehaviorFactory()
694:                             .createCallAction();
695:                 }
696:             } else if (Model.getMetaTypes().getCreateAction()
697:                     .equals(actionType)) {
698:                 if (fromPort instanceof LinkPort
699:                     && Model.getFacade().isAObject(toPort)) {
700:                     fromObject = ((LinkPort) fromPort).getObject();
701:                     toObject = toPort;
702:                     action =
703:                         Model.getCommonBehaviorFactory()
704:                             .createCreateAction();
705:                 }
706:             } else if (Model.getMetaTypes().getReturnAction()
707:                     .equals(actionType)) {
708:                 if (fromPort instanceof LinkPort
709:                     && toPort instanceof LinkPort) {
710:                     fromObject = ((LinkPort) fromPort).getObject();
711:                     toObject = ((LinkPort) fromPort).getObject();
712:                     action =
713:                         Model.getCommonBehaviorFactory()
714:                             .createReturnAction();
715: 
716:                 }
717:             } else if (Model.getMetaTypes().getDestroyAction()
718:                     .equals(actionType)) {
719:                 if (fromPort instanceof LinkPort
720:                     && toPort instanceof LinkPort) {
721:                     fromObject = ((LinkPort) fromPort).getObject();
722:                     toObject = ((LinkPort) fromPort).getObject();
723:                     action =
724:                         Model.getCommonBehaviorFactory()
725:                             .createDestroyAction();
726:                 }
727:             } else if (Model.getMetaTypes().getSendAction()
728:                     .equals(actionType)) {
729:                 ;// no implementation, not of importance to sequence diagrams
730:             } else if (Model.getMetaTypes().getTerminateAction()
731:                     .equals(actionType)) {
732:                 ;// not implemented yet
733:             }
734:         }
735:         if (fromObject != null && toObject != null && action != null) {
736:             Object link =
737:                 Model.getCommonBehaviorFactory().buildLink(
738:                     fromObject,
739:                     toObject);
740:             Object classifierRoleFrom =
741:                 Model.getFacade().getClassifiers(fromObject).iterator().next();
742:             Object classifierRoleTo =
743:                 Model.getFacade().getClassifiers(toObject).iterator().next();
744:             Object associationRole =
745:                 Model.getCollaborationsHelper().getAssocationRole(
746:                     classifierRoleFrom,
747:                     classifierRoleTo);
748:             if (associationRole == null) {
749:                 associationRole =
750:                     Model.getCollaborationsFactory().buildAssociationRole(
751:                         link);
752:             }
753:             Object stimulus = null;
754:             if (Model.getFacade().getStimuli(link) == null
755:                 || Model.getFacade().getStimuli(link).isEmpty()) {
756:                 stimulus =
757:                     Model.getCommonBehaviorFactory().buildStimulus(link);
758:             } else {
759:                 // we need to find the right stimulus
760:                 Iterator it = Model.getFacade().getStimuli(link).iterator();
761:                 while (it.hasNext()) {
762:                     Object o = it.next();
763:                     if (Model.getFacade().getSender(o) != null
764:                         && Model.getFacade().getSender(o).equals(fromObject)
765:                         && Model.getFacade().getReceiver(o) != null
766:                         && Model.getFacade().getReceiver(o).equals(toObject)) {
767:                         stimulus = o;
768:                         break;
769:                     }
770:                 }
771:                 if (stimulus == null) {
772:                     stimulus =
773:                         Model.getCommonBehaviorFactory().buildStimulus(link);
774:                 }
775:             }
776:             Model.getCommonBehaviorHelper().setDispatchAction(stimulus, action);
777: 
778:             Object message =
779:                 Model.getCollaborationsFactory().buildMessage(
780:                     getInteraction(),
781:                     associationRole);
782:             Model.getCollaborationsHelper().setAction(message, action);
783:             Model.getCollaborationsHelper()
784:                 .setSender(message, classifierRoleFrom);
785:             Model.getCommonBehaviorHelper()
786:                 .setReceiver(message, classifierRoleTo);
787:             addEdge(link);
788:             edge = link;
789:         }
790:         if (edge == null) {
791:             LOG.debug("Incorrect edge");
792:         }
793:         return edge;
794: 
795:     }
