796:     /**
797:      * Returns a list with all nodes that belong to the same
798:      * activation as the given node.<p>
799:      *
800:      * TODO: Does not work for EmptyNode atm.
801:      *
802:      * @param node is the given node
803:      * @return a List
804:      */
805:     public List getActivationNodes(Node node) {
806:         int start = -1;
807:         int end = -1;
808:         if (node instanceof ActivationNode) {
809:             ActivationNode activationNode = (ActivationNode) node;
810:             if (activationNode.isStart()) {
811:                 start = linkPositions.indexOf(activationNode);
812:                 ListIterator it =
813:                     linkPositions
814:                         .subList(
815:                             linkPositions.indexOf(activationNode),
816:                             linkPositions.size())
817:                         .listIterator();
818:                 while (it.hasNext()) {
819:                     Node node2 = (Node) it.next();
820:                     if (node2 instanceof ActivationNode
821:                         && ((ActivationNode) node2).isEnd()) {
822:                         end = linkPositions.indexOf(node2);
823:                         break;
824:                     }
825:                 }
826:             } else if (activationNode.isEnd()) {
827:                 end = linkPositions.indexOf(activationNode);
828:                 for (int i = end - 1; i >= 1; i--) {
829:                     Node node2 = (Node) linkPositions.get(i);
830:                     if (node2 instanceof ActivationNode
831:                         && ((ActivationNode) node2).isStart()) {
832:                         start = linkPositions.indexOf(node2);
833:                         break;
834:                     }
835:                 }
836:             } else {
837:                 // node is in between activations or does not belong
838:                 // to activation (yet)
839:                 if (!(nextNode(activationNode) instanceof ActivationNode)
840:                     || !(previousNode(activationNode)
841:                         instanceof ActivationNode)) {
842:                     return new ArrayList();
843:                 }
844:                 for (int i = getIndexOf(activationNode) + 1;
845:                     i < linkPositions.size();
846:                     i++) {
847:                     Node node2 = (Node) linkPositions.get(i);
848:                     if (node2 instanceof ActivationNode
849:                         && ((ActivationNode) node2).isEnd()) {
850:                         end = getIndexOf(node2);
851:                         break;
852:                     }
853:                 }
854:                 for (int i = getIndexOf(activationNode) - 1; i >= 0; i--) {
855:                     Node node2 = (Node) linkPositions.get(i);
856:                     if (node2 instanceof ActivationNode
857:                         && ((ActivationNode) node2).isStart()) {
858:                         start = getIndexOf(node2);
859:                         break;
860:                     }
861:                 }
862: 
863:             }
864:             if (end == -1 || start == -1) {
865:                 return new ArrayList();
866:             }
867:             return linkPositions.subList(start, end);
868: 
869:         }
870:         return new ArrayList();
871:     }
