973:      *
974:      * @param index the given index
975:      * @param node the given node
976:      */
977:     public void setNode(int index, Node node) {
978:         linkPositions.set(index, node);
979:     }
980: 
981:     /**
982:      * Returns the ObjectNode. This is the port that represents the
983:      * object Figrect.
984:      *
985:      * @return the ObjectNode.
986:      */
987:     public ObjectNode getObjectNode() {
988:         for (int i = 0; i < linkPositions.size(); i++) {
989:             if (linkPositions.get(i) instanceof ObjectNode) {
990:                 return (ObjectNode) linkPositions.get(i);
991:             }
992:         }
993:         return null;
994:     }
