996:     /**
997:      * Removes the fig from both the figs list as from the
998:      * _figActivations list and the _figLinkPorts. This assures us
999:      * that removal will indeed remove all 'pointers' to the object.<p>
1000:      *
1001:      * @see org.tigris.gef.presentation.FigGroup#removeFig(Fig)
1002:      */
1003:     public void removeFig(Fig f) {
1004:         super.removeFig(f);
1005:         figActivations.remove(f);
1006:         figFigLinkPorts.remove(f);
1007:     }
1008: 
1009:     /**
1010:      * Returns a list with the start, end and all nodes in between
1011:      * them of the activation that is prior to the given node. If the
1012:      * node is part of an activation, that activation is returned. If
1013:      * the node is null an empty list is returned.
1014:      *
1015:      * @param node is the given node
1016:      * @return a List
1017:      */
1018:     public List getPreviousActivation(Node node) {
1019:         List retList = getActivationNodes(node);
1020:         if (retList.isEmpty()) {
1021:             retList = getPreviousActivation(previousNode(node));
1022:         }
1023:         return retList;
1024:     }
