72:     private static final Logger LOG = Logger.getLogger(FigEdgeNote.class);
73: 
74:     private CommentEdge owner;
75:     
76:     private Object comment;
77:     private Object annotatedElement;
78: 
79:     /**
80:      * Construct a new note connection. Use the same layout as for
81:      * other edges.
82:      */
83:     public FigEdgeNote() {
84:         super();
85:         LOG.info("Constructing a FigEdgeNote");
86:         setBetweenNearestPoints(true);
87:         getFig().setDashed(true);
88:         allowRemoveFromDiagram(false);
89:     }
90: 
91:     /**
92:      * Constructor that hooks the Fig to a CommentEdge.
93:      *
94:      * @param commentEdge the CommentEdge
95:      * @param theLayer the layer (ignored)
96:      */
97:     public FigEdgeNote(Object commentEdge, Layer theLayer) {
98:         this();
99: 
100:         if (!(theLayer instanceof LayerPerspectiveMutable)) {
101:             throw new IllegalArgumentException(
102:                     "The layer must be a mutable perspective. Got "
103:                     + theLayer);
104:         }
105: 
106:         if (!(commentEdge instanceof CommentEdge)) {
107:             throw new IllegalArgumentException(
108:                     "The owner must be a CommentEdge. Got " + commentEdge);
109:         }
110: 
111:         Object fromNode = ((CommentEdge) commentEdge).getSource();
112:         if (!(Model.getFacade().isAModelElement(fromNode))) {
113:             throw new IllegalArgumentException(
114:                     "The given comment edge must start at a model element. "
115:                     + "Got " + fromNode);
116:         }
117: 
118:         Object toNode = ((CommentEdge) commentEdge).getDestination();
119:         if (!(Model.getFacade().isAModelElement(toNode))) {
120:             throw new IllegalArgumentException(
121:                     "The given comment edge must end at a model element. Got "
122:                     + toNode);
123:         }
124: 
125:         Fig destFig = theLayer.presentationFor(toNode);
126:         if (destFig instanceof FigEdgeModelElement) {
127:             destFig = ((FigEdgeModelElement) destFig).getEdgePort();
128:         }
129:         if (!(destFig instanceof FigNodeModelElement)) {
130:             throw new IllegalArgumentException(
131:                     "The given comment edge must end at a model element"
132:                     + " in the given layer.");
133:         }
134: 
135:         Fig sourceFig = theLayer.presentationFor(fromNode);
136:         if (sourceFig instanceof FigEdgeModelElement) {
137:             sourceFig = ((FigEdgeModelElement) sourceFig).getEdgePort();
138:         }
139:         if (!(sourceFig instanceof FigNodeModelElement)) {
140:             throw new IllegalArgumentException(
141:                     "The given comment edge must start at a model element "
142:                     + "in the given layer.");
143:         }
144: 
145:         setLayer(theLayer);
146:         setDestFigNode((FigNode) destFig);
147:         setDestPortFig(destFig);
148:         setSourceFigNode((FigNode) sourceFig);
149:         setSourcePortFig(sourceFig);
150:         computeRoute();
151: 
152:         setOwner(commentEdge);
153:     }
