336:     /**
337:      * distance formula: (x-h)^2 + (y-k)^2 = distance^2
338:      *
339:      * @param p1 point
340:      * @param p2 point
341:      * @return the square of the distance
342:      */
343:     public int getSquaredDistance(Point p1, Point p2) {
344:         int xSquared = p2.x - p1.x;
345:         xSquared *= xSquared;
346:         int ySquared = p2.y - p1.y;
347:         ySquared *= ySquared;
348:         return xSquared + ySquared;
349:     }
