406:      * The user clicked on the clarifier.
407:      *
408:      * @param x the x of the point clicked
409:      * @param y the y of the point clicked
410:      * @return the todo item clicked
411:      */
412:     public ToDoItem hitClarifier(int x, int y) {
413:         int iconPos = 25, xOff = -4, yOff = -4;
414:         Point p = new Point();
415:         ToDoList list = Designer.theDesigner().getToDoList();
416:         Vector items = list.elementsForOffender(getOwner());
417:         int size = items.size();
418:         for (int i = 0; i < size; i++) {
419:             ToDoItem item = (ToDoItem) items.elementAt(i);
420:             Icon icon = item.getClarifier();
421:             stuffPointAlongPerimeter(iconPos, p);
422:             int width = icon.getIconWidth();
423:             int height = icon.getIconHeight();
424:             if (y >= p.y + yOff
425:                 && y <= p.y + height + yOff
426:                 && x >= p.x + xOff
427:                 && x <= p.x + width + xOff)
428:                 return item;
429:             iconPos += width;
430:         }
431:         for (int i = 0; i < size; i++) {
432:             ToDoItem item = (ToDoItem) items.elementAt(i);
433:             Icon icon = item.getClarifier();
434:             if (icon instanceof Clarifier) {
435:                 ((Clarifier) icon).setFig(this);
436:                 ((Clarifier) icon).setToDoItem(item);
437:                 if (((Clarifier) icon).hit(x, y))
438:                     return item;
439:             }
440:         }
441:         items = list.elementsForOffender(this);
442:         size = items.size();
443:         for (int i = 0; i < size; i++) {
444:             ToDoItem item = (ToDoItem) items.elementAt(i);
445:             Icon icon = item.getClarifier();
446:             stuffPointAlongPerimeter(iconPos, p);
447:             int width = icon.getIconWidth();
448:             int height = icon.getIconHeight();
449:             if (y >= p.y + yOff
450:                 && y <= p.y + height + yOff
451:                 && x >= p.x + xOff
452:                 && x <= p.x + width + xOff)
453:                 return item;
454:             iconPos += width;
455:         }
456:         for (int i = 0; i < size; i++) {
457:             ToDoItem item = (ToDoItem) items.elementAt(i);
458:             Icon icon = item.getClarifier();
459:             if (icon instanceof Clarifier) {
460:                 ((Clarifier) icon).setFig(this);
461:                 ((Clarifier) icon).setToDoItem(item);
462:                 if (((Clarifier) icon).hit(x, y))
463:                     return item;
464:             }
465:         }
466:         return null;
467:     }
