530:     /**
531:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
532:      */
533:     public void propertyChange(PropertyChangeEvent pve) {
534:         Object src = pve.getSource();
535:         String pName = pve.getPropertyName();
536:         if (pve instanceof DeleteInstanceEvent && src == getOwner()) {
537:             removeFromDiagramImpl();
538:             return;
539:         }
540:         // We handle and consume editing events
541:         if (pName.equals("editing")
542:                 && Boolean.FALSE.equals(pve.getNewValue())) {
543:             LOG.debug("finished editing");
544:             // parse the text that was edited
545:             textEdited((FigText) src);
546:             calcBounds();
547:             endTrans();
548:         } else if (pName.equals("editing")
549:                 && Boolean.TRUE.equals(pve.getNewValue())) {
550:             textEditStarted((FigText) src);
551:         } else {
552:             // Add/remove name change listeners for applied stereotypes
553:             if (src == getOwner()
554:                     && "stereotype".equals(pName)) {
555:                 if (pve instanceof RemoveAssociationEvent) {
556:                     removeElementListener(pve.getOldValue());
557:                 } else if (pve instanceof AddAssociationEvent) {
558:                     addElementListener(pve.getNewValue(), "name");
559:                 }
560:             }
561:             // Pass everything except editing events to superclass
562:             super.propertyChange(pve);
563:         }
564: 
565:         if (Model.getFacade().isAModelElement(src) 
566:                 && getOwner() != null
567:                 && !Model.getUmlFactory().isRemoved(getOwner())) {
568:             /* If the source of the event is an UML object,
569:              * then the UML model has been changed.*/
570:             modelChanged(pve);
571:         }
572:         damage();  // TODO: (MVW) Is this required?
573:         // After all these events? I doubt it...
574:     }
