778:     /**
779:      * In ArgoUML, for every Fig, this setOwner() function
780:      * may only be called twice: Once after the fig is created, 
781:      * with a non-null argument, and once at end-of-life of the Fig,
782:      * with a null argument. It is not allowed in ArgoUML to change 
783:      * the owner of a fig in any other way. <p>
784:      * 
785:      * Hence, during the lifetime of this Fig object, 
786:      * the owner shall go from null to some UML object, and to null again.
787:      * 
788:      * @see org.tigris.gef.presentation.Fig#setOwner(java.lang.Object)
789:      */
790:     public void setOwner(Object newOwner) {
791:         if (newOwner != null && !Model.getFacade().isAModelElement(newOwner)) {
792:             throw new IllegalArgumentException(
793:                     "The owner must be a model element - got a "
794:                     + newOwner.getClass().getName());
795:         }
796:         updateListeners(newOwner);
797:         super.setOwner(newOwner);
798:         initNotationProviders(newOwner);
799:         if (newOwner != null) {
800:             renderingChanged();
801:         }
802:     }
