940:     /**
941:      * @see org.tigris.gef.presentation.Fig#removeFromDiagram()
942:      */
943:     public void removeFromDiagramImpl() {
944:         Object o = getOwner();
945:         if (o != null) {
946:             removeElementListener(o);
947:         }
948:         ArgoEventPump.removeListener(this);
949: 
950:         Iterator it = getPathItemFigs().iterator();
951:         while (it.hasNext()) {
952:             Fig fig = (Fig) it.next();
953:             fig.removeFromDiagram();
954:         }
955: 
956:         /* TODO: MVW: Why the next action?
957:          * Deleting a fig from 1 diagram should not influence others!
958:          * */
959:         // GEF does not take into account the multiple diagrams we have
960:         // therefore we loop through our diagrams and delete each and every
961:         // occurence on our own
962:         it =
963: 	    ProjectManager.getManager().getCurrentProject()
