990:      * helper method (layoutThisToSelf) to avoid this edge
991:      * disappearing if the new source and dest are the same node.
992:      *
993:      * @return boolean whether or not the update was sucessful
994:      */
995:     protected boolean updateClassifiers() {
996:         Object owner = getOwner();
997:         if (owner == null || getLayer() == null) {
998:             return false;
999:         }
1000: 
1001:         Object newSource = getSource();
1002:         Object newDest = getDestination();
1003: 
1004:         Fig currentSourceFig = getSourceFigNode();
1005:         Fig currentDestFig = getDestFigNode();
1006:         Object currentSource = null;
1007:         Object currentDestination = null;
1008:         if (currentSourceFig != null && currentDestFig != null) {
1009:             currentSource = currentSourceFig.getOwner();
1010:             currentDestination = currentDestFig.getOwner();
1011:         }
1012:         if (newSource != currentSource || newDest != currentDestination) {
1013:             Fig newSourceFig = null;
1014:             if (newSource != null)
1015:                 newSourceFig = getLayer().presentationFor(newSource);
1016:             Fig newDestFig = null;
1017:             if (newDest != null)
1018:                 newDestFig = getLayer().presentationFor(newDest);
1019:             if (newSourceFig == null || newDestFig == null) {
1020:                 removeFromDiagramImpl();
1021:                 return false;
1022:             }
1023:             if (newSourceFig != null && newSourceFig != currentSourceFig) {
1024:                 setSourceFigNode((FigNode) newSourceFig);
1025:                 setSourcePortFig(newSourceFig);
1026: 
1027:             }
1028:             if (newDestFig != null && newDestFig != currentDestFig) {
1029:                 setDestFigNode((FigNode) newDestFig);
1030:                 setDestPortFig(newDestFig);
1031:             }
1032:             if (newDestFig != null && newSourceFig != null) {
1033:                 ((FigNode) newSourceFig).updateEdges();
1034:             }
1035:             if (newSourceFig != null && newDestFig != null) {
1036:                 ((FigNode) newDestFig).updateEdges();
1037:             }
1038:             calcBounds();
1039: 
1040:             // adapted from SelectionWButtons from line 280
1041:             // calls a helper method to avoid this edge disappearing
1042:             // if the new source and dest are the same node.
1043:             if (newSourceFig == newDestFig) {
1044: 
1045:                 layoutThisToSelf();
1046:             }
1047: 
1048:         }
1049: 
1050:         return true;
