355:     /**
356:      * @param isVisible true if the attribute compartment is visible
357:      */
358:     public void setAttributesVisible(boolean isVisible) {
359:         Rectangle rect = getBounds();
360:         int h;
361:     	if (isCheckSize()) {
362:     	    h = ((ROWHEIGHT  
363:                 * Math.max(1, getAttributesFig().getFigs(null).size() - 1) + 2)
364:                 * rect.height
365:                 / getMinimumSize().height);
366:         } else {
367:             h = 0;
368:         }
369:         if (getAttributesFig().isVisible()) {
370:             if (!isVisible) {  // hide compartment
371:                 damage();
372:                 Iterator it = getAttributesFig().getFigs(null).iterator();
373:                 while (it.hasNext()) {
374:                     ((Fig) (it.next())).setVisible(false);
375:                 }
376:                 getAttributesFig().setVisible(false);
377:                 Dimension aSize = this.getMinimumSize();
378:                 setBounds(rect.x, rect.y,
379: 			  (int) aSize.getWidth(), (int) aSize.getHeight());
380:             }
381:         } else {
382:             if (isVisible) { // show compartement
383:                 Iterator it = getAttributesFig().getFigs(null).iterator();
384:                 while (it.hasNext()) {
385:                     ((Fig) (it.next())).setVisible(true);
386:                 }
387:                 getAttributesFig().setVisible(true);
388:                 Dimension aSize = this.getMinimumSize();
389:                 setBounds(rect.x, rect.y,
390: 			  (int) aSize.getWidth(), (int) aSize.getHeight());
391:                 damage();
392:             }
393:         }
394:     }
