559:         int key = ke.getKeyCode();
560:         if (key == KeyEvent.VK_UP || key == KeyEvent.VK_DOWN) {
561:             CompartmentFigText ft = unhighlight();
562:             if (ft != null) {
563:                 int i = new Vector(getAttributesFig().getFigs(null))
564:                                             .indexOf(ft);
565:                 FigGroup fg = getAttributesFig();
566:                 if (i == -1) {
567:                     i = new Vector(getOperationsFig().getFigs(null))
568:                                             .indexOf(ft);
569:                     fg = getOperationsFig();
570:                 }
571:                 if (i != -1) {
572:                     if (key == KeyEvent.VK_UP) {
573:                         ft = (CompartmentFigText)
574: 			    getPreviousVisibleFeature(fg, ft, i);
575:                     } else {
576:                         ft = (CompartmentFigText)
577: 			    getNextVisibleFeature(fg, ft, i);
578:                     }
579:                     if (ft != null) {
580:                         ft.setHighlighted(true);
581:                         highlightedFigText = ft;
582:                         return;
583:                     }
584:                 }
585:             }
586:         } else if (key == KeyEvent.VK_ENTER && highlightedFigText != null) {
587:             highlightedFigText.startTextEditor(ke);
588:             ke.consume();
589:             return;
590:         }
591:         super.keyPressed(ke);
592:     }
