597:     /**
598:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#textEdited(org.tigris.gef.presentation.FigText)
599:      */
600:     protected void textEdited(FigText ft) throws PropertyVetoException {
601:         super.textEdited(ft);
602:         Object cls = /*(MClassifier)*/ getOwner();
603:         if (cls == null) {
604:             return;
605:         }
606:         int i = new Vector(getAttributesFig().getFigs(null)).indexOf(ft);
607:         if (i != -1) {
608:             highlightedFigText = (CompartmentFigText) ft;
