650:         if (fgVec == null || i < 1) {
651:             return null;
652:         }
653:         FigText ft2 = null;
654:         // TODO: come GEF V 0.12 use getFigs returning an array
655:         Vector v = new Vector(fgVec.getFigs(null));
656:         if (i >= v.size() || !((FigText) v.elementAt(i)).isVisible()) {
657:             return null;
658:         }
659:         do {
660:             i--;
661:             while (i < 1) {
662:                 fgVec = (fgVec == getAttributesFig()) 
663:                     ? getOperationsFig() 
664:                     : getAttributesFig();
665:                 v = new Vector(fgVec.getFigs(null));
666:                 i = v.size() - 1;
667:             }
668:             ft2 = (FigText) v.elementAt(i);
669:             if (!ft2.isVisible()) {
670:                 ft2 = null;
671:             }
672:         } while (ft2 == null);
673:         return ft2;
674:     }
