825:     /**
826:      * @see org.argouml.uml.diagram.ui.FigNodeModelElement#updateStereotypeText()
827:      */
828:     protected void updateStereotypeText() {
829: 
830:         Object me = /*(MModelElement)*/ getOwner();
831: 
832:         if (me == null) {
833:             return;
834:         }
835: 
836:         Rectangle rect = getBounds();
837:         Object stereo = null;
838:         if (ModelFacade.getStereotypes(me).size() > 0) {
839:             stereo = ModelFacade.getStereotypes(me).iterator().next();
840:         }
841: 
842:         if ((stereo == null)
843:                 || (ModelFacade.getName(stereo) == null)
844:                 || (ModelFacade.getName(stereo).length() == 0))	{
845: 
846:             if (getStereotypeFig().isVisible()) {
847:                 getFigAt(BLINDER_POSN).setVisible(false);
848:                 getStereotypeFig().setVisible(false);
849:                 rect.y += STEREOHEIGHT;
850:                 rect.height -= STEREOHEIGHT;
851:                 setBounds(rect.x, rect.y, rect.width, rect.height);
852:                 calcBounds();
853:             }
854:         } else {
855:             setStereotype(Notation.generateStereotype(this, stereo));
856: 
857:             if (!getStereotypeFig().isVisible()) {
858:                 getFigAt(BLINDER_POSN).setVisible(true);
859:                 getStereotypeFig().setVisible(true);
860: 
861:                 // Only adjust the stereotype height if we are not newly
862:                 // created. This gets round the problem of loading classes with
863:                 // stereotypes defined, which have the height already including
864:                 // the stereotype.
865: 
866:                 if (!newlyCreated) {
867:                     rect.y -= STEREOHEIGHT;
868:                     rect.height += STEREOHEIGHT;
869:                     setBounds(rect.x, rect.y, rect.width, rect.height);
870:                     calcBounds();
871:                 }
872:             }
873:         }
874: 
875:         // Whatever happened we are no longer newly created, so clear the
876:         // flag. Then set the bounds for the rectangle we have defined.
877:         newlyCreated = false;
878:     }
