85:     private Orientation _ignoreSplitters;
86: 
87:     /**
88:      * Construct a new LabelledLayout.
89:      */
90:     public LabelledLayout() {
91:         _ignoreSplitters = Horizontal.getInstance();
92:         _hgap = 0;
93:         _vgap = 0;
94:     }
95: 
96:     /**
97:      * Construct a new LabelledLayout with the given orientation.
98:      * The ignoreSplitters determines how panels are layed out. A horizontal ignoreSplitters
99:      * has panels to the right of the previous. Vertical orientation has panels layed
100:      * out below the previous
101:      */
102:     public LabelledLayout(Orientation orientation) {
103:         _ignoreSplitters = orientation;
104:         _hgap = 0;
105:         _vgap = 0;
106:     }
107: 
108:     /**
109:      * Construct a new horizontal LabelledLayout with the specified cell spacing.
110:      */
111:     public LabelledLayout(int hgap, int vgap) {
112:         _ignoreSplitters = Horizontal.getInstance();
113:         _hgap = hgap;
114:         _vgap = vgap;
115:     }
116: 
117:     /** 
118:      * Adds the specified component with the specified name to the layout. This is included
119:      * to satisfy the LayoutManager interface but is not actually used in this layout
120:      * implementation.
121:      *
122:      * @param name the name of the component
123:      * @param comp the component to be added
124:      */
125:     public void addLayoutComponent(String name, Component comp) {
126:     }
127: 
128:     /** 
129:      * Removes the specified component with the specified name from the layout. This is included
130:      * to satisfy the LayoutManager interface but is not actually used in this layout
131:      * implementation.
132:      *
133:      * @param name the name of the component
134:      */
135:     public void removeLayoutComponent(Component comp) {
136:     }
137: 
138:     /**
139:      * Determines the preferred size of the container argument using this labelled layout.
140:      * The preferred size is that all child components are in one section at their own preferred size
141:      * with gaps and border indents.
142:      */
143:     public Dimension preferredLayoutSize(Container parent) {
144:         synchronized (parent.getTreeLock()) {
145:             Insets insets = parent.getInsets();
146:             int preferredWidth = 0;
147:             int preferredHeight = 0;
148:             int widestLabel = 0;
149:             ArrayList rowHeights = new ArrayList();
150: 
151:             int componentCount = parent.getComponentCount();
152:             for (int i = 0; i < componentCount; ++i) {
153:                 Component childComp = parent.getComponent(i);
154:                 if (childComp.isVisible()) {
155:                     int childHeight = (int) childComp.getPreferredSize().getHeight();
156:                     if (childComp instanceof JLabel) {
157:                         JLabel jlabel = (JLabel) childComp;
158:                         if (widestLabel < jlabel.getPreferredSize().getWidth()) {
159:                             widestLabel = (int) jlabel.getPreferredSize().getWidth();
160:                         }
161:                         childComp = jlabel.getLabelFor();
162:                         int childWidth = (int) childComp.getPreferredSize().getWidth();
163:                         if (childWidth > preferredWidth) {
164:                             preferredWidth = childWidth;
165:                         }
166: 
167:                         if (childHeight < jlabel.getPreferredSize().getHeight()) {
168:                             childHeight = (int) jlabel.getPreferredSize().getHeight();
169:                         }
170:                     }
171:                     preferredHeight += childHeight + _vgap;
172:                 }
173:             }
174:             preferredWidth += insets.left + widestLabel + insets.right;
175:             preferredHeight += insets.top + insets.bottom;
176:             return new Dimension(insets.left + widestLabel + preferredWidth + insets.right, preferredHeight);
177:         }
178:     }
