84:      * The class name of Swing's default look and feel (will be used if
85:      * the LookAndFeel property is null).
86:      **/
87:     private String defaultLookAndFeelClassName;
88: 
89:     /**
90:      * get the single instance of the LookAndFeelMgr
91:      * @return the single instance of the LookAndFeelMgr
92:      */
93:     public static LookAndFeelMgr getInstance() {
94:         return SINGLETON;
95:     }
96: 
97:     /** Creates a new instance of LookAndFeelMgr. */
98:     private LookAndFeelMgr() {
99:         LookAndFeel laf = UIManager.getLookAndFeel();
100:         if (laf != null) {
101:             defaultLookAndFeelClassName = laf.getClass().getName();
102:         }
103:         else {
104:             defaultLookAndFeelClassName = null;
105:         }
106:     }
107: 
108:     /**
109:      * Sets the appearance of the UI using the current values of
110:      * the LookAndFeel and Theme properties.
111:      **/
112:     public void initializeLookAndFeel() {
113:         setLookAndFeel(getCurrentLookAndFeelClassName());
114:         setTheme(getMetalTheme(getCurrentThemeClassName()));
115:     }
116: 
117:     /**
118:      * Detecting the theme from the command line.
119:      *
120:      * @param arg the argument from the command line
121:      * @return the theme
122:      */
123:     public String getThemeFromArg(String arg) {
124:         if (arg.equalsIgnoreCase("-big")) {
125:             return BIG_THEME.getClass().getName();
126:         }
127:         else if (arg.equalsIgnoreCase("-huge")) {
128:             return HUGE_THEME.getClass().getName();
129:         }
130:         return null;
131:     }
132: 
133:     /**
134:      * Outputs command-line arguments supported by this class.
135:      **/
136:     public void printThemeArgs() {
137:         System.err.println("  -big            use big fonts");
138:         System.err.println("  -huge           use huge fonts");
139:     }
