162:      **/
163:     public String[] getAvailableThemeNames() {
164:         String[] names = new String[LookAndFeelMgr.THEMES.length];
165:         for (int i = 0; i < THEMES.length; ++i) {
166:             names[i] = THEMES[i].getName();
167:         }
