255:         if (currentLookAndFeel == null) {
256:             return DEFAULT_KEY;
257:         } 
258:         String name = null;
259:         
260:         UIManager.LookAndFeelInfo[] lafs =
261:             UIManager.getInstalledLookAndFeels();
262:         for (int i = 0; i < lafs.length; ++i) {
263:             if (lafs[i].getClassName().equals(currentLookAndFeel)) {
264:                 name = lafs[i].getName();
265:             }
266:         }
