170:      * org.argouml.ui.targetmanager.TargetManager}.
171:      */
172:     public void setTarget(Object newTarget) {
173: 
174:         if (!(newTarget instanceof UMLDiagram)) {
175:             _shouldBeEnabled = false;
176:             // This is perfectly normal and happens among other things
177:             // within the call to setDiagram (below).
178:             LOG.debug("target is null in set target or "
179: 		      + "not an instance of UMLDiagram");
180:             return;
181:         }
