434: class ArgoEditor extends Editor {
435:     
436:     private RenderingHints  _argoRenderingHints;
437:         
438:     public ArgoEditor(Diagram d) {
439: 	super(d);
440:         setupRenderingHints();
441:     }
442:         
443:     /**
444:      * @deprecated in 0.16 in favour of ArgoEditor(GraphModel gm, JComponent c)
445:      */
446:     public ArgoEditor(GraphModel gm, Component c) {
447: 	super(gm, (JComponent) c);
448:         setupRenderingHints();
449:     }
450: 
451:     public ArgoEditor(GraphModel gm, JComponent c) {
452: 	super(gm, c);
453:         setupRenderingHints();
454:     }
455: 
456:     /**
457:      * @see java.awt.event.MouseListener#mouseEntered(java.awt.event.MouseEvent)
458:      */
459:     public void mouseEntered(MouseEvent me) {
460: 	if (getActiveTextEditor() != null) {
461:             getActiveTextEditor().requestFocus();         
462:         }
463: 	translateMouseEvent(me);
464: 	Globals.curEditor(this);
465: 	pushMode((FigModifyingMode) Globals.mode());
466: 	setUnderMouse(me);
467: 	_modeManager.mouseEntered(me);
468:     }
469:         
470:     /** Invoked when the mouse button has been moved (with no buttons
471:      * no down). */
472:     public void mouseMoved(MouseEvent me) {
473: 	//- RedrawManager.lock();
474: 	translateMouseEvent(me);
475: 	Globals.curEditor(this);
476: 	setUnderMouse(me);
477:         Fig currentFig = getCurrentFig();
478: 	if (currentFig != null && Globals.getShowFigTips()) {
479: 	    String tip = currentFig.getTipString(me);
480: 	    if (tip != null && (getJComponent() != null)) {
481: 	        JComponent c = getJComponent();
482: 	        if (c.getToolTipText() == null 
483: 		    || !(c.getToolTipText().equals(tip))) {
484: 	            c.setToolTipText(tip);
485: 	        }
486:             }
487: 	} else if (getJComponent() != null
488: 		   && getJComponent().getToolTipText() != null) {
489:             getJComponent().setToolTipText(null); //was ""
490: 	}
491: 
492: 	_selectionManager.mouseMoved(me);
493: 	_modeManager.mouseMoved(me);
494: 	//- RedrawManager.unlock();
495: 	//- _redrawer.repairDamage();
496:     }
497:     
498:     /**
499:      * Overridden to set Argo-specific RenderingHints to determine whether
500:      * or not antialiasing should be turned on.
501:      */
502:     public synchronized void paint(Graphics g) {
503:         if (!shouldPaint())
504:             return;
505: 
506:         if (g instanceof Graphics2D) {
507:             Graphics2D g2 = (Graphics2D) g;
508:             g2.setRenderingHints(_argoRenderingHints);
509: 	    double scale = getScale();
510:             g2.scale(scale, scale);
511:         }
512:         getLayerManager().paint(g);
513:         //getLayerManager().getActiveLayer().paint(g);
514:         if (_canSelectElements) {
515:             _selectionManager.paint(g);
516:             _modeManager.paint(g);
517:         }        
518:     }
519:     
520:     /**
521:      * Construct a new set of RenderingHints to reflect current user
522:      * settings.
523:      */
524:     private void setupRenderingHints() {
525:         _argoRenderingHints = new RenderingHints(null);
526: 
527:         _argoRenderingHints.put(RenderingHints.KEY_FRACTIONALMETRICS, 
528:             RenderingHints.VALUE_FRACTIONALMETRICS_ON);
529:         
530:         if (Configuration.getBoolean(Argo.KEY_SMOOTH_EDGES, false)) {
531:             _argoRenderingHints.put(RenderingHints.KEY_RENDERING, 
532:                 RenderingHints.VALUE_RENDER_QUALITY);
533:             _argoRenderingHints.put(RenderingHints.KEY_ANTIALIASING, 
534:                 RenderingHints.VALUE_ANTIALIAS_ON);
535:             _argoRenderingHints.put(RenderingHints.KEY_TEXT_ANTIALIASING, 
536:                 RenderingHints.VALUE_TEXT_ANTIALIAS_ON);        
537:         }
538:         else {
539:             _argoRenderingHints.put(RenderingHints.KEY_RENDERING, 
540:                 RenderingHints.VALUE_RENDER_SPEED);
541:             _argoRenderingHints.put(RenderingHints.KEY_ANTIALIASING, 
542:                 RenderingHints.VALUE_ANTIALIAS_OFF);
543:             _argoRenderingHints.put(RenderingHints.KEY_TEXT_ANTIALIASING, 
544:                 RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);        
545:         }
546:     }
547: }
