63: /**
64:  * This class provides support for writing a UML diagram for argo using
65:  * the GEF framework.
66:  * <p>It adds common buttons, a namespace, capability
67:  * to delete itself when its namespace is deleted, some help
68:  * with creating a valid diagram name.
69:  *
70:  */
71: public abstract class UMLDiagram
72:     extends ArgoDiagram
73:     implements MElementListener {
74: 
75:     private static final Logger LOG = Logger.getLogger(UMLDiagram.class);
76: 
77:     ////////////////////////////////////////////////////////////////
78:     // actions for toolbar
79:     
80:     /**
81:      * Tool to add a comment node.
82:      */
83:     protected static Action actionComment =
84: 	new RadioAction(new CmdCreateNode(ModelFacade.COMMENT, "Note"));
85: 
86:     /**
87:      * Tool to create an relationship between a comment node and some other node
88:      * using a polyedge.<p>
89:      */
90:     protected static Action _actionCommentLink = new RadioAction(
91:         new CmdSetMode(
92:             ModeCreatePolyEdge.class,  
93:             "edgeClass",
94:             CommentEdge.class,
95:             "CommentLink"));
96: 
97: 
98:     protected static Action actionSelect =
99:         new CmdSetMode(ModeSelect.class, "Select");
100: 
101:     protected static Action actionBroom =
102:         new CmdSetMode(ModeBroom.class, "Broom");
103: 
104:     protected static Action _actionRectangle =
105:         new RadioAction(new CmdSetMode(ModeCreateFigRect.class, "Rectangle",
106:         Translator.localize("misc.primitive.rectangle")));
107: 
108:     protected static Action _actionRRectangle =
109:         new RadioAction(new CmdSetMode(ModeCreateFigRRect.class, "RRect",
110:         Translator.localize("misc.primitive.rounded-rectangle")));
111: 
112:     protected static Action _actionCircle =
113:         new RadioAction(new CmdSetMode(ModeCreateFigCircle.class, "Circle",
114:         Translator.localize("misc.primitive.circle")));
115: 
116:     protected static Action _actionLine =
117:         new RadioAction(new CmdSetMode(ModeCreateFigLine.class, "Line",
118:         Translator.localize("misc.primitive.line")));
119: 
120:     protected static Action _actionText =
121:         new RadioAction(new CmdSetMode(ModeCreateFigText.class, "Text",
122:         Translator.localize("misc.primitive.text")));
123: 
124:     protected static Action _actionPoly =
125:         new RadioAction(new CmdSetMode(ModeCreateFigPoly.class, "Polygon",
126:         Translator.localize("misc.primitive.polygon")));
127: 
128:     protected static Action _actionSpline =
129:         new RadioAction(new CmdSetMode(ModeCreateFigSpline.class, "Spline",
130:         Translator.localize("misc.primitive.spline")));
131: 
132:     protected static Action _actionInk =
133:         new RadioAction(new CmdSetMode(ModeCreateFigInk.class, "Ink",
134:         Translator.localize("misc.primitive.ink")));
135: 
136:     ////////////////////////////////////////////////////////////////
137:     // instance variables
138:     private Object namespace;
139:     private DiagramInfo diagramName = new DiagramInfo(this);
140: 
141:     private JToolBar toolBar;
142: 
143:     ////////////////////////////////////////////////////////////////
144:     // constructors
145: 
146:     /**
147:      * constructor
148:      */
149:     public UMLDiagram() {
150:         super();
151:     }
152: 
153:     /**
154:      * @param ns the UML namespace
155:      */
156:     public UMLDiagram(Object ns) {
157:         this();
158: 
159:         if (!ModelFacade.isANamespace(ns))
160:             throw new IllegalArgumentException();
161: 
162:         setNamespace(ns);
163:     }
164: 
165:     /**
166:      * @param name the name of the diagram
167:      * @param ns the UML namespace
168:      */
169:     public UMLDiagram(String name, Object ns) {
170:         this(ns);
171:         try {
172:             setName(name);
173:         } catch (PropertyVetoException pve) {
174:             LOG.fatal("Name not allowed in construction of diagram");
175:         }
176:     }
177: 
178:     /**
179:      * @see org.tigris.gef.base.Diagram#initialize(java.lang.Object)
180:      */
181:     public void initialize(Object owner) {
182:         super.initialize(owner);
183:         if (org.argouml.model.ModelFacade.isANamespace(owner))
184:             setNamespace(owner);
185:         else
186:             LOG.debug("unknown object in UMLDiagram initialize:" + owner);
187:     }
188: 
189:     ////////////////////////////////////////////////////////////////
190:     // accessors
191: 
192:     /**
193:      * @return the namespace for the diagram
194:      */
195:     public Object getNamespace() {
196:         return namespace;
197:     }
198: 
199:     /**
200:      * sets the namespace of the Diagram, and
201:      * adds the diagram as a listener of its namspace in the UML model.
202:      * (so that it can delete itself when the model element is deleted).
203:      *
204:      * @param ns the namespace
205:      */
206:     public void setNamespace(Object ns) {
207:         if (!ModelFacade.isANamespace(ns)) {
208:             LOG.error("Not a namespace");
209:             LOG.error(ns);
210:             throw new IllegalArgumentException("Given object not a namespace");
211:         }
212:         namespace = ns;
213:         // add the diagram as a listener to the namspace so
214:         // that when the namespace is remove()d the diagram is deleted also.
215:         UmlModelEventPump.getPump().addModelEventListener(
216:             this,
217:             namespace,
218:             UmlModelEventPump.REMOVE);
219:     }
220: 
221:     /**
222:      * @see org.tigris.gef.base.Diagram#getClassAndModelID()
223:      */
224:     public String getClassAndModelID() {
225:         String s = super.getClassAndModelID();
226:         if (getOwner() == null)
227:             return s;
228:         String id = ModelFacade.getUUID(getOwner());
229:         return s + "|" + id;
230:     }
231: 
232:     // TODO: should be overwritten by each subclass of UMLDiagram
233: 
234:     /**
235:      * @return the namespace
236:      */
