405:     /**
406:      * Removes the UMLDiagram and all the figs on it as listener to 
407:      * UmlModelEventPump. Is called by setTarget in TabDiagram to improve 
408:      * performance. 
409:      *
410:      */
411:     public void removeAsTarget() {
412:         Enumeration elems = elements();
413:         UmlModelEventPump pump = UmlModelEventPump.getPump();
414:         while (elems.hasMoreElements()) {
415:             Object o = elems.nextElement();
416:             if (ModelFacade.isAElementListener(o)) {
417:                 MElementListener listener = (MElementListener) o;
418:                 Fig fig = (Fig) o;
419:                 pump.removeModelEventListener(listener, fig.getOwner());
420:             }
421:         }
422:         pump.removeModelEventListener(this, getNamespace());
423: 
424:     }
425: 
426:     /**
427:      * Adds the UMLDiagram and all the figs on it as listener to
428:      * UmlModelEventPump.  Together with removeAsModelListener this is
429:      * a performance improvement.
430:      *
431:      */
432:     public void setAsTarget() {
433:         Enumeration elems = elements();
434:         while (elems.hasMoreElements()) {
435:             Fig fig = (Fig) elems.nextElement();
436:             if (org.argouml.model.ModelFacade.isAElementListener(fig)) {
437:                 Object owner = fig.getOwner();
438:                 // pump.addModelEventListener((MElementListener)fig, owner);
439:                 // this will make sure all the correct event listeners are set. 
440:                 fig.setOwner(null);
441:                 fig.setOwner(owner);
442:             }
443:         }
444:     }
