472:   protected Component createPanels() {
473:     _topSplit = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT, _navPane, _multiPane);
474:     _botSplit = new JSplitPane(JSplitPane.HORIZONTAL_SPLIT,
475: 			       _toDoPane, _detailsPane);
476:     _mainSplit = new JSplitPane(JSplitPane.VERTICAL_SPLIT, _topSplit, _botSplit);
477:     _topSplit.setDividerSize(2);
478:     _topSplit.setDividerLocation(270);
479:     _botSplit.setDividerSize(2);
480:     _mainSplit.setDividerSize(2);
481:     //_botSplit.setOneTouchExpandable(true);
482:     return _mainSplit;
483:   }
