51:  * @author Bob Tarling
52:  */
53: public abstract class FigFeaturesCompartment extends FigCompartment {
54: 
55:     /**
56:      * Logger.
57:      */
58:     private static final Logger LOG = Logger.getLogger(FigCompartment.class);
59: 
60:     private FigSeperator compartmentSeperator;
61: 
62:     /**
63:      * The constructor. <p>
64:      * 
65:      * Two figs are added to this FigGroup:
66:      * The bigPort (i.e. a box that encloses all compartments),
67:      * and a seperator.
68:      *
69:      * @param x x
70:      * @param y y
71:      * @param w width
72:      * @param h height
73:      */
74:     public FigFeaturesCompartment(int x, int y, int w, int h) {
75:         super(x, y, w, h); // This adds bigPort, i.e. number 1
76:         compartmentSeperator = new FigSeperator(10, 10, 11);
77:         addFig(compartmentSeperator); // number 2
78:     }
79: 
80:     /**
81:      * @return separator figure
82:      */
83:     protected FigSeperator getSeperatorFig() {
84:         return compartmentSeperator;
85:     }
86: 
87:     /**
88:      * If a features compartment is set to invisible then remove all its
89:      * children.
90:      * This is to save on resources and increase efficiency as multiple
91:      * figs need not exist and be resized, moved etc if they are not visible.
92:      * If a compartment is later made visible the its child figs are rebuilt
93:      * from the model.
94:      * {@inheritDoc}
95:      */
96:     public void setVisible(boolean visible) {
97:         if (isVisible() == visible) {
98:             return;
99:         }
100:         super.setVisible(visible);
101:         if (visible) {
102:             populate();
103:         } else {
104:             for (int i = getFigs().size() - 1; i >= 0; --i) {
105:                 Fig f = getFigAt(i);
106:                 if (f instanceof FigFeature) {
107:                     removeFig(f);
108:                 }
109:             }
110:         }
111:     }
112: 
113:     /*
114:      * @see org.tigris.gef.presentation.FigGroup#addFig(org.tigris.gef.presentation.Fig)
115:      */
116:     public void addFig(Fig fig) {
117:         if (fig != getBigPort()
118:                 && !(fig instanceof FigFeature)
119:                 && !(fig instanceof FigSeperator)) {
120:             LOG.error("Illegal Fig added to a FigFeature");
121:             throw new IllegalArgumentException(
122:                     "A FigFeaturesCompartment can only contain FigFeatures, "
123:                     + "received a " + fig.getClass().getName());
124:         }
125:         super.addFig(fig);
126:     }
127: 
128:     /**
129:      * @return the collection of UML objects 
130:      *              on which this compartment of features is based
131:      */
132:     protected abstract Collection getUmlCollection();
133: 
134:     /**
135:      * @return the type of the notationprovider 
136:      *              used to handle the text in the compartment 
137:      */
138:     protected abstract int getNotationType();
139:     
140:     /**
141:      * Fills the Fig by adding all figs within.
142:      */
143:     public void populate() {
144:         if (!isVisible()) {
145:             return;
146:         }
147: 
148:         Fig bigPort = this.getBigPort();
149:         int xpos = bigPort.getX();
150:         int ypos = bigPort.getY();
151: 
152:         List figs = getElementFigs();
153:         // We remove all of them:
154:         Iterator i = figs.iterator();
155:         while (i.hasNext()) {
156:             Fig f = (Fig) i.next();
157:             removeFig(f);    
158:         }
159: 
160:         // We are going to add the ones still valid & new ones
161:         // in the right sequence:
162:         FigSingleLineText comp = null;
163:         try {
164:             Collection umlObjects = getUmlCollection();
165:             int acounter = -1;
166:             Iterator iter = umlObjects.iterator();
167:             while (iter.hasNext()) {
168:                 Object umlObject = iter.next();
169:                 comp = findCompartmentFig(figs, umlObject);
170:                 acounter++;                
171: 
172:                 NotationProvider np = 
173:                     NotationProviderFactory2.getInstance()
174:                         .getNotationProvider(getNotationType(), umlObject);
175: 
176:                 // If we don't have a fig for this feature, we'll need to add
177:                 // one. We set the bounds, but they will be reset later.
178:                 if (comp == null) {
179:                     comp = createFigText(
180:                                 xpos + 1,
181:                                 ypos + 1 + acounter
182:                                 * FigNodeModelElement.ROWHEIGHT,
183:                                 0,
184:                                 FigNodeModelElement.ROWHEIGHT - 2,
185:                                 bigPort,
186:                                 np);
187:                     // bounds not relevant here
188:                     comp.setOwner(umlObject);
189:                     
