517: 
518:         /* Check if multiple items are selected: */
519:         if (TargetManager.getInstance().getTargets().size() == 1) {
520:             ToDoList list = Designer.theDesigner().getToDoList();
521:             Vector items =
522:                     (Vector) list.elementsForOffender(getOwner()).clone();
523:             if (items != null && items.size() > 0) {
524:                 ArgoJMenu critiques = new ArgoJMenu("menu.popup.critiques");
525:                 ToDoItem itemUnderMouse = hitClarifier(me.getX(), me.getY());
526:                 if (itemUnderMouse != null) {
527:                     critiques.add(new ActionGoToCritique(itemUnderMouse));
528:                     critiques.addSeparator();
529:                 }
530:                 int size = items.size();
531:                 for (int i = 0; i < size; i++) {
532:                     ToDoItem item = (ToDoItem) items.elementAt(i);
533:                     if (item != itemUnderMouse) {
534:                         critiques.add(new ActionGoToCritique(item));
535:                     }
536:                 }
537:                 popUpActions.insertElementAt(new JSeparator(), 0);
538:                 popUpActions.insertElementAt(critiques, 0);
539:             }
540: 
541:             // Add stereotypes submenu
542:             Action[] stereoActions =
543:                 StereotypeUtility.getApplyStereotypeActions(getOwner());
544:             if (stereoActions != null) {
545:                 popUpActions.insertElementAt(new JSeparator(), 0);
546:                 ArgoJMenu stereotypes =
547:                     new ArgoJMenu("menu.popup.apply-stereotypes");
548:                 for (int i = 0; i < stereoActions.length; ++i) {
549:                     stereotypes.addCheckItem(stereoActions[i]);
550:                 }
551:                 popUpActions.insertElementAt(stereotypes, 0);
552:             }
553:         }
554: 
555:         return popUpActions;
556:     }
