616:     public void setEnclosingFig(Fig newEncloser) {
617: 	Fig oldEncloser = encloser;
618: 	super.setEnclosingFig(newEncloser);
619: 	if (newEncloser != oldEncloser) {
620: 	    Object owningModelelement = null;
621: 	    if (newEncloser == null && isVisible()) {
622: 	        // If we are not visible most likely we're being deleted.
623: 
624: 		// moved outside another fig onto the diagram canvas
625: 		Project currentProject =
626: 		    ProjectManager.getManager().getCurrentProject();
627:                 ArgoDiagram diagram = currentProject.getActiveDiagram();
628:                 // TODO: Who said this was about the active diagram?
629:                 if (diagram instanceof UMLDiagram
630: 			&& ((UMLDiagram) diagram).getNamespace() != null) {
631:                     owningModelelement = ((UMLDiagram) diagram).getNamespace();
