635: 	    } else if (newEncloser != null
636:                     && Model.getFacade()
637:                             .isAModelElement(newEncloser.getOwner())) {
638:                 owningModelelement = newEncloser.getOwner();
639:             }
640:             if (owningModelelement != null
641: 		&& getOwner() != null
642: 		&& (!Model.getModelManagementHelper()
643: 		    .isCyclicOwnership(owningModelelement, getOwner()))
644: 		&& ((Model.getCoreHelper()
645: 			.isValidNamespace(getOwner(),
646: 					  owningModelelement)))) {
647:                 Model.getCoreHelper().setModelElementContainer(getOwner(),
648: 						     owningModelelement);
