650:                  * i.e. issue 2151
651:                  */
652:             }
653:         }
654: 	if (newEncloser != encloser) {
655: 	    if (encloser instanceof FigNodeModelElement) {
656: 		((FigNodeModelElement) encloser).removeEnclosedFig(this);
657:             }
658: 	    if (newEncloser instanceof FigNodeModelElement) {
659: 		((FigNodeModelElement) newEncloser).addEnclosedFig(this);
660:             }
661: 	}
662:         encloser = newEncloser;
663:     }
