715:     /*
716:      * Overridden to paint shadows. This method supports painting shadows
717:      * for any FigNodeModelElement. Any Figs that are nested within the
718:      * FigNodeModelElement will be shadowed.<p>
719:      *
720:      * TODO: If g is not a Graphics2D shadows cannot be painted. This is
721:      * a problem when saving the diagram as SVG.
722:      *
723:      * @see org.tigris.gef.presentation.Fig#paint(java.awt.Graphics)
724:      */
725:     public void paint(Graphics g) {
726:         if (shadowSize > 0
727: 	        && g instanceof Graphics2D) {
728:             int width = getWidth();
729:             int height = getHeight();
730:             int x = getX();
731:             int y = getY();
732: 
733:             /* Only create a new shadow image if figure size has changed.
734:              * Which does not catch all cases:
735:              * consider show/hide toggle of a stereotype on a package:
736:              * in this case the total size remains, but the notch
737:              * at the corner increases/decreases.
738:              * Hence also check the "forceRepaint" attribute.
739:              */
740:             if (width != cachedWidth
741:                     || height != cachedHeight
742:                     || forceRepaint) {
743:                 forceRepaint = false;
744: 
745:                 cachedWidth = width;
746:                 cachedHeight = height;
747: 
748:                 BufferedImage img =
749: 		    new BufferedImage(width + 100,
750: 				      height + 100,
751: 				      BufferedImage.TYPE_INT_ARGB);
752: 
753:                 // Paint figure onto offscreen image
754:                 Graphics ig = img.getGraphics();
755:                 ig.translate(50 - x, 50 - y);
756:                 super.paint(ig);
757: 
758:                 // Apply two filters to the image:
759:                 // 1. Apply LookupOp which converts all pixel data in the
760:                 //    figure to the same shadow color.
761:                 // 2. Apply ConvolveOp which creates blurred effect around
762:                 //    the edges of the shadow.
763:                 shadowImage =
764: 		    SHADOW_CONVOLVE_OP.filter(
765: 			    SHADOW_LOOKUP_OP.filter(img, null), null);
766:             }
767: 
768:             // Paint shadow image onto canvas
769:             Graphics2D g2d = (Graphics2D) g;
770:             g2d.drawImage(
771:                 shadowImage,
772:                 null,
773:                 x + shadowSize - 50,
774:                 y + shadowSize - 50);
775:         }
776: 
777:         // Paint figure on top of shadow
778:         super.paint(g);
779:     }
