781:     /**
782:      * Displays visual indications of pending ToDoItems.
783:      * Please note that the list of advices (ToDoList) is not the same
784:      * as the list of element known by the FigNode (_figs). Therefore,
785:      * it is necessary to check if the graphic item exists before drawing
786:      * on it. See ClAttributeCompartment for an example.
787:      * @param g the graphics device
788:      * @see org.argouml.uml.cognitive.critics.ClAttributeCompartment
789:      */
790:     public void paintClarifiers(Graphics g) {
791:         int iconX = getX();
792:         int iconY = getY() - 10;
793:         ToDoList list = Designer.theDesigner().getToDoList();
794:         Vector items = list.elementsForOffender(getOwner());
795:         int size = items.size();
796:         for (int i = 0; i < size; i++) {
797:             ToDoItem item = (ToDoItem) items.elementAt(i);
798:             Icon icon = item.getClarifier();
799:             if (icon instanceof Clarifier) {
800:                 ((Clarifier) icon).setFig(this);
801:                 ((Clarifier) icon).setToDoItem(item);
802:             }
803:             if (icon != null) {
804:                 icon.paintIcon(null, g, iconX, iconY);
805:                 iconX += icon.getIconWidth();
806:             }
807:         }
808:         items = list.elementsForOffender(this);
809:         size = items.size();
810:         for (int i = 0; i < size; i++) {
811:             ToDoItem item = (ToDoItem) items.elementAt(i);
812:             Icon icon = item.getClarifier();
813:             if (icon instanceof Clarifier) {
814:                 ((Clarifier) icon).setFig(this);
815:                 ((Clarifier) icon).setToDoItem(item);
816:             }
817:             if (icon != null) {
