824:     /**
825:      * @param x the x of the hit
826:      * @param y the y of the hit
827:      * @return the todo item of which the clarifier has been hit
828:      */
829:     public ToDoItem hitClarifier(int x, int y) {
830:         int iconX = getX();
831:         ToDoList list = Designer.theDesigner().getToDoList();
832:         Vector items = list.elementsForOffender(getOwner());
833:         int size = items.size();
834:         for (int i = 0; i < size; i++) {
835:             ToDoItem item = (ToDoItem) items.elementAt(i);
836:             Icon icon = item.getClarifier();
837:             int width = icon.getIconWidth();
838:             if (y >= getY() - 15
839:                     && y <= getY() + 10
840:                     && x >= iconX
841:                     && x <= iconX + width) {
842:                 return item;
843:             }
844:             iconX += width;
845:         }
846:         for (int i = 0; i < size; i++) {
847:             ToDoItem item = (ToDoItem) items.elementAt(i);
848:             Icon icon = item.getClarifier();
849:             if (icon instanceof Clarifier) {
850:                 ((Clarifier) icon).setFig(this);
851:                 ((Clarifier) icon).setToDoItem(item);
852:                 if (((Clarifier) icon).hit(x, y)) {
853:                     return item;
854:                 }
855:             }
856:         }
857:         items = list.elementsForOffender(this);
858:         size = items.size();
859:         for (int i = 0; i < size; i++) {
860:             ToDoItem item = (ToDoItem) items.elementAt(i);
861:             Icon icon = item.getClarifier();
862:             int width = icon.getIconWidth();
863:             if (y >= getY() - 15
864:                     && y <= getY() + 10
865:                     && x >= iconX
866:                     && x <= iconX + width) {
867:                 return item;
868:             }
869:             iconX += width;
870:         }
871:         for (int i = 0; i < size; i++) {
872:             ToDoItem item = (ToDoItem) items.elementAt(i);
873:             Icon icon = item.getClarifier();
874:             if (icon instanceof Clarifier) {
875:                 ((Clarifier) icon).setFig(this);
876:                 ((Clarifier) icon).setToDoItem(item);
877:                 if (((Clarifier) icon).hit(x, y)) {
878:                     return item;
879:                 }
880:             }
881:         }
882:         return null;
883:     }
