949:     /*
950:      * @see java.beans.PropertyChangeListener#propertyChange(java.beans.PropertyChangeEvent)
951:      */
952:     public void propertyChange(PropertyChangeEvent pve) {
953:         Object src = pve.getSource();
954:         String pName = pve.getPropertyName();
955:         if (pve instanceof DeleteInstanceEvent && src == getOwner()) {
956:             removeFromDiagram();
957:             return;
958:         }
959:         // We handle and consume editing events
960:         if (pName.equals("editing")
961:                 && Boolean.FALSE.equals(pve.getNewValue())) {
962:             try {
963:                 //parse the text that was edited
964:                 textEdited((FigText) src);
965:                 // resize the FigNode to accomodate the new text
966:                 Rectangle bbox = getBounds();
967:                 Dimension minSize = getMinimumSize();
968:                 bbox.width = Math.max(bbox.width, minSize.width);
969:                 bbox.height = Math.max(bbox.height, minSize.height);
970:                 setBounds(bbox.x, bbox.y, bbox.width, bbox.height);
971:                 endTrans();
972:             } catch (PropertyVetoException ex) {
973:                 LOG.error("could not parse the text entered. "
974: 			  + "PropertyVetoException",
975: 			  ex);
976:             }
977:         } else if (pName.equals("editing")
978:                         && Boolean.TRUE.equals(pve.getNewValue())) {
979:             textEditStarted((FigText) src);
980:         } else {
981:             super.propertyChange(pve);
982:         }
983:         if (Model.getFacade().isAModelElement(src)) {
984:             /* If the source of the event is an UML object,
985:              * e.g. the owner of this Fig (but not always only the owner
986:              * is shown, e.g. for a class, also its attributes are shown),
987:              * then the UML model has been changed.
988:              */
989:             // We catch the exception here so it is handled for all subclasses
990:             try {
991:                 modelChanged(pve);
992:             } catch (InvalidElementException e) {
993:                 LOG.debug("modelChanged method accessed deleted element ", e);
994:             }
995:         }
996:     }
