1057:     /*
1058:      * If the user double clicks on any part of this FigNode, pass it
1059:      * down to one of the internal Figs. This allows the user to
1060:      * initiate direct text editing.
1061:      *
1062:      * @see java.awt.event.MouseListener#mouseClicked(java.awt.event.MouseEvent)
1063:      */
1064:     public void mouseClicked(MouseEvent me) {
1065:         if (!readyToEdit) {
1066:             if (Model.getFacade().isAModelElement(getOwner())) {
1067:                 Model.getCoreHelper().setName(getOwner(), "");
1068:                 readyToEdit = true;
1069:             } else {
1070:                 LOG.debug("not ready to edit name");
1071:                 return;
1072:             }
1073:         }
1074:         if (me.isConsumed()) {
1075:             return;
1076:         }
1077:         if (me.getClickCount() >= 2
1078:                 && !(me.isPopupTrigger()
1079:                         || me.getModifiers() == InputEvent.BUTTON3_MASK)) {
1080:             if (getOwner() == null) {
1081:                 return;
1082:             }
1083:             Rectangle r = new Rectangle(me.getX() - 2, me.getY() - 2, 4, 4);
1084:             Fig f = hitFig(r);
1085:             if (f instanceof MouseListener && f.isVisible()) {
1086:                 ((MouseListener) f).mouseClicked(me);
1087:             } else if (f instanceof FigGroup && f.isVisible()) {
1088:                 //this enables direct text editing for sub figs of a
1089:                 //FigGroup object:
1090:                 Fig f2 = ((FigGroup) f).hitFig(r);
1091:                 if (f2 instanceof MouseListener) {
1092:                     ((MouseListener) f2).mouseClicked(me);
1093:                 } else {
1094:                     createContainedModelElement((FigGroup) f, me);
1095:                 }
1096:             }
1097:         }
1098:     }
