1188:     public String generateMultiplicityRange(MMultiplicityRange mr) {
1189: 	Integer lower = new Integer(mr.getLower());
1190: 	Integer upper = new Integer(mr.getUpper());
1191: 	if (lower == null && upper == null) return ANY_RANGE;
1192: 	if (lower == null) return "*.." + upper.toString();
1193: 	if (upper == null) return lower.toString() + "..*";
1194: 	if (lower.intValue() == upper.intValue()) return lower.toString();
1195: 	return lower.toString() + ".." + upper.toString();
1196: 
