281:     public String generateOperation(Object state, boolean documented) {
282: 
283: 	MOperation op = (MOperation) state;
284: 	String s = "";
285: 
286: 	Object cls = op.getOwner();
287: 
288: 	String nameStr = generateName(op.getName());
289: 	String clsName = generateName(op.getOwner().getName());
290: 
291: 	/*
292: 	 * Replaced 2001-09-26 STEFFEN ZSCHALER
293: 	 *
294: 	 * Was
295: 	 *
296: 	 s += DocumentationManager.getDocs(op) + "\n" + INDENT;
297: 	*/
298: 
299: 	if (documented)
300: 	    s += generateConstraintEnrichedDocComment (op) + "\n" + INDENT;
301: 
302: 	//    s += "function ";
303: 
304: 	if (!(cls instanceof MInterface)) {
305: 	    s += generateAbstractness (op);
306: 	    s += generateScope (op);
307: 	    s += generateChangeability (op);
308: 	    s += generateVisibility (op);
309: 	}
310: 	// pick out return type
311: 	MParameter rp = UmlHelper.getHelper().getCore().getReturnParameter(op);
312: 	if ( rp != null) {
313: 	    MClassifier returnType = rp.getType();
314: 
315: 	    if (returnType == null && !nameStr.equals(clsName)) {
316: 		s += " void ";
317: 	    }
318: 	    else if (returnType != null) {
319: 		s += " " + generateClassifierRef (returnType) + " ";
320: 	    }
321: 	}
322: 	else {
323: 	    //          removed since it was throwing exceptions and didn't seem to do
324: 	    //                 much,  Curt Arnold 15 Jan 2001
325: 	    //
326: 	    //		if (nameStr.equals(clsName)) s += " "; // this is a constructor!
327: 	}
328: 
329: 	// name and params
330: 	Vector params = new Vector (op.getParameters());
331: 	params.remove (rp);
332: 
333: 	s += nameStr + "(";
334: 
335: 	if (params != null) {
336: 	    boolean first = true;
337: 
338: 	    for (int i = 0; i < params.size(); i++) {
339: 		MParameter p = (MParameter) params.elementAt (i);
340: 
341: 		if (!first) s += ", ";
342: 
343: 		s += generateParameter (p);
344: 		first = false;
345: 	    }
346: 	}
347: 
348: 	s += ")";
349: 
350: 	return s;
351: 
352:     }
