130: class UMLAction extends AbstractAction {
131: 
132:   public UMLAction(String name) { this(name, true); }
133:   
134:   public UMLAction(String name, boolean global) { 
135:     super(name, loadIconResource(imageName(name), name));
136:     putValue(Action.SHORT_DESCRIPTION, name);
137:     if (global) Actions._allActions.addElement(this);
138:   }
139: 
140:   protected static ImageIcon loadIconResource(String imgName, String desc) {
141:     ImageIcon res = null;
142:     try {
143:       java.net.URL imgURL = UMLAction.class.getResource(imgName);
144:       return new ImageIcon(imgURL, desc);
145:     }
146:     catch (Exception ex) {
147:       return new ImageIcon(desc);
148:     }
149:   }
150: 
151:   protected static String imageName(String name) {
152:     return "/uci/Images/" + stripJunk(name) + ".gif";
153:   }
154:   
155: 
156:   /** Perform the work the action is supposed to do. */
157:   // needs-more-work: should actions run in their own threads?
158:   public void actionPerformed(ActionEvent e) {
159:     System.out.println("pushed " + getValue(Action.NAME));
160:     StatusBar sb = ProjectBrowser.TheInstance.getStatusBar();
161:     sb.doFakeProgress(stripJunk(getValue(Action.NAME).toString()), 100);
162:     History.TheHistory.addItem("pushed " + getValue(Action.NAME));
163:     Actions.updateAllEnabled();
164:   }
165: 
166: 
167:   public void updateEnabled(Object target) { setEnabled(shouldBeEnabled()); }
168:   public void updateEnabled() { setEnabled(shouldBeEnabled()); }
169: 
170:   /** return true if this action should be available to the user. This
171:    *  method should examine the ProjectBrowser that owns it.  Sublass
172:    *  implementations of this method should always call
173:    *  super.shouldBeEnabled first. */
174:   public boolean shouldBeEnabled() { return true; }
175: 
176: 
177:   protected static String stripJunk(String s) {
178:     String res = "";
179:     int len = s.length();
180:     for (int i = 0; i < len; i++) {
181:       char c = s.charAt(i);
182:       if (Character.isJavaLetterOrDigit(c)) res += c;
183:     }
184:     return res;
185:   }
186: } /* end class UMLAction */
