799:     /**
800:      * Prepares one part of the key for menu- or/and menuitem-mnemonics used
801:      * in menu.properties.
802:      * 
803:      * The method changes the parameter str to lower cases. Spaces in the 
804:      * parameter str are changed to hyphens.
805:      *  
806:      * @param str
807:      * @return the prepared str
808:      */
809:     private static String prepareKey(String str) {
810:     	StringBuffer strb = new StringBuffer(str.toLowerCase());
811:     	for (int i = 0; i < (strb.length() - 1); i++) {
812: 	    if (strb.charAt(i) == ' ') {
813: 		strb.setCharAt(i, '-');
814: 	    }
815:     	}
816:     	return strb.toString();
817:     }
